    -- ═══════════════════════════════════
    -- MythicTracker EJ-Boss-Namen (2.9.10)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- PartyFrame-CD-Fix + Performance (2.9.12)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- Installer Overhaul & AB Toggle (2.9.17)
    -- ═══════════════════════════════════
    -- Smart Waypoint (2.9.20)
    -- ═══════════════════════════════════
    ["wn_2920_waypoint_redirect"]       = "Smart Waypoint — cross-zone redirect: the waypoint now tracks the next path step on your current map (portal, dungeon entrance) via C_SuperTrack.GetNextWaypointForMap(), updated on SUPER_TRACKING_PATH_UPDATED and zone changes.",
    ["wn_2920_waypoint_blob"]           = "Smart Waypoint — stuck 0 m fix: the beacon now hides automatically when the player is inside the quest objective area (C_Minimap.IsInsideQuestBlob), preventing the waypoint from freezing at 0 m.",
    ["wn_2920_waypoint_label"]          = "Smart Waypoint — dynamic label: the destination now shows the redirect step description (e.g. 'Travel to Durotar') or the tracked quest title instead of a blank field.",

    -- Objective Tracker Stability (2.9.19)
    -- ═══════════════════════════════════
    ["wn_2919_antiflicker"]             = "Anti-flicker — eliminated the visible 'trembling' of the Objective Tracker caused by a feedback loop between TomoMod's bucket layout and Blizzard's native Update / MarkDirty hooks. New re-entry guard, deferred pump coalescing, and a 0.20 s post-layout silence window break the recursion.",
    ["wn_2919_collapsed_persist"]       = "Collapsed bucket persistence — quest blocks under a collapsed bucket header no longer reappear when Blizzard re-runs its layout; each block gets a one-time Show hook that re-hides it while its bucket is folded.",
    ["wn_2919_header_detection"]        = "Module header detection — accent- and case-insensitive matching (Métier / métier / MÉTIER all resolve to the same keyword) and added singular variants. Quest titles and objective lines are now explicitly excluded so the full quest description is never accidentally hidden.",
    ["wn_2919_recipe_height"]           = "Recipe block height — Profession recipe blocks no longer overlap the next quest. The deepest-descendant measurement now runs unconditionally and walks 8 levels deep to reach reagent FontStrings (TrackedRecipe → Lines → Line[i]).",
    ["wn_2919_reward_preview"]          = "Reward preview exclusion — Delves (e.g. 'La Sombrevoie'), M+ scenarios, world quest reward popups and weekly vault reward blocks (e.g. 'Halte de l'Ombre-Garde' with ilvl preview) are now skipped from the bucket system. They stay in Blizzard's native location and no longer overlap our quests.",

    -- ═══════════════════════════════════
    -- Objective Tracker Quest Buckets (2.9.18)
    -- ═══════════════════════════════════
    ["wn_2918_buckets"]                 = "Objective Tracker quest buckets — quests, world quests, weeklies, dailies, dungeons, raids, professions and achievements are now grouped into collapsible categories with colored headers and live count badges.",
    ["wn_2918_bucket_toggle"]           = "New 'Group quests into collapsible categories' checkbox in Config → Skins → Objective Tracker; disabling it instantly restores Blizzard's native module layout, no /reload required.",
    ["wn_2918_tracker_width"]           = "Tracker panel widened by 10 px so quest item icons no longer clip against the right edge.",
    ["wn_2918_layout_fix"]              = "Re-parented quest blocks now anchor both TOPLEFT and TOPRIGHT to prevent width collapse, and stale heights after collapse/expand are corrected via multi-pass layout.",

    ["wn_2917_ab_master_toggle"]        = "Action Bar master toggle — a new checkbox lets you fully disable bar management; after /reload, Blizzard's default action bars are fully restored.",
    ["wn_2917_installer_raid"]          = "Installer step 5 — Raid Frames: enable/disable, hide Blizzard frames, dispel highlights, HoT tracking, debuff and defensive icons, grid/list layout.",
    ["wn_2917_installer_coverage"]      = "Installer expanded — Skins step adds Objective Tracker, Mail, Reputation Bar; QOL step adds Auto Summon, Auto Quest, Class Reminder, Leveling Bar, Waypoint, World Quests, Frame Anchors, Profession Helper.",
    ["wn_2917_chat_skin_fix"]           = "Chat Skin fix — installer wrote to orphan key instead of the actual chatFrameSkin key.",
    ["wn_2917_talking_head_fix"]        = "HideTalkingHead fix — module now checks its DB toggle before suppressing the TalkingHead frame.",
    ["wn_2917_minimal_style"]           = "Action Bar Minimal style — the 5th skin style was missing from the Installer dropdown; now selectable.",

    -- AuctionRecipeTracker (2.9.15)
    -- ═══════════════════════════════════
    ["wn_2916_layout_fix"]              = "Stiller Fehler des Layout-Buttons behoben — bei einer Neuinstallation tat ein Klick auf 'Layout' nichts, weil das Mover-System seine Initialisierung nie abschloss. Toggle führt jetzt eine verzögerte Initialisierung via pcall durch und meldet Fehler im Chat statt still zu scheitern.",
    ["wn_2916_safe_init"]               = "Härtung der Modul-Init-Kette — jeder TomoMod-Modul-Initialize()-Aufruf wird nun über einen safeInit-Helper in xpcall eingewickelt; ein fehlerhaftes Modul bricht nicht mehr die ~45 nachfolgenden Module ab, und das verursachende Modul wird im Chat gemeldet.",
    ["wn_2916_art_total"]               = "AuctionRecipeTracker — jeder Kopf eines verfolgten Rezepts zeigt jetzt die globalen Gesamtkosten seiner Reagenzien auf der rechten Seite; wenn mindestens ein Reagenz keinen erfassten Preis hat, weist ein graues (~)-Suffix darauf hin, dass die Summe eine Teilschätzung ist.",
    ["wn_2916_avr_gui"]                 = "Auto-Verkauf/Reparatur-GUI — zwei neue Kontrollkästchen in Config → QOL → Automatisierungen erlauben die unabhängige Aktivierung der automatischen Reparatur beim Händler und des automatischen Verkaufs grauer (schlechter) Gegenstände; Einstellungen werden in TomoModDB persistiert und greifen live ohne /reload.",
    ["wn_2915_art_module"]              = "Neues QOL-Modul — AuctionRecipeTracker: Eine GUI öffnet sich automatisch beim Auktionator, wenn mindestens ein Handwerksrezept verfolgt wird; Reagenzien werden als '14x Icon Itemname Preis' angezeigt, mit Klick-zur-Suche und manuellem AH-Scan-Button.",
    ["wn_2915_art_tooltip"]             = "TomoHDV-Tooltip-Zeile — nach einem Scan zeigt jeder Item-Tooltip (Taschen, Bank, Chat-Links, Ausrüstung) den gespeicherten Stückpreis sowie den gesamten Stapelpreis bei Stapel > 1 und wie lange der Scan zurückliegt.",
    ["wn_2915_art_scrollbar"]           = "Moderne TomoMod-Scrollbar — ersetzt die Blizzard-Standard-Scrollbar durch eine 4 px schmale Spur mit einem akzentfarbigen Thumb, dessen Größe proportional zum Inhalt ist; unterstützt Drag, Klick auf Spur zum Springen, Mausrad und blendet sich aus, wenn der Inhalt passt.",
    ["wn_2915_art_anchor"]              = "Standard-Verankerung des AuctionRecipeTracker — das Fenster wird am rechten Rand des Auktionshausfensters verankert (TOPLEFT, AuctionHouseFrame, TOPRIGHT, 8, 0); manuell verschobene Positionen bleiben gespeichert und haben Vorrang.",
    ["wn_2915_art_scan_fix"]            = "Zuverlässigkeit des Scan-Buttons — OnShow setzt jetzt scanInProgress zurück, reaktiviert den Button und stellt sein Label wieder her; stille frühe Rückkehren (Scan läuft, AH geschlossen, API fehlt) zeigen jetzt eine rote Statusmeldung statt nichts zu tun.",

    -- ═══════════════════════════════════
    -- MythicTracker Boss Names Fix (2.9.13)
    -- ═══════════════════════════════════
    ["wn_2913_boss_names"]               = "MythicTracker: Boss-Namen werden jetzt korrekt angezeigt statt \"Boss 1\", \"Boss 2\" usw. — in WoW 12.x wurde das Szenario-Kriterium-Feld von criteriaString in description umbenannt; TomoMod liest jetzt description zuerst mit criteriaString als Fallback.",
    ["wn_2913_boss_checkmark"]           = "MythicTracker: Blizzards führendes Häkchen-Präfix (bei abgeschlossenen Boss-Zielen in 12.x hinzugefügt) wird vor der Anzeige jetzt entfernt.",
    ["wn_2913_ej_pcall"]                 = "MythicTracker: Der EncounterJournal_OpenJournal-Aufruf in FetchEJBossNames ist jetzt mit pcall umhüllt, um möglichen Taint in 12.x zu verhindern.",

    ["wn_2912_party_cd_fix"]             = "PartyFrame: Interrupt- und Kampfwiederbelebungs-CD-Tracking nutzt jetzt UNIT_SPELLCAST_SUCCEEDED mit taintsicherer SpellID-Auflösung (string.format); COMBAT_LOG_EVENT_UNFILTERED entfernt — die Registrierung aus einem Addon verursacht in 12.x Taint.",
    ["wn_2912_healer_interrupt"]         = "PartyFrame: Das Interrupt-Tracker-Symbol wird jetzt für Heiler ausgeblendet — seit Patch 12.x haben Heiler keine Interrupt-Fähigkeit mehr.",
    ["wn_2912_perf_cdm"]                 = "CooldownManager: UpdateButtonState cached GetCooldownTimes, GetCachedCooldownID und GetCooldownViewerCooldownInfo jetzt einmalig pro Button und Tick statt zweimal; ~50 % weniger API-Aufrufe in der Hauptschleife.",
    ["wn_2912_perf_aura"]                = "AuraTracker: Aktualisierungsrate von 10 fps (0,1 s) auf 5 fps (0,2 s) reduziert; kein sichtbarer Unterschied, Ticker-Overhead halbiert.",
    ["wn_2912_perf_resbars"]             = "ResourceBars: OnUpdate-Schwellenwert für DK-Runen/Mönch-Stagger von 50 ms auf 100 ms erhöht; Ausführungshäufigkeit halbiert ohne spürbaren Einfluss auf die Anzeige.",

    -- ═══════════════════════════════════
    -- CooldownManager / ProcGlow / BuffSkin Korrekturen (2.9.11)
    -- ═══════════════════════════════════
    ["wn_2911_cdm_hooks"]                = "CooldownManager: Swipe-Farben und GCD-Ausblendung in einen einzigen Hook pro Button zusammengefasst; GCD-Erkennung nutzt jetzt den Scanner-Cache statt pcall(C_CooldownViewer).",
    ["wn_2911_procglow_fixes"]           = "CDMProcGlow: Glow wird synchron in ShowAlert angewandt, um eine Race-Condition mit HideAlert im selben Frame zu vermeiden; Per-Frame-Timer durch einen einzigen globalen Persistence-Ticker ersetzt; RefreshAll filtert jetzt korrekt aktive Procs.",
    ["wn_2911_buffskin_fixes"]           = "BuffSkin: SkinButton wendet Icon-Anker und Masken jetzt erneut auf recycelten Frames an; Hooks werden einmalig über hooksInstalled installiert (Ein-/Ausschalten funktioniert jetzt korrekt); TemporaryEnchantFrame für Waffen-Verzauberungen eingehangen; Hooks werden sofort statt verzögert installiert.",

    -- ═══════════════════════════════════
    -- MythicTracker EJ-Boss-Namen (2.9.10)
    -- ═══════════════════════════════════
    ["wn_2910_ej_boss_names"]            = "MythicTracker: Boss-Namen werden über das Encounter-Journal aufgelöst — lokalisiert, unicode-sicher, für alle Dungeons von Cata bis The War Within.",
    ["wn_2910_ej_fallback"]              = "MythicTracker: 3-stufige Namensauflösung — dungeonEncounterID > EJ-Index > gefilterter criteriaString, mit automatischem Retry (×5) falls das EJ noch nicht geladen ist.",

    -- Player Auras Mover (v2.9.5)
    ["mover_player_auras"]       = "Spieler-Auren",
    ["opt_auras_spacing"]        = "Symbolabstand",
    ["btn_reset_aura_position"]  = "Aura-Position zurücksetzen",

    -- Module Reload Safety (v2.9.21)
    ["msg_module_reload"]        = "Diese Änderung erfordert ein Neuladen der Oberfläche.\nJetzt neu laden?",
    ["info_module_reload"]       = "Erfordert /reload um wirksam zu werden.",
    ["wn_2921_aura_mover"]       = "Spieler-Auren haben jetzt einen eigenen Mover im Layout-Modus (getöntes Overlay, Label, unabhängiges Drag & Drop).",
    ["wn_2921_aura_gui"]         = "Neuer Aura-Abstandsregler und Positionsreset-Button im Auren-Tab der Konfiguration.",
    ["wn_2921_reload_safety"]    = "Das Aktivieren/Deaktivieren eines Hauptmoduls (UnitFrames, Nameplates, Castbars, ActionBars, Party, Raid) bietet jetzt automatisch /reload an.",

    -- Waypoint Arrow Reversed (v2.9.22)
    ["wn_2922_waypoint_arrow"]    = "Der Off-Screen-Navigatorpfeil des Wegpunkts befindet sich jetzt auf der gegenüberliegenden Orbits-Seite: Wenn das Ziel vor dir liegt, erscheint der Pfeil unten und zeigt nach oben.",

    -- 3.0.3
    -- 3.0.4
    ["wn_304_consumable_bar"]    = "ConsumableBar — neues QOL-Modul, das Flakon- und Wohlgenährt-Buff-Symbole mit Countdown-Timer anzeigt. Vollständig konfigurierbar (Größe, Abstand, Ausrichtung, Timer-Position) und in Layout Mode verschiebbar.",
    ["wn_304_cursor_textures"]   = "Cursor-Ring — zwei neue Texturen hinzugefügt (Cygle und Herz). Textur-Auswahl verfügbar unter Allgemein → Cursor-Ring.",
    ["wn_304_mythichub_tp"]      = "MythicHub-Teleportation behoben — kein Taint (ADDON_ACTION_FORBIDDEN) oder Anchor-Fehler mehr beim Klicken auf Dungeon-Zeilen. Spell-IDs für Maisara Caverns und Windrunner Spire korrigiert.",

    -- 3.0.3
    ["wn_303_tracking_panel"]    = "Benutzerdefiniertes Verfolgungsfenster — ein Klick auf den Verfolgungsknopf öffnet jetzt ein TomoMod-gestaltetes Fenster links neben der Minikarte statt des nativen Blizzard-Dropdowns.",
    ["wn_303_collector_panel"]   = "Collector-Fenster überarbeitet — Addon-Knöpfe werden in einem TomoMod-Fenster (dunkler Hintergrund, türkisener Titel, Klassenfarbrahmen) links neben der Minikarte zusammengefasst.",
    ["wn_303_collector_autoclose"] = "Der Collector schließt sich 0,5 s nach dem Login/Neuladen automatisch, sobald die Knöpfe erfasst wurden — beim Klick öffnet er sich normal.",
    ["wn_303_tooltip_fix"]       = "Tooltip-Skin-Fix — das große schwarze Rechteck beim Überfahren von Einheiten oder Zaubern wurde behoben.",
    ["wn_303_coords_pos"]        = "Minikarten-Koordinaten zur besseren Lesbarkeit nach unten mittig verschoben.",

    -- 3.0.0
    ["wn_300_installer"]  = "Brandneuer Einrichtungsassistent — Voreinstellungen zuerst: wähle Empfohlen, Tank, Heiler, DPS, Minimal oder Benutzerdefiniert und du bist in Sekunden eingerichtet.",
    ["wn_300_presets"]    = "Konfigurations-Voreinstellungen — ein Klick wendet eine stimmige, rollenangepasste Konfiguration auf alle Module an; jederzeit über /tm wiederverwendbar.",
    ["wn_300_dashboard"]  = "Neues Start-Dashboard in /tm — schnelle Modul-Schalter, Assistent neu starten, Voreinstellung anwenden, Profil wechseln und zurücksetzen, alles an einem Ort.",
    ["wn_300_search"]     = "Durchsuchbare Seitenleiste — filtere Konfigurationskategorien nach Name oder Stichwort (tippe 'heal', 'cd', 'bag'…).",
    ["wn_300_locales"]    = "Vollständige Lokalisierung aller neuen 3.0-Texte in den 6 unterstützten Sprachen.",

    -- 3.0.5
    ["wn_305_rare_alert"]           = "Seltener-Alarm — neues QOL-Modul: spielt einen Sound und zeigt ein Banner, wenn ein seltener NPC in die Minimapreichweite eintritt. Linksklick: anvisieren + Totenkopf-Marker + Wegpunkt. Rechtsklick: schliessen.",

    -- =====================
    -- Extra Action Button (v3.0.6)
    -- =====================
    ["mover_ab_extra"] = "Extra-Aktion",
    ["mover_ab_pet"] = "Begleiterleiste",
    ["mover_ab_stance"] = "Haltungsleiste",
    ["section_extra_button"] = "Extra-Aktionsschaltflaeche",
    ["opt_extra_enabled"] = "Extra-Aktionsschaltflaeche verwalten (/reload zum Freigeben)",
    ["opt_extra_scale"] = "Skalierung der Extra-Schaltflaeche",
    ["btn_extra_reset_pos"] = "Position zuruecksetzen",
    ["info_extra_button"] = "Positioniere die Extra-Aktionsschaltflaeche im Layout-Modus. Sie erscheint bei Quests und Kaempfen. Beim Deaktivieren wird sie nach einem /reload an Blizzard zurueckgegeben.",
    ["wn_306_extra_button"] = "Neu — die Extra-Aktionsschaltflaeche ist jetzt Teil des TomoMod-Aktionsleistensystems.",
    ["wn_306_extra_mover"] = "Neu — verschiebe die Extra-Aktionsschaltflaeche (und die Zonenfaehigkeit-Schaltflaeche) im Layout-Modus wie jede andere Leiste. Position und Skalierung werden im Profil gespeichert.",
    ["wn_306_extra_scale"] = "Neu — Optionen der Extra-Aktionsschaltflaeche unter Aktionsleisten, Reiter Leistenverwaltung: aktivieren, Skalierung und Position zuruecksetzen.",
    ["wn_306_compass"] = "Korrektur — Kompass: haeufiger Lua-Fehler (x417) in der Weltkoordinatenkonvertierung behoben (C_Map.GetWorldPosFromMapPos gibt continentID + worldPosition zurueck; continentID wird nun korrekt verworfen).",
    ["wn_306_bagskin"] = "BagSkin — Slots verwenden jetzt Blizzards ContainerFrameItemButtonTemplate: Klick, Benutzen, Aufheben und Teilen werden durch nativen gesicherten Code behandelt (kein PreClick mehr mit Taint-Risiko). Waehrend des Kampfes aufgeschobene Slots werden nach dem Kampf automatisch neu gezeichnet.",
    -- 3.0.7
    ["wn_307_objective_tracker"] = "Questtracker — Weltquest-Bloecke werden jetzt korrekt dem Weltquests-Bucket zugeordnet statt ueber dem Tracker zu schweben. Fortschrittsbalken (Feindliche Staerken, Wochen-%) werden versteckt wenn ihr Bucket eingeklappt ist.",
    ["wn_307_guardian_rage"]     = "Ressourcenleisten — Hueter-Druiden sehen jetzt standardmaessig ihre Wut-Leiste zentriert auf dem Bildschirm. Mana bleibt als sekundaere Leiste darunter. Die Machtleiste im Einheitenrahmen wird automatisch ausgeblendet.",
    ["wn_307_resource_bars"]     = "Ressourcenleisten — Behoben: Hoehenschieberegler fuer Klassenmacht und Druiden-Mana funktionieren jetzt korrekt (globaler Frame-Name-Konflikt behoben). Neuer Schieberegler fuer die zentrierte Hauptleisten-Hoehe. Neue Checkbox in Einheitenrahmen › Spieler › Abmessungen.",
    ["wn_310_brez_counter"]       = "Kampfauferstehungs-Zaehler — Neues verschiebbares HUD das zeigt wie viele Kampfauferstehungen verfuegbar sind und die Zeit bis zur naechsten Aufladung. Liest den gemeinsamen Pool, funktioniert fuer jede Klasse. Einstellbar unter Schlachtzugsrahmen → Funktionen.",
    ["wn_310_resurrect"]          = "Auferstehungsanzeige — Ein Rez-Symbol erscheint jetzt auf einem Gruppe- oder Schlachtzugsmitglied waehrend eine Auferstehung auf ihn gewirkt wird.",
    ["wn_310_raid_sizes"]         = "Schlachtzugsrahmen — Neue optionale Layouts pro Groesse (10 / 25 / 40): Breite und Hoehe der Rahmen passen sich automatisch an die aktuelle Gruppengroesse an. Einstellbar unter Schlachtzugsrahmen → Funktionen.",
    ["wn_310_brez_fix"]           = "Gruppenrahmen — Behoben: Der Kampfauferstehungs-CD-Tracker zeigt jetzt korrekt das ausgegrautete Symbol und den Auflade-Timer wenn ein Brez von jemandem in der Instanz verbraucht wird.",

    -- 3.1.1
    ["art_searching"]        = "Suche: %s",
    ["art_searching_qty"]    = "Suche: %s × %d",
    ["wn_311_icicles"]        = "Frost-Magier: Neuer Eiszapfen-Tracker in der Ressourcenleiste (5 Segmente + Glacialer Einschlag-Leuchten bei Maximum). Farbe anpassbar unter CD & Ressource → Farben.",
    ["wn_311_taint_money"]   = "Midnight-Taint-Fehler behoben: Das Betrachten von Gegenständen im Schlachtzugskompendium löst keinen 'secret number'-Fehler mehr beim Goldwert aus — TomoMod verfälscht Vergleichs-Tooltips nicht mehr.",
    ["wn_311_art_qty"]       = "AuctionRecipeTracker: Ein Klick auf einen Bestandteil sucht den Gegenstand im Auktionshaus und zeigt die benötigte Anzahl in der Statusleiste an (z.B. Suche: Erwachtes Feuer × 14).",

    -- 3.1.2
    ["wn_312_brand"]         = "Akzentfarbe von #0cd29f auf #2ed884 (Mintgrün) in der gesamten Benutzeroberfläche aktualisiert — Titelleiste, Panels, Chat-Nachrichten, Popups und Standard-Farbwerte.",
    ["wn_312_brand_api"]     = "Neue TomoMod_Utils.BRAND / BRAND_DARK / BRAND_HOVER-Konstanten zentralisieren die Akzentfarbe: Konfigurationspanels und das Widget-Theme lesen jetzt aus einer einzigen Quelle.",
    ["wn_312_companion_fix"] = "CompanionStatus: Globale Variable behoben (UpdateIcon wurde ohne 'local' deklariert).",

    -- 3.1.3
    ["wn_313_nav"]        = "Konfigurations-UI überarbeitet: 16 Panels in 6 Gruppen zusammengefasst (Interface, Einheiten, Kampf, Komfort, Werkzeuge), jede mit eigener Akzentfarbe und Seitenkopf.",
    ["wn_313_accent"]     = "Widgets übernehmen jetzt automatisch die Akzentfarbe ihres übergeordneten Panels — Karten, Überschriften, Trennlinien, Checkboxen, Buttons und Tabs reagieren auf den aktiven Kategoriekontext.",
    ["wn_313_segmented"]  = "Neues SegmentedControl-Widget ersetzt kurze Dropdowns (Taschenleiste, Micro-Menü, Chat-Skin, Taschen-Layout, Sortierung, Audiokanal).",
    ["wn_313_dashboard"]  = "Startseite komplett neu gestaltet: Hero-Banner mit Live-Diagnosestatus, Schnellzugriff-Buttons (Installationsassistent, Profile, Diagnose, Neu laden) und überarbeitete Modul-Schalter.",
    ["wn_313_np_preview"] = "Nameplatten: Neue Live-Vorschau oben im Konfigurationspanel — zeigt Verbündete, feindliches Ziel und Boss, aktualisiert sich beim Ändern von Breite, Höhe, Cast-Leiste und Schriftgröße.",
    ["wn_313_loot_filter"] = "Beute-Klassenfilter behoben: Gegenstände ohne IDB-Eintrag (z. B. neue Raid-Drops) nutzen jetzt Rüstungstyp-Abgleich statt für alle Klassen sichtbar zu sein.",
    ["wn_313_sporefall"]   = "Beutedaten: Sporefall-Schlachtzug (ejEncounterID 2711) mit 15 Gegenständen aus KeystoneLoot Build 12.0.7 hinzugefügt.",
    ["wn_313_diag"]       = "Diagnose: 7 neue UIError-Ausschluss-Schlüsselwörter (Händler, Reittier, Inventar, Löschen, Aufwertung, Aussehen, Duell) + Konsole erscheint jetzt immer über dem Konfigurationsmenü.",
    ["wn_313_tooltip_anchor"] = "Tooltip-Position: neues 4-Modus-Ankersystem — Standard, Maus (folgt dem Cursor), Ecke (an Bildschirmecke fixiert) und Benutzerdefiniert (per Drag verschiebbarer Rahmen).",

    -- Tooltip-Verankerung
    ["opt_tooltip_anchor"]        = "Tooltip-Position",
    ["tooltip_anchor_default"]    = "Standard",
    ["tooltip_anchor_cursor"]     = "Maus",
    ["tooltip_anchor_corner"]     = "Bildschirmecke",
    ["tooltip_anchor_custom"]     = "Benutzerdefiniert",
    ["opt_tooltip_anchor_corner"] = "Ecke (Ecken-Modus)",
    ["corner_br"]                 = "Unten rechts",
    ["corner_bl"]                 = "Unten links",
    ["corner_tr"]                 = "Oben rechts",
    ["corner_tl"]                 = "Oben links",
    ["info_tooltip_anchor"]       = "Benutzerdefiniert: Diesen Modus wählen, dann den türkisfarbenen Rahmen an die gewünschte Position ziehen.",
    ["btn_tooltip_toggle_anchor"] = "Anker anzeigen/ausblenden",
    ["mover_tooltip_anchor"]      = "Tooltip-Anker",

    -- Nameplates preview
    ["np_preview_title"]   = "Nameplates-Vorschau",
    ["np_preview_hint"]    = "Schnelle Lesbarkeit: Farbe, Cast-Leiste, Auren und Bedrohung auf einen Blick.",
    ["preview_np_friendly"] = "Verbündeter",
    ["preview_np_target"]  = "Feindliches Ziel",
    ["preview_np_boss"]    = "Markierter Boss",

    -- 3.1.4
    ["wn_314_tooltip_anchor"] = "Tooltip-Position: neues 4-Modus-System — Standard, Maus (folgt dem Cursor), Ecke (Bildschirmecke) und Benutzerdefiniert (verschiebbarer Rahmen). Konfigurierbar unter Skins → Tooltip.",
    ["wn_314_locale_fix"]     = "Fehlende Tooltip-Farbbeschriftungen behoben: Hintergrund- und Rahmenfarb-Auswähler in Skins → Tooltip werden jetzt korrekt angezeigt.",

    -- 3.1.5
    ["wn_315_ot_itembutton"] = "Aufgaben-Tracker: Quest-Gegenstandsknöpfe werden jetzt korrekt ausgeblendet, wenn ihr Bucket eingeklappt wird (der Knopf ist dem nativen Tracker zugeordnet, nicht dem Block — er blieb bisher sichtbar über eingeklappten Buckets).",
    ["wn_315_talkinghead"] = "QOL: Die Option „Talking Head ausblenden“ ist wieder im Konfigurations-GUI (QOL → Automatisierungen). Sie wirkt jetzt sofort ohne /reload und ist umkehrbar — beim Abwählen werden die Scroll-Dialoge wiederhergestellt.",

    -- 3.1.6
    ["wn_316_party_combat"] = "Gruppenrahmen: Sichtbarkeitsfehler behoben, wenn Mitglieder beitreten, die Gruppe verlassen oder sich die Gruppe mitten im Kampf in eine Schlachtzugsgruppe umwandelt — die Rahmen werden nun in jeder Situation zuverlässig ein-/ausgeblendet.",
    ["wn_316_raid_combat"] = "Schlachtzugsrahmen: behoben, dass Rahmen sichtbar oder ausgeblendet hängen blieben, wenn Mitglieder während eines Kampfes beitraten oder gingen — die Sichtbarkeit wird jetzt von einem sicheren, kampftauglichen System gesteuert.",
    ["wn_316_roster_repaint"] = "Gruppen- & Schlachtzugsrahmen: behoben, dass veraltete Informationen (Klassenfarbe, Absorptionsschilde, Dispel-Hervorhebung) nach einem Wechsel in der Zusammensetzung kurzzeitig den falschen Spieler anzeigten — auch im Kampf.",
    ["wn_317_cdm_holders"] = "Cooldown Manager: neues 'Holders'-System — jeder Cooldown-Viewer (Essenziell, Nützlich, Buff-Symbole, Buff-Leisten) lässt sich unabhängig vom Edit-Mode-Raster von Blizzard frei verschieben und sperren, mit Live-Vorschau von Symbolen/Leisten, solange sie leer sind.",
    ["wn_317_resourcebars_health"] = "Ressourcenleisten: neue optionale Lebensleiste — einstellbare Höhe, Format (%, Wert oder beides), klassenfarbige Füllung, sanfte Animation und eine Farbschwelle für niedrige Lebenspunkte.",
    ["wn_317_config_cards"] = "Konfigurationsoberfläche: das Panel Cooldown & Ressourcen hat jetzt ein Karten-Layout sowie einen eigenen Reiter Leisten für alle Einstellungen der Lebensleiste.",
    ["wn_316_locale_cdm"] = "Behoben: der Reiter Leisten, die Platzierungs-/Live-Vorschaukarten und der Bereich Lebensleiste & Animationen zeigten rohe Schlüssel statt übersetztem Text an — jetzt in allen 6 Sprachen übersetzt.",
    ["wn_316_taint_chat"] = "Ein Taint-Fehler ('secret string value') im Chat-Skin beim Empfang von Kanalnachrichten wurde behoben.",
    ["wn_316_taint_skyride"] = "Ein Taint-Fehler ('secret number value') in der Skyriding-Geschwindigkeitsleiste wurde behoben, verursacht durch die geschützten Flug-/Gleitgeschwindigkeitswerte des Spiels.",
    ["wn_316_durability_pos"] = "Minimap: Die Position des Haltbarkeitstextes ist jetzt konfigurierbar (Ecke + X/Y-Versatz) unter Interface → Allgemein → Info Panel — nützlich, um Überlappungen mit dem neuen Erweiterungs-Button aus Patch 12.0.7 zu vermeiden.",

    -- 3.1.7
    ["wn_317_libserialize_namespace"] = "Profile: Die eingebettete LibSerialize-Bibliothek verwendet jetzt einen privaten Namensraum ('TomoSerialize-1.0') statt des gemeinsamen Namens 'LibSerialize', wodurch Export-/Import-Konflikte mit anderen Addons vermieden werden, die ebenfalls LibSerialize einbetten.",
    ["wn_317_drag_absolute_coords"] = "Verschiebbare Rahmen: behoben, dass gespeicherte Positionen nach dem Ziehen bei Leveling Bar, Movers, AuctionRecipeTracker, Mythic+ Tracker, TomoScore, Frame Anchors, Bag Skin, Zauberleisten, Gruppen-/Schlachtzugsrahmen-Ankern, Kompass, Verbrauchsgüterleiste, Beutebrowser, Minimap, Aufgaben-Tracker, Skyriding-Leiste, Ressourcenleisten und UnitFrames verrutschten oder sich umkehrten — Positionen werden jetzt als stabile, bildschirmabsolute Koordinaten gespeichert.",
    ["wn_317_ot_combat_taint"] = "Aufgaben-Tracker: ein möglicher Taint-Fehler wurde behoben, wenn Blizzard einen eingeklappten Quest-Bucket-Block während einer Quest-Aktualisierung im Kampf erneut anzeigt.",
    ["wn_317_deadcode_cleanup"] = "Interne Bereinigung: mehrere ungenutzte/deaktivierte Module wurden entfernt, um die Addon-Größe zu reduzieren — keine für den Nutzer sichtbaren Funktionen waren betroffen.",
    ["wn_317_raidmanager_fix"] = "Schlachtzugsrahmen: behoben, dass das standardmäßige Blizzard-Gruppenleiter-Panel (Bereitschaftscheck, Raid-Zielmarkierungen, in Schlachtzug umwandeln, Ping-Limit, Gruppe verlassen) zusammen mit den Schlachtzugsrahmen ausgeblendet wurde, wenn „Blizzard Schlachtzug-Rahmen ausblenden“ aktiviert ist — jetzt wird nur noch der Container der Mitgliederrahmen unterdrückt, die Leiter-Symbolleiste bleibt verfügbar.",
    ["wn_317_groupmanager_skin"] = "Schlachtzugsrahmen: die Option „Gruppenleiter-Panel im TomoMod-Stil gestalten“ gestaltet nun die komplette Blizzard-Symbolleiste im dunklen/minzgrünen TomoMod-Design um — Modus- und Ping-Limit-Dropdowns, Rollen-/Gruppenfilter, Symbolleisten-Schaltflächen (Bearbeitungsmodus, Einstellungen, Bereitschaftscheck, Rollenumfrage, Countdown), Raid-Markierungsschaltflächen mit ihren Einheit/Boden-Tabs sowie rot gestaltete Schaltflächen zum Verlassen der Gruppe — alle Blizzard-Symbole bleiben dabei unverändert, und die Option lässt sich live ohne Neuladen umschalten.",
    ["wn_317_groupmanager_collapsetab"] = "Schlachtzugsrahmen: behoben, dass die eingeklappte Umschaltfläche des Gruppenleiter-Panels einen Reststreifen am Bildschirmrand hinterließ, und dafür ein richtiges minzfarbenes Auszieh-Tab anstelle einer einfach umgestalteten Schaltfläche eingeführt.",

    -- 3.1.8
    ["wn_318_bagskin_itemclass_enum"] = "Bag Skin: der Kategorieabgleich verwendet jetzt Blizzards Enum.ItemClass-Konstanten (mit numerischem Fallback) statt fest codierter Itemklassen-Zahlen, was die Kategorisierung auf allen Clients korrekt hält.",
    ["wn_318_bagskin_cat_order"] = "Bag Skin: Standard-Kategorienreihenfolge aktualisiert — Questgegenstände werden jetzt direkt nach Ausrüstung eingeordnet, vor Verbrauchsgütern und Handelswaren.",
    ["wn_318_bagskin_cat_foundation"] = "Bag Skin: interne Grundlage für eine zukünftige Option zum Ausblenden/Neuordnen von Kategorien hinzugefügt — Verschiedenes und Freie Plätze bleiben immer sichtbar, damit kein Gegenstand jemals verschwinden kann.",

    -- 3.1.9
    ["wn_3110_actionbar_spelldrag"] = "Aktionsleisten: die Korrektur für leere Slots aus 3.1.9 funktionierte weiterhin nicht für einen bereits auf einer Leiste liegenden Zauber, ein Makro oder ein Reittier (bei deaktiviertem „Leere Slots anzeigen“) — das Verschieben auf einen leeren Slot funktioniert jetzt bei jeder Aufnahme, ohne das Zauberbuch/die Talente zu öffnen.",
    ["wn_3110_skyride_taint"] = "Skyriding: ein wiederkehrender Verunreinigungsfehler bei der Bodengeschwindigkeitsanzeige, der trotz einer früheren Korrektur weiterhin hunderte Male pro Sitzung auftreten konnte, wurde behoben — die Geschwindigkeitsberechnung ist nun mit einem zusätzlichen Sicherheitsnetz abgesichert, sodass kein Fehler mehr auftreten kann.",
    ["wn_3110_diag_exclusions"] = "Diagnose: zwei neue Ausschluss-Schlüsselwörter hinzugefügt (Händler verweigert den Ankauf eines Gegenstands, Plündern während des aktiven Herausforderungsmodus blockiert), damit diese normalen Spielmeldungen nicht mehr als Fehler protokolliert werden.",
    ["wn_319_actionbar_dragfix"] = "Aktionsleisten: behoben, dass Zauber nicht auf einen leeren Slot gezogen werden konnten (bei deaktivierter Option „Leere Slots anzeigen“), außer wenn das Zauberbuch/die Talente geöffnet waren — leere Slots werden jetzt während jeder Aufnahme automatisch sichtbar.",
    ["wn_319_ot_mover_fix"] = "Aufgaben-Tracker: behoben, dass die Position des Ankers sich gelegentlich selbst zurücksetzte (Blizzards Edit-Modus konnte sie stillschweigend überschreiben) — das Ziehen bleibt jetzt zuverlässig erhalten.",
    ["wn_319_ot_quest_limit"] = "Aufgaben-Tracker: behoben, dass der Regler „Max. angezeigte Quests“ im Standard-Kategorien-Layout überhaupt keine Wirkung hatte.",
    ["wn_319_minimap_drift"] = "Minimap: behoben, dass sich die Minimap nach einem /reload selbst an eine andere Position verschob (ein Skalierungsfehler wendete den Skalierungsfaktor doppelt auf die gespeicherte Position an).",
    ["wn_319_minimap_collector"] = "Minimap: behoben, dass der Button-Sammler weiterhin die Minimap-Buttons anderer Addons nach einem Reload ausblendete, obwohl er deaktiviert war.",
    ["wn_319_minimap_tracking"] = "Minimap: behoben, dass der Pistage-Button gelegentlich verschwand und der native Blizzard-Pistage-Button nach dem Wiederanzeigen nicht anklickbar blieb.",
    ["wn_319_repbar_hide"] = "Ruf-Leiste: behoben, dass Blizzards eigene Ruf-/Ehre-Leiste in manchen Fällen trotz aktivierter Option „Blizzard-Ruf-Leiste ausblenden“ noch sichtbar war.",
    ["wn_319_tooltip_bg"] = "Tooltip: weniger transparenter Standard-Hintergrund (Deckkraft 92 % → 97 %) — weiterhin voll über den Regler für Hintergrund-Deckkraft anpassbar.",
    ["wn_319_tooltip_anchor"] = "Tooltip: der „Benutzerdefiniert“-Positionsanker bleibt nicht mehr außerhalb des Layout-Modus dauerhaft sichtbar, und eine neue Schaltfläche „Anker anzeigen/ausblenden“ wurde unter Skins → Tooltip hinzugefügt.",
    ["wn_319_diag_copy"] = "Diagnose: behoben, dass die Schaltfläche „Copy Report“ scheinbar nichts tat — das Export-Fenster konnte sich versteckt hinter der Konsole öffnen.",

    -- 3.1.11
    ["wn_3111_castbar_deathstuck"] = "Zauberleiste: behoben, dass die Zauberleiste für Ziel, Fokus, Boss und andere Nicht-Spieler-Einheiten sichtbar hängen blieb, wenn die Einheit starb oder verschwand, ohne dass ein passendes Stopp-Ereignis ausgelöst wurde.",
    ["wn_3111_castbar_targetreset"] = "Zauberleiste: ein Wechsel von Ziel oder Fokus setzt die Zauberleiste jetzt vollständig zurück, statt nur den Fehlschlag-Timer zu löschen — ein Restzauber der vorherigen Einheit kann so nicht mehr auf der neu ausgewählten weiter angezeigt werden.",
    ["wn_3111_ot_lfgbutton"] = "Aufgaben-Tracker: das Einklappen einer Questkategorie blendet jetzt auch deren Schaltfläche „Gruppe suchen“ aus, nicht nur die Gegenstands-Schaltfläche — beide werden beim erneuten Ausklappen korrekt wiederhergestellt.",
    ["wn_3112_score_taint"] = "Mythisch+-Ergebnistafel: ein Schwall von Taint-Fehlern behoben, der die Anzeige/Positionierung der Dungeon-Abschluss-Ergebnistafel blockieren konnte, wenn der Spieler beim Dungeon-Abschluss noch im Kampf war.",
    ["wn_3112_config_resize"] = "Konfigurationsfenster: das /tm-Fenster kann jetzt durch Ziehen der unteren rechten Ecke in der Größe verändert und über einen neuen 70-130%-Regler in Allgemein skaliert werden — Standardgröße auf 1240x820 erhöht, mit einem Button, um beides mit einem Klick zurückzusetzen.",
    -- =====================
