    ["info_bar_uniformize"]           = "Überträgt das Erscheinungsbild (Größe, Abstand, Spalten, Transparenz, Skalierung, Ausblenden, Texte …) auf jede andere Leiste. Position und Aktivierungsstatus jeder Leiste bleiben erhalten.",
    ["opt_bar_hotkey_size"]           = "Schriftgröße der Tastenkürzel",
    ["popup_ab_uniformize"]           = "Das Aussehen der Leiste „%s“ auf alle anderen Leisten übertragen?",
    ["info_cb_anchor_uf"]             = "Diese Zauberleiste ist am zugehörigen Unit-Frame verankert (sie erscheint also am Ziel-/Fokus-/Begleiter-/Boss-Rahmen).",
    ["tab_qol_compass"]               = "Kompass",
    ["section_compass"]               = "Kompassleiste",
    ["info_compass_desc"]             = "Eine Richtungsleiste oben am Bildschirm, die beim Drehen N/O/S/W anzeigt, mit einem Marker, der auf deine verfolgte Quest oder den Kartenwegpunkt zeigt. Nur lesend – kein Taint.",
    ["info_compass_layout"]           = "Tipp: Nutze den Layout-Modus (/tm layout), um die Leiste an die gewünschte Stelle zu ziehen.",
    ["opt_compass_enable"]            = "Kompassleiste aktivieren",
    ["opt_compass_fov"]               = "Sichtfeld",
    ["compass_fov_narrow"]            = "Eng (±45°)",
    ["compass_fov_standard"]          = "Standard (±60°)",
    ["compass_fov_wide"]              = "Weit (±90°)",
    ["opt_compass_width"]             = "Leistenbreite",
    ["opt_compass_height"]            = "Leistenhöhe",
    ["opt_compass_scale"]             = "Skalierung",
    ["opt_compass_show_heading"]      = "Richtungsanzeige anzeigen (z. B. 245° SW)",
    ["opt_compass_show_distance"]     = "Entfernung an Markern anzeigen",
    ["opt_compass_show_quest"]        = "Marker für verfolgte Quest anzeigen",
    ["opt_compass_show_waypoint"]     = "Marker für Kartenwegpunkt anzeigen",
    ["opt_skyride_ground_speed"]      = "Bodengeschwindigkeit anzeigen",
    ["info_skyride_ground_speed"]     = "Zeigt deine Bewegungsgeschwindigkeit auch am Boden an (Fluganzeigen bleiben verborgen, solange du nicht fliegst).",
    ["btn_class_reminder_preview"]    = "Vorschau",
    ["sublabel_class_reminder_coverage"] = "— Verfolgte Buffs & Gestalten —",
    ["opt_char_skin_movable"]         = "Verschiebbares Fenster",
    ["info_char_skin_movable"]        = "Sobald aktiviert, kannst du das Charakterfenster ziehen, um es zu verschieben. Die Position wird gespeichert.",
    ["btn_char_skin_reset_pos"]       = "Position zurücksetzen",
    ["btn_sound_test"]                = "▶ Diesen Sound abspielen",
    ["opt_auras_max_width"]           = "Max. Breite (Zeilenumbruch)",
    ["opt_auras_per_row"]             = "Symbole pro Zeile",

    -- 3.2.0
    ["wn_320_gsearch"] = "Konfigurationsfenster: die Seitenleisten-Suche ist jetzt global — sie findet passende Optionen in allen Kategorien und Reitern, nicht nur auf der sichtbaren Seite, und ein Klick auf ein Ergebnis springt direkt dorthin mit einem kurzen Hervorhebungs-Blinken.",
    ["wn_320_panelcache"] = "Konfigurationsfenster: das Wechseln zwischen Kategorie-Reitern ist nach dem ersten Besuch jetzt sofort — Panels werden zwischengespeichert, statt jedes Mal neu aufgebaut zu werden.",
    ["wn_320_configlocale"] = "Konfigurationsfenster: alle verbliebenen fest einprogrammierten französischen Beschriftungen in den Einstellungs-Panels sind jetzt vollständig übersetzbar.",
    ["cfg_tab_cdforge"]           = "Cooldowns",

    -- 3.2.1
    ["wn_321_cdf_intro"] = "Neu — CooldownForge: Erstelle individuelle Cooldown-Leisten pro Klasse, die Zauber, Gegenstände, Presets (Tränke, Heilstein …), Schmuckstücke oder deine Rassenfähigkeit verfolgen, im neuen Reiter „Cooldowns“ (Kategorie Kampf).",
    ["wn_321_cdf_movers_io"] = "CooldownForge-Leisten lassen sich jetzt über den einheitlichen Movers-Manager verschieben und über einen klassenbezogenen Import/Export-String zwischen Charakteren teilen.",

    -- 3.2.2
    ["wn_322_studio_intro"] = "Neu — Cooldown Studio: ein eigener Vollbild-Editor für CooldownForge-Leisten mit Reitern pro Leiste für Layout/Stil/Zauber/Sichtbarkeit/Teilen, aufrufbar über den Reiter Cooldowns.",
    ["wn_322_studio_fix"] = "Cooldown Studio: behoben, dass sich das Fenster nicht immer über anderen Fenstern anzeigte und seine Widgets nicht immer die richtige Akzentfarbe übernahmen.",
    ["wn_322_studio_visibility"] = "Cooldown Studio: bedingte Sichtbarkeit pro Leiste hinzugefügt — eine Leiste je nach Kampf-, Instanz-, Gruppen- oder Schlachtzugsstatus über einfache Indifferent/Ja/Nein-Menüs im Reiter Sichtbarkeit ein- oder ausblenden.",
    ["wn_322_studio_finestyle"] = "Cooldown Studio: Feinabstimmungs-Stiloptionen im Reiter Stil hinzugefügt — Deckkraft, Rahmenfarbe/-stärke, eine benutzerdefinierte Timer-Farbe und ein Schlagschatten-Schalter.",
    ["wn_322_forge_internal"] = "Intern: Die gemeinsamen Mechanismen von CooldownForge und Cooldown Studio wurden in eine neue interne Forge-Bibliothek ausgelagert und legen damit den Grundstein für zukünftige Tiefenbearbeitungsmodule — keine für den Nutzer sichtbaren Änderungen.",
    ["wn_322_studio_fixes2"] = "Cooldown Studio: behoben, dass die Seitenleisten-Schaltflächen (Neu/Duplizieren/Umbenennen/Löschen/Vorlagen) manchmal nicht auf Klicks reagierten und ihre Zeile überliefen, dass Escape das Fenster mit einem Taint-Fehler schloss, und dass der ausgewählte Reiter beim Wechseln der Leiste zurückgesetzt statt gemerkt wurde.",
    ["wn_322_studio_talents"] = "Cooldown Studio: Die Zauberbibliothek enthält jetzt auch deine aktiven Talente und Heldentalente, nicht nur Grimoire-Zauber, sodass du sie ebenfalls auf Cooldown-Leisten verfolgen kannst.",
    ["wn_322_talent_scan_fix"] = "Cooldown Studio: behoben, dass der Talent-/Heldentalent-Scan der Bibliothek im Spiel nichts fand — es werden jetzt nur tatsächlich gewählte Talente berücksichtigt, unter Verwendung des richtigen API-Felds für deine ausgewählte Wahl.",
    ["wn_322_diag_taintown"] = "Diagnose: behoben, dass fantomhafte ADDON_ACTION_FORBIDDEN-Meldungen (UseToy, SetNote ...) zufälligen Addons zugeschrieben wurden — Diagnose übernimmt jetzt die exklusive Kontrolle über die Taint-Ereignisse, statt sie von Blizzards eigener Verarbeitung erneut weiterleiten zu lassen.",
    ["wn_322_actionbars_discover"] = "Aktionsleisten: Der Infotext im Reiter Leisten-Verwaltung weist jetzt auch darauf hin, dass das Aufklappen einer Leiste ihre Buttongröße- und Skalierungsregler anzeigt, wodurch diese Option leichter zu finden ist.",
    ["wn_322_tracker_editmode"] = "Zielverfolgung: behoben, dass der Tracker beim Verschieben während Blizzards nativem Edit Mode einfror.",
    ["wn_323_studio_preview"] = "Cooldown Studio: Der Reiter Stil zeigt jetzt eine Live-Symbolvorschau (gleiches Rendering wie echte Leisten), die zwischen bereit/im Cooldown wechselt, sodass Stiländerungen sofort sichtbar sind.",
    ["wn_323_studio_copystyle"] = "Cooldown Studio: Im Reiter Stil wurde ein Button „Stil übernehmen von...“ hinzugefügt, um nur den visuellen Stil einer anderen Leiste zu kopieren, ohne Zauber, Position oder Layout zu ändern.",
    ["wn_323_studio_create"] = "Cooldown Studio: „+ Neu“ fragt jetzt zuerst nach dem Namen der Leiste, anstatt einen Platzhalter zu erstellen, der danach umbenannt werden muss, und die Umbenennen-/Erstellen-Popups werden jetzt zuverlässig über dem Fenster angezeigt, wobei das Namensfeld automatisch fokussiert wird.",
    ["wn_323_slider_entry"] = "Konfigurations-Regler: Rechtsklick auf einen Wert, um eine genaue Zahl einzugeben, Strg+Klick zum Zurücksetzen auf den Standardwert, mit einem Tooltip-Hinweis für beides.",
    ["wn_323_petbar_editmode"] = "Aktionsleisten: Die Begleiter- und Formen-Leisten können jetzt im Bearbeitungsmodus ausgewählt und verschoben werden, auch wenn sie im Ruhezustand ausgeblendet sind (kein Begleiter/keine Formen).",
    ["wn_324_studio_real_icons"] = "Cooldown Studio: Die Vorschau im Reiter Stil verwendet jetzt echte Symbole — zuerst die Zauber der Leiste, dann Zauberbuch und Talente deiner Klasse — statt drei fest hinterlegter Demo-Symbole aus fremden Klassen.",
    ["wn_324_chat_contacts"] = "Chat: Die Chat-Seitenleiste hat jetzt einen Kontakte-Button, der Blizzards Freundesliste mit einem Klick öffnet — und damit einen Zugang wiederherstellt, den das Ausblenden des nativen Sozial-Buttons durch den Skin entfernt hatte.",
    ["wn_324_editbox_scrollbar"] = "Konfiguration: Mehrzeilige Textfelder (Import/Export, Notizen...) zeigen nicht mehr Blizzards goldene Pfeil-Bildlaufleiste — sie nutzen jetzt die schmale Akzent-Bildlaufleiste des Addons und unterstützen das Mausrad.",
    ["wn_325_friends_window"] = "Kontakte: Das Freundesfenster ist jetzt vollständig gestaltet statt nur halbfertig — flacher dunkler Körper, Akzentrahmen über der Liste gezeichnet, neu gestalteter Titel und ein schlichter Akzent-Schließen-Button.",
    ["wn_325_friends_tabs"] = "Kontakte: Die unteren Reiter und die Unterreiter Freunde / Kürzliche Verbündete / Freunde werben haben ihre goldenen Platten verloren und zeigen nun eine Akzent-Unterstreichung und -Beschriftung auf dem ausgewählten.",
    ["wn_325_friends_buttons"] = "Kontakte: Jeder Button im Fenster (Freund hinzufügen, Nachricht senden, die Buttons im Wer-Reiter, In Schlachtzug umwandeln, Schlachtzugsinfo, Warteschlange beitreten) teilt sich nun einen flachen Akzent-Stil, der beim Überfahren aufhellt, und die beiden Kontakt-Buttons teilen sich die untere Reihe gleichmäßig.",
    ["wn_325_friends_toggle"] = "Kontakte: Den Skin in den Einstellungen auszuschalten stellt Blizzards Aussehen jetzt sofort wieder her, ohne Neuladen.",
    ["wn_325_cdf_radial"] = "CooldownForge: Cooldown-Leisten können ihre Symbole nun im Kreis statt in einer Linie anordnen — Radius, Startwinkel, Bogenweite und Richtung stellst du über den neuen Layout-Modus ein.",
    ["wn_325_cdf_spacing"] = "CooldownForge: Der Symbolabstand besteht jetzt aus zwei getrennten Werten — entlang der Reihe und zwischen umgebrochenen Reihen — und das Maximum wurde von 16 auf 64 px erhöht.",
    ["wn_325_cdf_glow"] = "CooldownForge: Das Leuchten kann nun nach einer wählbaren Bedingung ausgelöst werden — wenn der Zauber bereit ist, während ein Buff auf dir aktiv ist (mit optionaler Buff-ID für Schmuckstücke/Talente) oder immer — pro Leiste oder pro Zauber einstellbar.",
    ["wn_325_cdf_hidecd"] = "CooldownForge: Eine Leiste kann jedes Symbol während seines Cooldowns ausblenden, wobei die verbleibenden Symbole die Lücke schließen; sie ordnet sich nur neu an, wenn sich die Menge der bereiten Zauber ändert.",
    ["wn_326_whatsnew_stuck"] = "Was ist neu: Dieses Fenster mit Escape zu schließen ließ den Bildschirm abgedunkelt und die Maus tot zurück, und die Version blieb ungemerkt — beim nächsten Login kam sie wieder. Jeder Schließweg (X, Button, Escape) läuft nun über eine einzige Stelle, die die Abdunklung entfernt und die Version merkt.",
    ["wn_326_whatsnew_escape"] = "Was ist neu: Escape wird jetzt vom Fenster selbst verarbeitet statt über Blizzards UISpecialFrames, was einen Taint-Pfad über das Spielmenü beseitigt; alle anderen Tasten werden weiterhin durchgereicht.",
    ["wn_326_whatsnew_gates"] = "Was ist neu: Das Fenster wartet nun auf einen freien Moment — nie über einer Zwischensequenz, einem Video oder einem Kampf — und überspringt den allerersten Login eines Charakters komplett, damit es dich nicht mitten in der Intro-Sequenz begrüßt.",
    ["wn_326_tracker_empty"] = "Zielverfolgung: Wird nichts verfolgt, bleibt kein dunkles Panel mehr zurück, das fast den ganzen Bildschirm bedeckte — es schrumpft jetzt auf seine Kopfzeile, und „Bei Leere ausblenden“ ist standardmäßig aktiv (bestehende Profile werden einmalig angepasst; wer es wieder abschaltet, behält das).",
    ["wn_326_tracker_drag"] = "Zielverfolgung: Das Panel lässt sich wieder nach unten ziehen — die Bildschirmbegrenzung galt für Blizzards überdimensioniertes Verfolgungsfenster, dessen Unterkante bereits außerhalb des Bildschirms lag, weshalb jede Bewegung nach unten abgelehnt wurde.",
    ["wn_326_repbar_drag"] = "Rufleiste: Behoben, dass die Leiste im Layout-Modus zwar ihren Entsperr-Rahmen zeigte, sich aber nicht greifen ließ — die Maus war dort nie aktiviert, das Ziehen konnte also gar nicht starten.",
    -- Cooldown-Manager-Halter (Movers / Layout-Modus)
    ["mover_cdm"]                        = "Cooldown Manager",
    ["cdm_drag_hint"]                    = "Zum Verschieben ziehen",
    ["cdm_preview_aura"]                 = "Aura",

    ["wn_326_suite_card"] = "Konfiguration: Das Dashboard hat eine Karte „Tomo-Suite“ erhalten, die TomoBoss vorstellt (Boss-Timer mit gesprochenen Ansagen) — eine Verknüpfung zu seinen Optionen, wenn es installiert ist, sonst eine kopierbare Adresse und ein dauerhaftes „Nicht mehr anzeigen“.",

    ["wn_330_cdf_unusable"] = "CooldownForge: Ein Symbol kann sich jetzt einfärben, wenn der Zauber zwar nicht auf Abklingzeit ist, aber gerade nicht gewirkt werden kann — zu wenig Wut, falsche Gestalt, fehlende Reagenz. Drei Möglichkeiten: kein Effekt (Standard), ausgrauen, oder ausgrauen mit blauem Ton, wenn genau die fehlende Ressource blockiert; pro Leiste und pro Zauber einstellbar.",
    ["wn_330_cdf_glow_usable"] = "CooldownForge: Das Leuchten hat eine Bedingung „wenn der Zauber wirkbar ist“ erhalten — bereit *und* bezahlbar, damit ein Zauber ohne Ressource nicht weiterleuchtet und zu einem Druck einlädt, der fehlschlagen würde.",
    ["wn_330_cdf_hide_unusable"] = "CooldownForge: Eine Leiste kann ein Symbol auch ganz ausblenden, solange die Ressource fehlt — zusätzlich zum bestehenden Filter „während der Abklingzeit ausblenden“. Beide sind unabhängig und kombinierbar, und die übrigen Symbole rücken nach.",
    ["wn_330_cp_charged"] = "Ressourcenleisten: Aufgeladene Kombopunkte werden jetzt als solche angezeigt — der aufgeladene Punkt wird markiert, ob gefüllt oder nicht, sodass du siehst, wo die Ladung sitzt, bevor du sie verbrauchst. Die Farbe ist unter CD & Ressource → Farben einstellbar, standardmäßig Rot.",
    ["wn_330_colorpicker"] = "Konfiguration: Die Farbauswahl öffnete sich hinter dem Einstellungsfenster und Cooldown Studio, sodass es aussah, als würde das Farbfeld nichts tun. Sie öffnet sich jetzt darüber, direkt neben dem angeklickten Farbfeld statt in der Bildschirmmitte.",
    ["wn_330_locale_escapes"] = "Lokalisierung: Die Kompass-Optionen zeigten rohe Escape-Codes anstelle der Umlaute — „durchlxC3xA4uft“, „xC3x96ffne“, „Weit (xC2xB190xC2xB0)“. Diese Texte nutzten eine Escape-Syntax, die das Lua des Spiels nicht kennt und wörtlich ausgab; sie sind wieder lesbar, in allen sechs Sprachen.",
    ["wn_330_diag_filters"] = "Diagnose: Festgesetzt zu sein und der Versuch, einen gebundenen Gegenstand per Post zu senden, wurden im Bericht als Fehler erfasst. Beides ist normale Spielrückmeldung und wird jetzt wie der Rest herausgefiltert.",
    ["wn_330_tracker_delve_place"] = "Zielverfolgung: Mit deaktiviertem „Ausblenden wenn leer“ blieb das Panel zwar stehen, der Tiefen-Block wurde darin aber nie positioniert — der Leerfall kehrte vor dem Durchgang zurück, der ihn platziert. Szenario- und Tiefenmodule werden jetzt zuerst platziert, unabhängig davon, was sonst verfolgt wird.",
    ["wn_330_tooltip_info"] = "Tooltip: Einheits-Tooltips tragen jetzt eine echte Informationsebene — Gildenrang, aktuelles Ziel der Einheit, Mythisch+-Wertung, Reittier, Bewegungstempo und Ort, dazu Schlachtzugsmarkierung, Rollen- und Klassensymbol auf der Namenszeile. Jede Zeile hat ihren eigenen Schalter unter Skins → Tooltip.",
    ["wn_330_tooltip_inspect"] = "Tooltip: Wer über einen Spieler fährt, sieht jetzt dessen angelegte Gegenstandsstufe und Spezialisierung. Beides erfordert ein Untersuchen und erscheint daher nur in Reichweite; die Gegenstandsstufe wird nach dem Abstand zur eigenen eingefärbt statt nach Saisonschwellen, die mit jedem Patch veralten.",
    ["wn_330_tooltip_border"] = "Tooltip: Der Rahmen kann die Farbe der Einheit annehmen — Klassenfarbe bei Spielern, feindlich / neutral / freundlich bei NSCs — und die Stufenzeile wird nach Schwierigkeit eingefärbt, rot bei einem Boss oder einer „??“-Einheit.",
    ["wn_330_tooltip_bar"] = "Tooltip: Die Lebensleiste ist jetzt standardmäßig ausgeblendet, da die Informationsebene sie ersetzt. Bestehende Profile werden einmalig angepasst; wer die Option abwählt, bekommt die Leiste dauerhaft zurück.",
    ["wn_330_pf_leader"] = "Gruppenfenster: Der Gruppenanführer wird jetzt mit einer Krone über seinem Fenster markiert, mit eigenem Schalter und Größenregler.",
    ["wn_330_stance_bar"] = "Aktionsleisten: Klassen ohne Gestaltwandel-Formen bekamen eine Haltungsleiste mit zehn leeren Feldern, und das Abwählen von „leere Tastenplätze anzeigen“ ließ die ganze Haltungsleiste verschwinden. Die Leiste erscheint nur noch, wenn tatsächlich Formen vorhanden sind, und zeigt genau so viele Tasten wie Formen.",
    ["wn_330_leveling_panel"] = "Stufenleiste: Beim Überfahren öffnet sich jetzt ein gestaltetes Panel statt eines Tooltips — mit Stufe, EP, verbleibender EP, Fortschritt, Erholung, EP/h, Zeit bis zur Stufe, seit dem letzten Stufenaufstieg gesammelter EP und dem Beitrag der letzten Quest. Es klappt unter die Leiste, wenn darüber kein Platz ist.",
    ["wn_330_bags_click"] = "Taschen: Entzaubern, Zermahlen oder Prospektieren aus dem Taschen-Skin brauchte zwei Versuche — der Tastendruck verbrauchte den Zielcursor und das Loslassen hob stattdessen den Gegenstand auf. Es klappt jetzt beim ersten Mal, und das Ziehen ist unverändert.",
    ["wn_330_bags_layout"] = "Taschen: Das Layout „Kategorien“ wurde entfernt, es bleiben kombiniertes Raster und getrennte Taschen. Ein Profil, das noch darauf steht, wird einmalig auf das kombinierte Raster umgestellt.",
    ["wn_330_chat_copy"] = "Chat: Das Kopiersymbol pro Nachricht setzte vor jede Zeile ein Platzhalterzeichen, weil seine Textur nie aufgelöst wurde. Die Option wurde entfernt und einmalig für alle zurückgesetzt, die sie aktiviert hatten.",

    ["wn_331_tooltip_secret"] = "Tooltip: Die gesamte in 3.3.0 hinzugefügte Einheiten-Informationsebene erschien in Midnight nie — kein Gildenrang, kein Ziel, keine Mythisch+-Wertung, kein Reittier, kein Tempo, kein Ort, keine Gegenstandsstufe, keine Spezialisierung, keine Symbole in der Namenszeile. Die Ebene liest das Einheitenkürzel aus dem Tooltip zurück, das Spiel liefert es inzwischen als geschützten Wert, und die Absicherung wies ihn ab: Es wurde nie etwas geschrieben.",
    ["wn_331_tooltip_border"] = "Tooltip: Der Rahmen in der Farbe der Einheit war aus demselben Grund aus — er las das Kürzel über seine eigene Absicherung und gab auf, sodass jede Einheit auf die eingestellte Rahmenfarbe zurückfiel, was genau so aussah, als täte die Option nichts.",
    ["wn_331_tooltip_target"] = "Tooltip: Die Zielzeile entfiel bei jedem Spieler, dessen Name geschützt zurückkommt — also bei den meisten. Der Name wird nicht mehr in einen Farbcode eingefasst — diese Zeichenkette zu bauen bedeutet, den Namen zu lesen — und die Farbe läuft über die Farbargumente des Tooltips. Optisch identisch, und es funktioniert.",
    ["wn_331_tooltip_guards"] = "Tooltip: Die Absicherungen selbst konnten einen Fehler auslösen. Eine verglich den Wert mit einer leeren Zeichenkette, bevor sie prüfte, ob er geschützt ist, und stürzte damit genau bei den Werten ab, die sie abfangen sollte; dazu wurden rund zwanzig Ja/Nein-Prüfungen (existiert die Einheit, ist es ein Spieler, lässt sie sich untersuchen …) ungeschützt verglichen. Alles wird jetzt in der richtigen Reihenfolge geprüft.",
    ["wn_331_inspect"] = "Tooltip: Gegenstandsstufe und Spezialisierung sind mit dem Rest zurück — die Untersuchungs-Engine führte bei jeder Eignungsprüfung dieselben ungeschützten Vergleiche durch und gab bei einem geschützten Wert auf, noch bevor eine Anfrage gesendet wurde.",
    ["wn_330_tracker_delve"] = "Zielverfolgung: In einer Tiefe zeigte die Verfolgung überhaupt nichts mehr — weder Stufe noch Kriterien noch Fortschritt. „Ausblenden wenn leer“ zählte nur Questblöcke, während eine Tiefe ihren Fortschritt im Szenariomodul führt, das bei dieser Zählung bewusst außen vor bleibt — also wurde das ganze Panel ausgeblendet. Tiefen, Szenarien und Bonusziele zählen jetzt als Inhalt, und das Panel passt seine Größe an sie an, wenn sie allein auf dem Bildschirm sind.",
    ["wn_327_tracker_progressbars"] = "Zielverfolgung: Die Fortschrittsleisten der Quests (Tötungszähler, feindliche Streitkräfte, Szenario- und Tiefenkriterien) sind zurück — eine Leiste wird nicht mehr als verwaist entfernt, wenn ihr Block nur über einen Anker erreichbar ist, sie übersteht das Ein- und wieder Ausklappen ihrer Gruppe, und die verbleibenden Leisten übernehmen endlich das Design der übrigen Verfolgung.",
    ["wn_327_tracker_position"] = "Zielverfolgung: Eine per Blizzards eigenem Bearbeitungsmodus verschobene Verfolgung sprang beim nächsten Neuladen an ihre alte Stelle zurück — diese Position wurde nie in die Datenbank des Addons geschrieben. Sie wird jetzt am Ende der Bearbeitungssitzung gespeichert, und eine Verfolgung mit einer anderen Skalierung als 100 % wandert nicht mehr bei jedem Neuladen ein Stück weiter.",
    ["wn_327_minimap_indicators"] = "Minikarte: Die Schwierigkeitsanzeige blieb außerhalb von Instanzen sichtbar, weil das Neuverankern der nativen Anzeigen sie zugleich sichtbar erzwang und Blizzards eigene Regel überschrieb. Sie folgen wieder Blizzards Sichtbarkeit — und der Erweiterungsknopf bleibt nicht mehr dauerhaft unsichtbar, wenn man ihn aus- und wieder einschaltet.",
    ["wn_327_resourcebar_frozen"] ="Ressourcenleisten: Die zentrierte Energieleiste blieb auf dem Wert stehen, den sie beim Erstellen hatte — 0 Wut, 0 Energie — bei allen Spezialisierungen, deren einzige Ressource die primäre ist (Krieger, Priester, Feuermagier, Nebelwirker, Verwüstung...), während das Einheitenfenster direkt daneben den echten Wert anzeigte. Sie aktualisiert sich wieder wie jede andere Leiste.",
    ["wn_327_profile_rename"] ="Profile: Umbenennen oder Duplizieren eines Profils bewirkte überhaupt nichts — Blizzards Popup-Umbau in 11.2 entfernte das Feld, aus dem der eingegebene Name gelesen wurde. Beides funktioniert wieder, und Enter bestätigt nun wie die Bestätigungsschaltfläche.",
    ["wn_327_cds_rename"] = "Cooldown Studio: derselbe Fehler bei den Popups „Leiste umbenennen“ und „+ Neu“ — der eingegebene Name wurde ignoriert, das Umbenennen tat also nichts und jede neue Leiste hieß „Nouvelle barre“.",
    ["wn_327_popup_layer"] = "Popups: Die Neuladen-Abfrage, die Import-/Export-Fenster und alle Profilbestätigungen wurden hinter dem Konfigurationsfenster und dem Cooldown Studio gezeichnet, sodass scheinbar nichts passierte. Sie erscheinen jetzt über dem gerade geöffneten TomoMod-Fenster.",
    ["wn_327_profile_refresh"] = "Profile: Anlegen, Löschen, Umbenennen oder Duplizieren eines Profils aktualisiert jetzt die angezeigte Liste, statt die alte aus dem Seiten-Cache stehen zu lassen.",
    ["wn_327_import_perf"] = "Profile: Der Import ist deutlich schneller — die für die Vorschau dekodierte Zeichenkette wird beim Bestätigen wiederverwendet statt ein zweites Mal dekodiert zu werden, was den Großteil des Einfrierens beim Klick auf Importieren ausmachte.",
    ["wn_327_gui_split"] = "Konfiguration: Profile und Diagnose sind in der Seitenleiste wieder eigenständige Kategorien statt unter Werkzeuge zusammengefasst, jede mit eigenem Symbol und eigener Beschreibung; alte Links auf Werkzeuge funktionieren weiterhin.",

    -- =====================
    -- Fehlende Ubersetzungen -- these keys previously fell back to enUS
