    ["wn_300_minimap"]                    = "Minikarten-Schaltfläche — schneller Zugriff auf die Funktionen und Einstellungen von TomoMod.",
    ["wn_300_buttonbag"]                  = "Button Bag — bündelt und verwaltet deine Aktionsschaltflächen effizient.",
    ["tab_qol_rare_alert"]                = "Seltene Gegner",
    ["section_rare_alert"]                = "Seltene Gegner",
    ["opt_rare_alert_enable"]             = "Näherungswarnung für seltene Gegner aktivieren",
    ["opt_rare_alert_sound"]              = "Warnton abspielen",
    ["opt_rare_alert_duration"]           = "Anzeigedauer des Banners (Sek.)",
    ["btn_reset_rare_alert_pos"]          = "Bannerposition zurücksetzen",
    ["rare_alert_info"]                   = "Warnt dich, wenn ein seltener NSC in der Nähe ist. Klicke auf das Banner, um ihn ins Visier zu nehmen, die Totenkopfmarkierung zu setzen und einen Wegpunkt anzulegen. Rechtsklick zum Schließen. Mit /tm layout lässt sich das Banner verschieben.",
    ["rare_alert_tooltip"]                = "Linksklick: anvisieren + Totenkopf + Wegpunkt. Rechtsklick: schließen.",
    ["wn_305_rare_alert_marker"]          = "Klicke auf das Banner eines seltenen Gegners, um ihn anzuvisieren, die Totenkopfmarkierung zu setzen und einen Wegpunkt anzulegen. Ton und Dauer sind einstellbar, das Banner lässt sich im Layoutmodus verschieben.",
    ["wn_305_tm_fix"]                     = "Behoben — ein Klick auf eine RareScanner-Warnung öffnet nicht mehr die TomoMod-Konfiguration (die Kollision des Befehls /tm ist beseitigt).",

    -- =====================
    -- 3.3.2 — Was ist neu
    -- =====================
    ["wn_332_perf_auras"] = "Leistung: Die Aura-Überwachung und die Stärkungszauber-Optik lauschen jetzt nur noch auf deine eigenen Aura-Änderungen. Sie haben ohnehin immer nur auf dich reagiert, wurden aber für jede Einheit geweckt, deren Auren sich änderten — zwanzig und mehr Schlachtzugsmitglieder plus jede sichtbare Namensplakette, ununterbrochen — nur um die Einheit zu prüfen und zu verwerfen. Das Spiel filtert sie nun aus, bevor überhaupt Code von uns läuft.",
    ["wn_332_perf_castbar"] = "Leistung: Dasselbe für die Latenzmessung der Zauberleiste, die von jedem Zauber jeder sichtbaren Einheit geweckt wurde — ein kompletter Trashpack voller Fähigkeiten —, obwohl nur deine eigenen Zauber je eine Rolle spielten.",
    ["wn_332_perf_gc"] = "Leistung: Die Aura-Überwachung war die größte Quelle von Speichermüll in der Oberfläche. Ihr Scan und ihr Layout liefen im Kampf mehrmals pro Sekunde und warfen bei jedem Durchgang einen Stapel temporärer Tabellen weg; sie verwenden nun dieselben Arbeitstabellen wieder. Auf dem Bildschirm ändert sich nichts.",
    ["wn_332_aura_order"] = "Aura-Überwachung: Zwei Auren, die mit demselben Zauber und derselben Dauer angewendet wurden, konnten zwischen zwei Aktualisierungen sichtbar die Plätze tauschen, weil ihre Reihenfolge nirgends festgelegt war. Sie ist jetzt stabil.",
    ["wn_332_skyride_leak"] = "Drachenreiten: /tm skyride baute bei jeder Verwendung eine zweite Kopie der Leiste. Die alte blieb auf dem Bildschirm, mit nichts mehr verbunden und nicht mehr ausblendbar, denn das Spiel gibt einen Rahmen nie wieder frei. Die Leiste wird jetzt nur einmal gebaut, und der Befehl wendet lediglich deine Einstellungen erneut darauf an.",
    ["wn_332_skyride_ticker"] = "Drachenreiten: Derselbe Befehl hinterließ zudem jedes Mal eine dauerhafte Aktualisierung mit 4 Hz, die sich nicht mehr stoppen ließ. Sie summieren sich nicht mehr, und die Aktualisierung endet, wenn das Modul deaktiviert wird, statt eine unsichtbare Leiste abzufragen.",
    ["wn_332_tooltip_incombat"] = "Tooltip: Gegenstandsstufe und Spezialisierung verschwanden aus jedem Tooltip, sobald ein Kampf begann, und kamen erst danach zurück. Die Reichweitenprüfung, mit der die Inspektionslogik endete, gehört zu denen, die das Spiel Addons im Kampf verweigert: Damit galt während des gesamten Pulls jede Einheit als außer Reichweite — während sich das Verfälschungsprotokoll mit einem blockierten Aufruf pro Mauszeigerkontakt füllte. Jetzt wird eine Prüfung verwendet, die auch im Kampf funktioniert.",
    ["wn_332_tooltip_backoff"] = "Tooltip: Die neue Reichweitenprüfung ist ungenauer (sie reicht deutlich weiter, als eine Inspektion tatsächlich greift), deshalb wird ein zu weit entfernter Spieler nun gemerkt und zwanzig Sekunden lang in Ruhe gelassen, statt bei jedem Tooltip erneut angefragt zu werden. Es kann immer nur eine Inspektion gleichzeitig laufen, und ein Spieler außer Reichweite belegte diesen Platz wieder und wieder. Ein Tooltip ohne Antwort bleibt zudem nicht mehr auf „lädt“ hängen.",
    ["wn_332_diag_nopath"] = "Diagnose: Über eine Lücke zu stürmen, auf einen Vorsprung zu springen oder einen Begleiter dorthin zu schicken, wo er nicht laufen kann, wurde im Bericht als Fehler protokolliert. „Kein Weg verfügbar“ ist normale Spielrückmeldung und wird jetzt in allen sechs Sprachen herausgefiltert.",
    ["wn_332_locale_castbar"] = "Konfiguration: Das Hauptkästchen im Reiter Zauberleisten war in allen Sprachen mit „Verbrauchsgüterleiste aktivieren“ beschriftet — zwei verschiedene Optionen teilten sich denselben Übersetzungsschlüssel, und die der Verbrauchsgüter setzte sich durch. Jede hat jetzt ihren eigenen.",
    ["wn_332_locale_translations"] = "Lokalisierung: 173 Zeichenketten je Sprache ins Deutsche, Spanische, Italienische und Portugiesische übersetzt — erweiterte und Sichtbarkeitseinstellungen der Abklingzeitverwaltung, Questkategorien der Questverfolgung, Chatfenster-UI, Verschiebepunkte und Cursor-Texturen — dazu die 49 Zeichenketten der Chatfenster-UI auf Französisch. Sie fielen still auf Englisch zurück, statt einen Fehler zu zeigen, und wurden deshalb nie gemeldet.",
    ["wn_332_locale_search"] = "Konfiguration: Das Suchfeld zeigte den rohen Text „gs_no_results“ statt „Keine passende Option“, wenn nichts passte. Die Meldung ist jetzt in allen sechs Sprachen definiert.",
    ["wn_332_package"] = "Paket: Der Download enthält nicht mehr die Testsuiten, Beispiele, generierten Dokumentationen und Readme-Dateien der mitgelieferten Bibliotheken. Nichts davon wurde je vom Addon geladen.",
    ["wn_332_companion_panel"] = "Begleiter-Hinweis: Das Modul, das dich warnt, wenn dein Begleiter fehlt oder tot ist, hat endlich ein Einstellungsfenster unter QOL. Aktivierung, Größe, Skalierung, die Anzeige von Symbol, Text oder beidem und die Position auf dem Bildschirm ließen sich bisher nur durch händisches Bearbeiten einer Datei ändern.",
    ["wn_332_companion_travel"] = "Begleiter-Hinweis: Er konnte in vierfacher Größe während eines ganzen Fluges auf dem Bildschirm bleiben. Ob du fliegst, wurde nur in Momenten geprüft, in denen du noch am Boden standest, und danach konnte ihn nichts mehr ausblenden. Er wird jetzt im Flug, auf Flugrouten und in Fahrzeugen ausgeblendet — und auch auf einem Bodenreittier, was sich wieder abschalten lässt.",
    ["wn_332_companion_locale"] = "Begleiter-Hinweis: „Begleiter fehlt“ und „Begleiter tot“ erschienen unabhängig von der Client-Sprache auf Englisch. Beide sind jetzt übersetzt, ebenso das gesamte neue Fenster.",

    -- =====================
    -- 3.3.3 — Was ist neu
    -- =====================
    ["wn_333_summon_stuck"] = "Gruppen- und Schlachtzugsfenster: Das Beschwörungssymbol blieb bis zum Neuladen der Oberfläche stehen. Nach dem Annehmen oder Ablehnen meldet das Spiel weiterhin den letzten Zustand der Beschwörung, statt ihn zu löschen — das Symbol beschrieb also etwas, das seit Minuten nicht mehr existierte. Es wird jetzt geprüft, ob überhaupt noch eine Beschwörung offen ist, bevor etwas angezeigt wird.",
    ["wn_333_summon_roster"] = "Gruppen- und Schlachtzugsfenster: Bei einer Änderung der Gruppenzusammensetzung konnte ein Beschwörungssymbol auf einem Fenster stehen bleiben, das inzwischen einem anderen Spieler gehörte. Der Zustand wird bei jeder Gruppenänderung und nach jedem Zonenwechsel neu gelesen und zusammen mit dem restlichen Fenster aktualisiert, statt nur dann, wenn das Spiel eine Änderung meldet.",
    ["wn_333_defensives_party"] = "Gruppenfenster: Aktive Verteidigungs-Cooldowns werden jetzt bei jedem Mitglied angezeigt. Bisher gab es das nur bei den Schlachtzugsfenstern, und dort war es ein einzelnes Symbol ohne Dauer und ohne Hinweis darauf, worum es sich handelte.",
    ["wn_333_defensives_categories"] = "Gruppen- und Schlachtzugsfenster: Verteidigungen werden in externe (auf diesen Spieler gewirkt — Eisenrinde, Lebenskokon, Schmerzunterdrückung), schlachtzugsweite (Sammelschrei, Dunkelheit, Antimagiezone) und persönliche (Gottesschild, Eisblock, Baumrinde) unterteilt, jede mit eigener Option. Fünfzig Zauber, so sortiert, dass externe zuerst kommen, mit Restdauer und einem nach Kategorie gefärbten Rahmen.",
    ["wn_333_defensives_defaults"] = "Gruppen- und Schlachtzugsfenster: Standardmäßig werden nur externe angezeigt. Ein schlachtzugsweiter Cooldown lässt alle Fenster gleichzeitig aufleuchten — genau dann, wenn sie am schlechtesten lesbar sind — und persönliche laufen ständig. Beide lassen sich einschalten.",
    ["wn_333_defensives_size"] = "Schlachtzugsfenster: Der Regler für die Größe der Verteidigungssymbole wirkte erst nach einem Neuladen. Er greift jetzt schon beim Ziehen.",
    ["wn_333_hots_drift"] = "Gruppen- und Schlachtzugsfenster: Die beiden Fenstersätze waren sich nicht einig, welche Heilung-über-Zeit-Effekte anzuzeigen sind. Segen des Sommers, Wolkenbruchtotem und Einhüllender Atem erschienen in den Gruppenfenstern, aber nicht in den Schlachtzugsfenstern — derselbe Buff, beim selben Spieler, auf der einen Seite sichtbar und auf der anderen nicht. Es gibt jetzt nur noch eine Liste, die alle sechs Heilerklassen abdeckt.",
    ["wn_333_dispel_border"] = "Gruppen- und Schlachtzugsfenster: Die Randstärke der Entzauberungs-Hervorhebung ist jetzt einstellbar, von 1 bis 6. Der Rand wächst nach außen, ein dickerer Rand schneidet also nie in die Lebensleiste hinein, und der Standardwert sieht genauso aus wie bisher.",
    ["wn_333_stance_grid"] = "Aktionsleisten: Bei deaktivierter Option „Leere Tastenplätze anzeigen“ konnte die Haltungsleiste trotzdem zehn leere Kästchen anzeigen, und sie blieben stehen, bis die Haltung gewechselt wurde. Der Durchlauf, der leere Plätze einblendet, während ein Zauber am Mauszeiger hängt, lief auch über die Haltungs- und die Begleiterleiste, deren Tasten überhaupt keine Aktionsplätze sind — er hielt also jede einzelne für leer und zeigte sie an, während der Durchlauf, der sie wieder ausblendet, genau diese beiden Leisten bewusst überspringt und somit nichts mehr übrig blieb, das sie zurückgenommen hätte.",
    ["wn_333_diag_display"] = "Diagnose: Berichte enthalten jetzt Auflösung, Anzeigemodus und Oberflächenskalierung — und weisen darauf hin, wenn die Skalierung von etwas anderem als den Spieloptionen gesetzt wurde. Oberhalb von 1200 Pixeln Höhe verkleinert der Client die Oberfläche nicht mehr weit genug, weshalb hochauflösende Systeme von Hand oder durch ein anderes Addon skaliert werden — und das war in einem Bericht bisher unsichtbar.",
    ["wn_333_diag_scalechange"] = "Diagnose: Eine Änderung der Skalierung oder der Auflösung während der Sitzung wird mit Vorher- und Nachher-Werten protokolliert, sodass eine Neuskalierung direkt neben den Fehlern auftaucht, die sie verursacht haben könnte. Diese Neuskalierung wird nach jedem Ladebildschirm erneut angewendet, und genau dann geht etwas kaputt.",
    ["wn_333_diag_perf"] = "Diagnose: Berichte enthalten jetzt die Bildrate (aktuell sowie Minimum, Durchschnitt und Maximum der Sitzung) und die Latenz, und jeder erfasste Fehler hält die Bildrate zum Zeitpunkt seines Auftretens fest. Ein Fehler, der nur auf einem stockenden Client erscheint, ist ein Timing-Problem und keine kaputte Funktion — und nichts in einem Bericht konnte beides bisher unterscheiden.",
    ["wn_333_diag_scale_expected"] = "Diagnose: Der Bericht behauptete bei nahezu jeder Konfiguration, die Oberflächenskalierung sei von einem Makro oder einem anderen Addon gesetzt worden. Ist die Skalierungsoption des Spiels ausgeschaltet, ist der Wert, mit dem verglichen wurde, gar nicht der, den das Spiel verwendet — eine völlig gewöhnliche Konfiguration wurde also gemeldet. Jetzt wird ermittelt, welche Skalierung für Auflösung und Einstellungen zu erwarten ist, dieser Wert wird ausgegeben, und gewarnt wird nur bei einer echten Abweichung.",
    ["wn_333_diag_settle"] = "Diagnose: Die Skalierung, die das Spiel während der Anmeldung selbst anwendet, wurde in jedem Bericht als Neuskalierung mitten in der Sitzung festgehalten. Die Anzeigeerfassung wartet nun vier Sekunden, bis sich der Client eingependelt hat, bevor sie misst — der einzige verbliebene Skalierungseintrag in einem Bericht ist damit einer, der tatsächlich erklärungsbedürftig ist.",
    ["wn_333_diag_mode"] = "Diagnose: Wenn der Bericht den Anzeigemodus nicht bestimmen kann, gibt er jetzt die Rohwerte aus, die das Spiel geliefert hat, statt eines bloßen Fragezeichens — diese Einstellungsnamen ändern sich von Erweiterung zu Erweiterung, und ein alleinstehendes „?“ ließ sich ohne Rückfrage nicht auswerten. Vollbildfenster und maximierte Fenster werden in mehr Fällen erkannt, und Addon-Versionen lauten nicht mehr „vv1.2.3“.",
    ["wn_333_shared"] = "Intern: Die Gruppen- und Schlachtzugsfenster hielten zwei Kopien derselben 250 Zeilen vor — die Beschwörungslogik, die Liste der Heilung-über-Zeit-Effekte, die Verteidigungsverfolgung. Alle drei Fehler oben rühren daher: eine Korrektur, die an einer Kopie vorgenommen wurde und an der anderen nicht. Sie teilen sich jetzt eine einzige Implementierung.",
    -- =====================
    -- 3.6.2 — What's New
    -- =====================
    ["wn_362_vault_types"] = "Behoben — Die Vorschau der Großen Schatzkammer im Mythic Hub liest ihre Zeilen für Schlachtzüge, Dungeons und Tiefen jetzt aus Blizzards offiziellen Belohnungstypen, statt sie aus dem zu erraten, was die Wochenbelohnungs-API gerade zurückgab. Die Tiefen-Zeile bleibt dadurch nicht mehr leer und zeigt auch nicht mehr die Aktivitäten einer anderen Zeile.",
    ["wn_362_vault_progress"] = "Behoben — Die Vorschau der Großen Schatzkammer erzwingt keine Aktualisierung von Blizzards eigenem Wochenbelohnungs-Fenster mehr, bevor sie deinen Fortschritt ausliest. Diese Aktualisierung setzt den Aktivitätsfortschritt auf null zurück, solange eine frühere Belohnung noch abgeholt werden kann — abgeschlossene Dungeons, Schlachtzugsbosse und Tiefen wurden dadurch als 0 angezeigt.",
    ["wn_362_vault_slots"] = "Behoben — Jede Zeile der Großen Schatzkammer fragt ihre Aktivitäten jetzt einzeln beim Spiel ab und sortiert sie nach Belohnungsstufe. Die zusätzlichen Einträge, die die API neben den echten Zeilen zurückgibt (Bonus- und Aufholbelohnungen), können damit keinen sichtbaren Platz mehr belegen.",
    ["wn_362_ab_release"] = "Behoben — Aktionsbuttons reagieren wieder auf das Loslassen eines Klicks. TomoMods eigenen Buttons fehlte das sichere Loslassen-Attribut, das Blizzard auf seinen Aktionsbuttons setzt: Bei deaktiviertem „Beim Tastendruck wirken“ wurde gar nichts gewirkt, und Zauber zum Gedrückthalten wie die verstärkten Zauber des Rufers ließen sich zwar beginnen, aber nie auslösen.",
    ["wn_362_ab_release_gse"] = "Behoben — Ein Button, der für eine GSE-Sequenz verwendet wurde, kehrt jetzt zum normalen Drücken-und-Loslassen-Verhalten einer regulären Aktion zurück, sobald sich seine Aktion ändert, statt den GSE-Vertrag bis zum nächsten Reload beizubehalten.",
    ["wn_362_ab_cooldown_push"] = "Behoben — Die Abklingzeit-Anzeigen der Aktionsbuttons folgen jetzt exakt dem Spiel. TomoMod hielt eine kurzlebige Kopie des Abklingzeit-Zustands jedes Buttons und verwendete sie bis zu einem Sekundenbruchteil weiter, wodurch der Beginn oder das Ende einer Abklingzeit verborgen bleiben konnte — vor allem bei kurzen Abklingzeiten und in dem kurzen Moment, in dem der Server einen Zauber bestätigt. Der Zustand wird jetzt jedes Mal neu gelesen, während wiederholte Abfragen innerhalb eines Aktualisierungsdurchlaufs weiterhin geteilt werden.",
    ["wn_362_ab_counts"] = "Behoben — Ladungs- und Stapelzähler der Aktionsleisten lösen nicht mehr für jedes Aura- oder Ladungsereignis eine vollständige Aktualisierung aller Buttons aus. Bei großen Mythisch+-Pulls treffen diese Ereignisse in Schüben ein; im Kampf wird die Arbeit jetzt einige Male pro Sekunde gebündelt, sodass Tastendrücke reaktionsschnell bleiben. Außerhalb des Kampfes wird nichts gedrosselt.",
    ["wn_362_ab_glow"] = "Behoben — Der Sicherheitsdurchlauf, der übrig gebliebene Proc-Leuchteffekte entfernt, durchsucht nicht mehr für jedes Leuchtereignis alle sichtbaren Aktionsbuttons. Der Button, der sein Leuchten verliert, wird weiterhin sofort aktualisiert, und die vollständige Prüfung läuft jetzt höchstens zehnmal pro Sekunde — proclastige Kämpfe kosten damit keine Eingabeverzögerung mehr.",
    ["wn_362_ab_assist_rotation"] = "Geändert — Verbündeter Kampf findet seine Aktionsbuttons jetzt über die dafür vorgesehene Slot-API des Spiels, statt alle Leisten nach dem aktuell vorgeschlagenen Zauber zu durchsuchen. Ein Wechsel des Vorschlags berührt dadurch keine unbeteiligten Buttons mehr.",
    ["wn_362_ab_assist_load"] = "Behoben — Ein Wechsel des Verbündeter-Kampf-Vorschlags aktualisiert nicht mehr sämtliche TomoMod-Aktionsbuttons, und TomoMod hängt sich nicht mehr in eine Blizzard-Hervorhebungsfunktion ein, die im Kampf in Rotationsgeschwindigkeit aufgerufen werden kann. Beides zusammen war die größte Quelle zusätzlicher Arbeit, solange die One-Button-Rotation aktiv war.",
    ["wn_362_ab_assist_highlight"] = "Behoben — Die Verbündeter-Kampf-Hervorhebung wird jetzt entfernt, sobald das Spiel keinen Zauber mehr vorschlägt, und das Umschalten von Blizzards Option für die unterstützte Hervorhebung wirkt sofort, statt einen Reload zu erfordern.",
    ["wn_362_rb_toggles"] = "Neu — Zwei neue Optionen unter Animationen & Kraftbalken: Die eine schaltet das Leuchten ab, das erscheint, wenn eine Klassenressource ihr Maximum erreicht, die andere die Darstellung aufgeladener Kombopunkte für Schurken. Beide sind standardmäßig aktiv, und das Abschalten stellt sofort das normale Aussehen der bereits sichtbaren Punkte wieder her.",
    ["wn_362_rb_glow_stop"] = "Behoben — Das Leuchten bei maximaler Ressource bleibt nicht mehr sichtbar, wenn es längst verschwunden sein sollte. Es wird jetzt beendet, sobald die Option abgeschaltet wird und wenn die Klassenressourcen-Anzeige neu aufgebaut wird, statt auf einem bereits verworfenen Frame weiterzulaufen.",
    -- =====================
    -- 3.6.1 — What's New
    -- =====================
    ["wn_361_assist"] = "Behoben — Blizzards Verbündeter-Kampf-Rotationsrahmen wird auf TomoMod-Aktionsbuttons jetzt korrekt angezeigt und aktualisiert, statt am unsynchronisierten Lua-Aktionsfeld des Buttons einzufrieren.",
    ["wn_361_keydown"] = "Behoben — TomoMods Einstellung „Beim Tastendruck wirken“ bleibt jetzt mit Blizzards eigener Eingabe-CVar synchron; dies behebt einen ersten Tastendruck nach dem Login, der zuvor stillschweigend verschluckt werden konnte.",
    ["wn_361_safewindow"] = "Behoben — Durch Kampf verzögerte Override-Bindungen nach einem /reload im Kampf werden jetzt zuverlässig nach dem Kampf wiederhergestellt, statt sich auf ein Sicherheitsfenster zu verlassen, das selbst blockierte Aktionen zulassen konnte.",
    ["wn_361_strata"] = "Behoben — Aktionsleiste 1, Begleiter- und Haltungsbuttons werden nicht mehr über Blizzard-Vollbildfenstern wie der Weltkarte dargestellt.",
    ["wn_361_flyouts"] = "Behoben — Zauber-Flyouts wie Magier-Portal/Teleport öffnen sich und wirken wieder korrekt; TomoMod ändert die Größe nativer Flyout-Buttons nicht mehr auf eine Weise, die den sicheren Flyout beschmutzen (taint) konnte.",
    ["wn_361_flyouts_cast"] = "Behoben — Native Flyout-Popup-Buttons werden überhaupt nicht mehr gehookt oder beschrieben, da selbst kosmetische Änderungen Blizzards geschützten CastSpellByID/CastSpellByName-Wirkpfad beschmutzen (taint) konnten.",
    ["wn_361_flyout_secure"] = "Behoben — TomoMod-Aktionsbuttons aktualisieren ihr Zauber-Flyout jetzt über Blizzards eigenes UpdateFlyout innerhalb eines sicheren Aufrufs, und TomoMods Ersatz-Popup-Methoden wurden von den eigenen Buttons entfernt. Der Flyout-Pfeil, das dadurch geöffnete Popup und das anschließende Wirken bleiben damit vollständig auf Blizzards geschütztem Pfad.",
    ["wn_361_bar6_quarantine"] = "Behoben — Zauber-Flyouts auf Leiste 6 laufen nicht mehr Gefahr, nicht mehr gewirkt werden zu können: Diese Leiste verwendet jetzt TomoMods eigenes sicheres Flyout anstelle von Blizzards nativem, da das native Flyout speziell beim Öffnen von Leiste 6 weiterhin kontaminiert werden konnte. Alle anderen Leisten verwenden weiterhin Blizzards natives Flyout.",
    ["wn_361_flyout_keybind"] = "Behoben — Das Drücken einer zugewiesenen Tastenkombination zum Öffnen oder Schließen eines TomoMod-Flyout-Buttons funktioniert jetzt korrekt; zuvor wurde nur ein Mausklick erkannt.",
    ["wn_361_flyout_discovery"] = "Behoben — TomoMod durchsucht jetzt zusätzlich die tatsächlichen Aktionsplätze der isolierten Leiste nach ihren Flyouts, statt sich nur auf die Zauberbuch-Erkennung zu verlassen, sodass dort platzierte Flyouts stets die korrekten Bekannt/Unbekannt-Symbole zeigen.",
    ["wn_361_vehicle_mover"] = "Neu — „Fahrzeug verlassen“ besitzt jetzt einen eigenen Positionsrahmen im Layout-Modus und kann frei auf dem Bildschirm platziert werden, statt fest über Aktionsleiste 1 zu sitzen. Die Position wird mit dem Profil gespeichert; standardmäßig bleibt der Button direkt über Leiste 1, bis er verschoben wird.",
    ["wn_361_vehicle_state"] = "Geändert — Der Button „Fahrzeug verlassen“ wird jetzt angezeigt, sobald das Fahrzeug tatsächlich verlassen werden kann, statt sobald eine Fahrzeugoberfläche eingeblendet ist. Er erscheint dadurch nicht mehr bei Fahrzeugen, die nicht verlassen werden können.",
    ["wn_361_vehicle_taxi"] = "Behoben — Blizzards eigener „Fahrzeug verlassen“-Button wird jetzt nur noch ausgeblendet, solange TomoMods sicherer Ersatz nutzbar ist. So bleibt auf Taxiflügen und in Fahrzeugen ohne vorzeitigen Ausstieg eine funktionierende Ausstiegssteuerung erhalten.",
    ["wn_361_tracker"] = "Behoben — Im Kampf übersprungene Questblöcke des Questzielverfolgers werden nach Kampfende jetzt automatisch fertig angeordnet, statt bis zu einem unabhängigen Questereignis überlappend stehen zu bleiben.",
    ["wn_361_buttonbag"] = "Behoben — Der Minikarten-Sammler für Addon-Buttons vergisst beim erneuten Suchen die bereits eingesammelten Buttons nicht mehr: Addons, die ihren Button später registrieren, öffnen jetzt eine neue Zeile, statt sich auf die erste zu stapeln.",
    ["wn_361_trackdupe"] = "Behoben — Das Verfolgen-Fenster listet denselben Eintrag nicht mehr doppelt auf („Bankier“ erschien in zwei Zeilen). Verfolgungsfilter, die das Spiel unter demselben Namen meldet, werden zu einer einzigen Zeile zusammengefasst, die sie gemeinsam umschaltet.",
    ["wn_361_micromenu_native"] = "Behoben — TomoMod erstellt für Blizzards Mikromenü keinen eigenen Container mehr, hängt keine Buttons um und greift nicht mehr ins Layout ein; das alte eigenständige Mikroleisten-Modul wurde vollständig entfernt.",
    ["wn_361_micromenu_gui"] = "Geändert — Das Optionsfenster „Tasche & Mikromenü“ zeigt jetzt einen kompakten Abschnitt für das Gruppensuche-Auge anstelle des alten Mikroleisten-Baukastens, nur noch mit Ein/Aus-Schalter und Größenregler.",
    ["wn_361_lfgeye_fix"] = "Behoben — Das Gruppensuche-Auge verschwindet nicht mehr, wenn das Mikromenü beim Mausüberfahren ausgeblendet wird; es hat jetzt eine eigene Sichtbarkeits- und Größenverwaltung, die automatisch aktualisiert wird, wenn du die Welt betrittst, dich in eine Warteschlange einreihst oder eine Instanz/Schlachtfeld startet.",
    ["wn_361_validation"] = "Getestet — Verbündeter Kampf, Tastendruck-Wirken, Override-Bindungen nach Kampf-Reload, Leiste 1/Begleiter/Haltung nahe der Weltkarte, Zauber-Flyouts, die Kampfverzögerung des Questzielverfolgers und das Gruppensuche-Auge bei Mikromenü-Fade/LFG-Ereignissen wurden im Spiel getestet.",
    -- =====================
    -- 3.6.0 — What's New
    -- =====================
    ["wn_360_foundation"] = "Geändert — Die Aktionsleisten verwenden jetzt ein Zero-Taint-Besitzmodell: TomoMod hält eigene Schaltflächen aus Blizzards nativer ActionButton-Verteilung heraus und überlässt geschützte Blizzard-Leistenzustände vollständig Blizzard.",
    ["wn_360_nativebars"] = "Behoben — Blizzards Standard-Aktionsleisten bleiben für sicheres Paging aktiv, werden aber visuell ausgeblendet, sodass nur TomoMod-Leisten sichtbar sind, ohne ihren Laufzeitzustand einzufrieren.",
    ["wn_360_specialvisuals"] = "Behoben — Blizzards Haltungs-, Begleiter- und Besitzleisten bleiben im Hintergrund funktionsfähig, während doppelte Texturen, Texte, GCD-Wipes, Autocast-Effekte, aktive Rahmen und Blitze maskiert werden.",
    ["wn_360_stance"] = "Behoben — TomoMods Haltungsbuttons verwenden jetzt unabhängige sichere Zauberaktionen und bleiben für Druidenformen, Paladinauren und Kriegerhaltungen anklickbar.",
    ["wn_360_pet"] = "Behoben — TomoMods Begleiterbuttons verwenden jetzt unabhängige sichere Begleiteraktionen; Befehle, Fähigkeiten und Rechtsklick-Autocast funktionieren ohne sichtbare Blizzard-Begleiterleiste.",
    ["wn_360_possess"] = "Behoben — Besitz- und Fahrzeugzustände laufen weiterhin über das sichere Paging von Aktionsleiste 1, statt Blizzards PossessActionBar durch TomoMod verändern zu müssen.",
    ["wn_360_paging"] = "Behoben — Aktionsleiste 1 liest ihren aktuellen sicheren Aktionsplatz direkt, sodass Formen-, Fahrzeug-, Override- und Besitz-Paging aktiv bleiben und nicht in einer Lua-Kopie einfrieren.",
    ["wn_360_formsafe"] = "Behoben — Druidenwechsel zwischen Mensch/Katze/Bär aktualisieren Aktionsleiste 1 jetzt im und außerhalb des Kampfes korrekt; in Tests traten keine geschützten Aktions- oder geheimen Cooldown-Fehler auf.",
    ["wn_360_extra"] = "Behoben — Extra Action behält Blizzards sicheres Spielverhalten, während TomoMod den sichtbaren Button, eigenen GCD/Ladungen und eine klicksichere Darstellung ohne unsichtbare native Hitbox bereitstellt.",
    ["wn_360_zone"] = "Behoben — Zonenfähigkeiten behalten dynamische Statussymbole, GCD und Ladungen, verschwinden wenn sie nicht mehr aktiv sind und bewahren natives Klickverhalten für entsprechende Questfähigkeiten.",
    ["wn_360_vehicle"] = "Behoben — Fahrzeug verlassen bleibt eine sichere TomoMod-Aktion mit gemeinsamem ActionBar-Skin; Blizzards Taxi-Verhalten bleibt bei Bedarf verfügbar.",
    ["wn_360_gcd"] = "Behoben — Verbleibende native GCD-Anzeigen für Haltung/Aura/Form werden visuell maskiert, ohne Blizzard-Cooldownwerte oder geschützten Buttonzustand anzutasten.",
    ["wn_360_petvisuals"] = "Behoben — Die verbleibenden aktiven Rahmen, Flash-Effekte und Autocast-Overlays der Blizzard-Begleiterleiste sind verborgen, während der echte Begleiterzustand vollständig funktioniert.",
    ["wn_360_skin"] = "Geändert — Extra Action, Zonenfähigkeit und Fahrzeug verlassen verwenden jetzt dieselbe reguläre TomoMod-Button-Skin-Pipeline wie die übrigen Aktionsleisten.",
    ["wn_360_flyouts"] = "Behoben — Zauber-Flyouts öffnen sich wieder korrekt über TomoMod-Aktionsleisten, einschließlich Magierportalen und Jägerfallen.",
    ["wn_360_installer"] = "Behoben — Der Ersteinrichtungsassistent wird bei Neuinstallationen zuverlässig geladen und wartet mit dem Anzeigen, bis Zwischensequenzen, Filme und Kämpfe beendet sind.",
    ["wn_360_rolesafe"] = "Behoben — Gruppen-/Schlachtzugsfenster, Namensplaketten, TomoScore, Chat und Tooltips verarbeiten Midnights eingeschränkte Rollendaten jetzt sicher, statt Secret-Value-Fehler auszulösen.",
    ["wn_360_mythiccombat"] = "Behoben — MythicHub und TomoScore-Befehle warten jetzt bis zum Kampfende, bevor geschützte Bedienelemente geöffnet oder aktualisiert werden, und setzen danach automatisch fort.",
    ["wn_360_profiles"] = "Behoben — Profil-Import/Export-Fenster verarbeiten Escape im Kampf jetzt sicher, ohne blockierte Tastatureingabe-Aktionen auszulösen.",
    ["wn_360_validation"] = "Getestet — Standardleisten, Mensch/Katze/Bär-Paging, Haltung, Begleiter, Besitz, Spezialbuttons, Maus/Tastatur und Kampf wurden im Spiel ohne neue ActionBar-Taint-Fehler validiert.",
    -- =====================
    -- 3.5.9 — What's New
    -- =====================
    ["wn_359_visibility"] = "Neu — Aktionsleisten besitzen jetzt eine sichere Sichtbarkeits-Engine mit kampfsicheren Regeln für Kampfstatus, Gruppentyp, Instanzen, Reittiere, Ziele, den Modus Versteckt und eigene sichere Bedingungen.",
    ["wn_359_gcd"] = "Geändert — Der GCD-Swipe bleibt sichtbar, wo er hingehört, aber ein reiner GCD zeigt keinen störenden Sekundenbruchteil-Countdown mehr; Zahlen sind dem echten Cooldown der Aktion vorbehalten.",
    ["wn_359_editmode"] = "Fehlerbehebung — Blizzards Bearbeitungsmodus öffnet sich jetzt ohne die geschützten TargetUnit-/FocusUnit-Fehler oder Secret-Value-Fehler der kompakten Gruppenframes, die zuvor TomoMod zugeschrieben wurden.",
    ["wn_359_dormancy"] = "Neu — Sicher ausgeblendete Leisten wechseln jetzt in einen Ruhemodus und stellen unnötige visuelle Arbeit ein. Tastenkürzel bleiben aktiv und die Leiste wird sofort vollständig aktualisiert, sobald sie wieder sichtbar wird.",
    ["wn_359_nativeglow"] = "Neu — TomoMod verwendet jetzt eine eigene native Glow-Engine anstelle von LibCustomGlow. Dadurch entfällt der veraltete AnimateTexCoords-Absturzpfad und Proc-Animationen werden zentral verwaltet.",
    ["wn_359_conditional"] = "Fehlerbehebung — Bedingte Fähigkeiten wie Berührung des Todes des Mönchs aktualisieren Verwendbarkeit und Proc-Status jetzt über Blizzards Aktionsmeldungen. Nicht verwendbare Fähigkeiten bleiben abgedunkelt, statt fälschlich von der roten Reichweitenfarbe überschrieben zu werden.",
    ["wn_359_specialbars"] = "Fehlerbehebung — Blizzards Begleiter-, Haltungs- und Besitzleisten bleiben für Taint-Sicherheit vollständig unter Blizzard-Kontrolle, werden aber mit dem 12.1-Roleset alwaysBlocked gefiltert. Dadurch erscheinen keine doppelten nativen Leisten und die Edit-Mode-Fehler kehren nicht zurück.",
    ["wn_359_paging"] = "Neu — Sicheres Paging für Aktionsleiste 1 bietet Alt-/Shift-/Strg-Seiten, Seiten für freundliche/feindliche Ziele sowie optionales Form- und Skyriding-Paging, alles in TomoMod_Options konfigurierbar.",
    ["wn_359_priority"] = "Geändert — Die Paging-Priorität hält Fahrzeug/Override/Besitz weiterhin an erster Stelle, während manuelle und Modifikator-Seiten bei Bedarf vor automatischen Form- oder Skyriding-Seiten liegen.",
    ["wn_359_formsafe"] = "Fehlerbehebung — Druiden-Formwechsel funktionieren im Kampf jetzt zuverlässig, ohne geschützte Aktions- oder geheime Cooldown-Fehler beim Wechsel zwischen Mensch, Katze und Bär.",
    ["wn_359_zoneability"] = "Fehlerbehebung — Zonenfähigkeiten halten Symbol, GCD und Aufladungen jetzt synchron, wechseln bei Questzuständen korrekt ihr Aussehen und verschwinden, sobald die Fähigkeit nicht mehr verfügbar ist.",
    ["wn_359_extragcd"] = "Fehlerbehebung — Extra-Aktionsknöpfe spiegeln jetzt GCD und Aufladungsregeneration im TomoMod-Skin, ohne Blizzards natives Cooldown-Widget auszulesen oder zu verändern.",
    ["wn_359_specialbuttons"] = "Geändert — Extra-Aktion, Zonenfähigkeit und Fahrzeug verlassen behalten Blizzards sichere Spiellogik, während TomoMod die sichtbaren Steuerelemente übernimmt; Quest-, Fahrzeug- und Taxi-Verhalten bleibt erhalten.",
    ["wn_359_specialskin"] = "Geändert — Extra-Aktion, Zonenfähigkeit und Fahrzeug verlassen verwenden jetzt exakt denselben Aktionsknopf-Stil wie die übrigen TomoMod-Leisten; unsichtbare Blizzard-Klickflächen stehlen keine Klicks oder Tooltips mehr.",
    ["wn_359_validation"] = "Getestet — Formen, Spezialfähigkeiten, Mausklicks, GCD/Aufladungen, Sichtbarkeit, native Glows, Bearbeitungsmodus und sicheres Paging wurden im Spiel ohne neue ActionBar-Taint-Fehler geprüft.",

    -- =====================
    -- 3.5.8 — What's New
    -- =====================
    ["wn_358_input"] = "Fehlerbehebung — Eingaben auf den Aktionsleisten reagieren jetzt zuverlässig sofort: Unterbrechungen, Sofortzauber, Aktionen mit/ohne GCD, schnelles Tastenspammen sowie Shift-/Strg-Bindings haben nicht mehr die zuvor spürbare Verzögerung.",
    ["wn_358_state"] = "Fehlerbehebung — Verschieben, Ersetzen oder Leeren einer Aktion sowie Spezialisierungs-, Talent-, Seiten-, Haltungs-, Fahrzeug- und dynamische Flugwechsel aktualisieren die betroffenen Tasten jetzt ohne veraltete Symbole, Abklingzeiten, Leuchteffekte, Grauzustände oder falsche Aufladungen.",
    ["wn_358_range"] = "Änderung — Unter Midnight 12.1 nutzt die Reichweitenfärbung jetzt Blizzards native Reichweitenmeldungen; Mana und Verwendbarkeit werden ereignisgesteuert aktualisiert. Der alte periodische Scan bleibt nur als Kompatibilitäts-Fallback.",
    ["wn_358_glowflyout"] = "Fehlerbehebung — Proc-Leuchteffekte folgen Basis- und verwandelten Zaubern zuverlässiger, veraltete Leuchteffekte werden entfernt und Flyouts von per Mouseover ausgeblendeten Leisten bleiben sichtbar und kehren nach dem Schließen korrekt zum Fade zurück.",
    ["wn_358_taintstate"] = "Intern — Eigene Zustände, die zuvor direkt auf Blizzard-Frames gespeichert wurden, liegen jetzt in externen Weak-Tables. Dadurch wird weniger Addon-Zustand an geschützte UI-Objekte angehängt.",
    ["wn_358_registry"] = "Fehlerbehebung — TomoMod-Aktionstasten werden bei Bedarf von Blizzards nativen Registern und Broadcastern getrennt, damit der Spiel-Controller ausgemusterte native Tasten nicht über verunreinigte Aktualisierungspfade ausführt.",
    ["wn_358_secretcooldown"] = "Fehlerbehebung — Im Kampf konnte das Fehlerprotokoll mit Meldungen geflutet werden, wenn Blizzard geheime Abklingzeitwerte auf ausgemusterte native Tasten anwenden wollte. Diese Broadcast-Pfade sind jetzt isoliert.",
    ["wn_358_stancepossess"] = "Fehlerbehebung — StanceBar und PossessActionBar bleiben vollständig unter Blizzards Kontrolle. Dadurch verschwindet der geschützte MainActionBar-Fehler, der beim Beschwören eines temporären Mönch-Begleiters im Kampf reproduzierbar war.",
    ["wn_358_blizzbars"] = "Fehlerbehebung — Blizzards Standard-Aktionsleisten werden wieder über den für 12.1 validierten sicheren visuellen Pfad ausgeblendet. Sichtbar bleiben nur TomoMods Leisten, ohne den Controller-Taint zurückzubringen.",
    ["wn_358_validation"] = "Getestet — Der überarbeitete Aktionsleistenpfad wurde in intensiven Kämpfen, nach Reloads, Talent-/Spezialisierungswechseln, Formen, Fahrzeugen, dynamischem Flug, verwandelbaren Zaubern, Aufladungen, Flyouts, Procs und dem Mönch-Begleiter ohne ActionBar-Fehler geprüft.",


    -- =====================
    -- 3.5.7 — Was ist neu
    -- =====================
    ["wn_357_talkingheadfix"] = "Fehlerbehebung — Talking-Head-Fenster ausblenden konnte die Sprachausgabe eines Talking Heads unter einem ausgeblendeten Fenster weiterlaufen lassen. Talking-Head-Fenster verwalten ihre Sichtbarkeit selbst, sodass das bloße Ausblenden beim Anzeigen den Abspielzustand und dessen Abschluss-Timer weiterlaufen ließ — und jede Zeile nach der ersten eines mehrzeiligen Talking Heads übersprang, da das Fenster für diese bereits sichtbar war. TomoMod hakt sich nun in die eigentliche Abspielfunktion ein und schließt jeden Talking Head genauso, wie Blizzard es selbst tut, was Timer und Sprachausgabe zuverlässig gemeinsam stoppt.",
    ["wn_357_talkingheadcleanup"] = "Intern — Ein Stop-Sound-Aufruf, der im selben Moment erfolgt, in dem eine Sprachausgabe startet, wird von der Sound-Engine gelegentlich ignoriert, weshalb das Ausblenden von Talking Heads nun einen Sekundenbruchteil später nachfasst, um sicherzustellen, dass sie wirklich stoppt.",
    ["wn_357_queueeyedb"] = "Fehlerbehebung — Die Position des Warteschlangen-Auges wurde in Wirklichkeit nie gespeichert. Ihr Eintrag fehlte in der Standardeinstellungstabelle, sodass der Speicherhandler jedes Mal beim Ziehen stillschweigend das Schreiben einer neuen Position übersprang — das Auge bewegte sich zwar auf dem Bildschirm, vergaß aber beim nächsten Login, wo Ihr es hingesetzt hattet. Der fehlende Eintrag ist zurück, und der Speicherpfad legt ihn nun im laufenden Betrieb an, falls Eure gespeicherten Einstellungen ihn noch nicht enthalten, sodass ein veraltetes Speicherformat höchstens eine zusätzliche Tabelle kostet.",
    ["wn_357_queueeyeposition"] = "Fehlerbehebung — Die Standardposition des Warteschlangen-Auges war eine blinde Schätzung, die je nach Auflösung an einer anderen Stelle landete — bei einem Ultrawide-Monitor komplett außerhalb des Bildschirms, wodurch dies überhaupt entdeckt wurde. Sie sitzt nun standardmäßig neben der Minikarte, wo das Auge tatsächlich lebt.",
    ["wn_357_lfgeyesurvive"] = "Neu — Das Gruppensuche-Auge verschwand vollständig, wenn Ihr das Blizzard-Mikromenü ausgeblendet habt, da es im selben Container lebt. Es bleibt jetzt erhalten — der Gruppensuche-Warteschlangenstatus ist immer sichtbar, egal wo Ihr es platziert habt, ob das native Mikromenü ausgeblendet ist oder nicht.",
    ["wn_357_lfgeyeoptions"] = "Neu — Zwei neue Mikroleisten-Optionen erlauben es Euch, das Gruppensuche-Auge komplett auszuschalten oder in der Größe anzupassen, direkt neben der Einstellung, die das Blizzard-Mikromenü ausblendet.",
    ["wn_357_lfgeyescale"] = "Fehlerbehebung — Der Größenregler des Gruppensuche-Auges bewirkte nichts, es sei denn, die Mikroleiste war vollständig aktiviert und „Blizzard-Mikromenü ausblenden“ ebenfalls eingeschaltet — andernfalls wurde die Skalierung bei jeder Aktualisierung stillschweigend auf normal zurückgesetzt. Sie greift jetzt in jedem Fall.",
    ["wn_357_roletaintguard"] = "Fehlerbehebung — Ein Nameplate-Fehler konnte trotz vorhandener Absicherung weiterhin auftreten, weil eine Rolle verglichen wurde, die nicht direkt lesbar war. Dieser Vergleich wird jetzt doppelt abgesichert, sodass eine nicht lesbare Rolle als keine Rolle behandelt wird, statt einen Fehler auszulösen.",
    ["wn_357_cooldowntaint"] = "Fehlerbehebung — Manche Aktionsleisten-Schaltflächen konnten beim Aktualisieren ihrer Abklingzeit-Anzeige einen Fehler häufen, wenn das Spiel den Wert nicht direkt lesen ließ, selbst bei Leisten mit deaktiviertem Skin. Diese Aktualisierung wird jetzt bei jeder betroffenen Schaltfläche und jeder ihrer Abklingzeiten sicher übersprungen, statt einen Fehler auszulösen.",
    ["wn_357_mainbartaint"] = "Fehlerbehebung — Ein seltener Fehler konnte auftreten, wenn die Standard-Aktionsleiste nach dem Aufsteigen oder dem Betreten eines Fahrzeugs erneut angezeigt werden sollte. Er wird jetzt genauso abgefangen wie ähnliche Fälle.",
    ["wn_357_mailiconcrash"] = "Fehlerbehebung — Das Briefsymbol der Minikarte konnte bei jeder neuen Post einen Fehler auslösen. Das passiert nicht mehr, und das Symbol verhält sich genau wie zuvor.",
    ["wn_357_buggrabber"] = "Neu — Wenn Ihr auch !BugGrabber verwendet, sichert sich die Diagnose nun zusätzlich dagegen ab und erfasst Fehler, die es vor dem Start von TomoMods eigener Erfassung in dieser Sitzung bereits gesehen hat. Ohne installiertes !BugGrabber ändert sich nichts.",
    ["wn_357_shieldenchant"] = "Fehlerbehebung — Die Warnung zur Waffenverzauberung auf dem Charakterbogen konnte einen Schild oder einen in der linken Hand getragenen Gegenstand (Grimoire, Rüschen usw.) fälschlich als unverzaubert markieren, obwohl keines von beiden überhaupt verzaubert werden kann — Tanks mit Schild und Zauberwirker mit einem Gegenstand in der linken Hand sahen eine rote Warnung für etwas, das nie verzauberbar war. Die Warnung erscheint jetzt nur noch für einen Slot mit einer tatsächlich verzauberbaren Waffe.",
    ["wn_357_inspectiteminfo"] = "Neu — Das Inspizieren eines anderen Spielers zeigt jetzt dieselbe Aufschlüsselung pro Gegenstand wie Euer eigener Charakterbogen: Gegenstandsstufe, Verbesserungsstufe, Verzauberungstext (oder eine Warnung bei fehlender Verzauberung) und Edelsteinsockel neben jedem ausgestatteten Gegenstand, statt nur einer einzigen gemittelten Zahl oben.",
    ["wn_357_inspectiteminfotoggle"] = "Neu — Ein neues Kästchen erlaubt es Euch, die Gegenstandsinfo/Verzauberungen/Edelsteine des Inspektionsfensters unabhängig von den Einstellungen Eures eigenen Charakterbogens auszuschalten.",
    ["wn_357_enemybuffgrid"] = "Neu — Die Anzeige für gegnerische Buffs auf Euren Ziel- und Fokus-Frames (die hilfreichen Auras auf dem, was Ihr anvisiert) hat jetzt eigene Dropdown-Menüs für Richtung (rechts/links) und Nächste Zeile (hoch/runter) sowie einen Regler für Symbole pro Zeile — zuvor war es fest auf 3 pro Zeile nach oben wachsend eingestellt, ohne Änderungsmöglichkeit. Der Höchstwert des Anzahl-Reglers stieg außerdem von 8 auf 12, und jeder Stapel ist auf 3 Zeilen begrenzt — der Rest wird einfach ausgeblendet, statt den Container endlos wachsen zu lassen.",
    ["wn_357_aurasgrid"] = "Neu — Normale Auras (Buffs, Debuffs oder beides, bei Spieler/Ziel/Fokus) nutzen jetzt das gleiche Symbole-pro-Zeile-Raster wie gegnerische Buffs: Ein Regler für Symbole pro Zeile (Standard 6) ersetzt den alten pixelbasierten Zeilenumbruch, mit derselben 3-Zeilen-Begrenzung.",
    ["wn_357_auradirectionfix"] = "Fehlerbehebung — Die Richtungseinstellungen bei Auras und gegnerischen Buffs bewirkten bisher stillschweigend nichts: Die Live-Aktualisierung der Aura-Engine wandte die Wuchsrichtung nur an, wenn sich in derselben Aktualisierung auch Symbolgröße oder Anzahl änderten, und selbst dann sorgte eine fest verankerte Ecke dafür, dass „nach oben“ den Symbolstapel einige Zeilen über der Lebensleiste schweben ließ, statt bündig daran anzuliegen. Beides ist behoben — Richtungs- und Zeilenänderungen wirken jetzt sofort, und der Stapel wächst nun genau von der richtigen Stelle aus, ohne zu schweben.",
    ["wn_357_aurasliverefresh"] = "Fehlerbehebung — Mehrere Auras-/Gegnerische-Buffs-Optionen (Anzahl, Richtung, Typ) benötigten bisher ein `/reload`, um wirklich wirksam zu werden, obwohl sie so aussahen, als müssten sie sofort reagieren. Die meisten tun das jetzt; die zwei, die wirklich noch eines brauchen — Aktivieren und das Buff/Debuff/beides-Dropdown — weisen jetzt direkt im Panel darauf hin.",
    ["wn_357_microbarcombatfade"] = "Fehlerbehebung — Das Überfahren eines Micro-Bar-Symbols im Kampf konnte einen Fehler wegen blockierter Aktion auslösen, statt die Leiste einfach einzublenden. Der Hover-Übergang springt im Kampf jetzt direkt zum Zielwert, statt zu animieren, wodurch der blockierte Aufruf vollständig vermieden wird.",

    -- =====================
    -- 3.5.5 — Was ist neu
    -- =====================
    ["wn_355_barhoverblocked"] = "Fehlerbehebung: Schon das Überfahren einer Aktionsleistenschaltfläche mit der Maus während eines Kampfes erzeugte jedes Mal einen Fehler wegen blockierter Aktion. Blizzards eigene Schaltflächenaktualisierung läuft beim Überfahren und schreibt zum Schluss direkt eine Gedrückthalten-Einstellung — ein Schreibvorgang, der im Kampf nicht erlaubt ist und TomoMod angelastet wird, weil die Schaltflächen von uns stammen. Ein Eintrag pro Überfahren: So kamen in einer einzigen Sitzung 127 davon zusammen. TomoMod schreibt diese Einstellung nun über den eigenen geschützten Pfad, wo sie ohnehin schon korrekt geschrieben wurde, und überspringt Blizzards überflüssige Fassung.",
    ["wn_355_barpingblocked"] = "Fehlerbehebung: Dasselbe Überfahren löste zwei Zeilen weiter einen zweiten unerlaubten Schreibvorgang aus, diesmal aus dem Ping-System. Pings richten sich an Blizzards eigene Leisten und galten nie für TomoMods Schaltflächen, daher wird auch dieser Aufruf jetzt übersprungen. Keiner von beiden hat je etwas auf dem Bildschirm kaputtgemacht — aber sie haben echte Fehler unter Rauschen begraben und das Addon für alles verantwortlich aussehen lassen, was im selben Kampf sonst schieflief.",
    ["wn_355_escapekeyblocked"] = "Fehlerbehebung: War ein TomoMod-Fenster im Kampf geöffnet, erzeugte jeder Tastendruck einen Fehler wegen blockierter Aktion — eine gedrückt gehaltene Bewegungstaste genügte, um das Fehlerprotokoll allein zu füllen. Die Kampfprüfung war bereits vorhanden, sie lief nur eine Zeile zu spät, nach dem geschützten Aufruf, den sie verhindern sollte. Sie läuft jetzt zuerst.",
    ["wn_355_microportrait"] = "Fehlerbehebung: Im eigenen Mikromenü wurde die Schaltfläche für das Charakterfenster als leeres farbiges Quadrat dargestellt, während alle anderen Schaltflächen korrekt aussahen. Sie ist die einzige, deren Grafik kein festes Symbol ist — es ist das Porträt Eures Charakters — und TomoMod kopierte einen Texturverweis, der sich schlicht nirgendwo sonst reproduzieren lässt. Nun wird das Spiel gebeten, Euer Porträt direkt auf die Schaltfläche zu zeichnen, und es übernimmt dieselbe abgerundete Maske und denselben Schlagschatten, die Blizzard auf seiner eigenen Charakterschaltfläche verwendet — Euer Charakter erscheint damit in derselben Form und mit derselben Tiefe wie die benachbarten Schaltflächen statt als flaches Quadrat.",
    ["wn_355_perftooltip"] = "Neu: Der Speicher-Tooltip des eigenen Mikromenüs beginnt jetzt mit einem Leistungsblock: Eure Bildrate, Eure Latenz zu Heimat und Welt sowie die gesamte Addon-CPU. Die CPU-Zeile ist nur dann aussagekräftig, wenn das Spiel sie aufzeichnet, was standardmäßig deaktiviert ist und einen Neuladen erfordert — statt Euch Nullen zu zeigen, die wie eine echte Messung aussähen, steht dort „Profiling deaktiviert“, bis Ihr es einschaltet.",
    ["wn_355_micronative"] = "Fehlerbehebung: Auf manchen Clients bewirkte das Anhaken von „Blizzards Mikromenü ausblenden“ überhaupt nichts: Das Häkchen blieb gesetzt, die Leiste blieb auf dem Bildschirm. TomoMod suchte Blizzards Menü unter einem einzigen Namen, der sich über die Patches hinweg geändert hat, und gab sofort auf, wenn er nicht vorhanden war — ohne auch nur die Schaltflächen auszublenden, was funktioniert hätte. Nun werden alle von Blizzard verwendeten Namen erkannt und die Schaltflächen in jedem Fall behandelt. Antwortet auf Eurem Client gar nichts, wird das jetzt einmal im Chat gemeldet, statt still zu scheitern — bitte meldet es mit Eurer Client-Version, wenn Ihr diese Nachricht seht.",
    ["wn_355_queueanchor"] = "Neu: Das Warteschlangen-Auge — das kleine Symbol, das sich dreht, während Ihr auf einen Dungeon oder ein Schlachtfeld wartet — lässt sich nun verschieben. Blizzard hängt es an die Minikarte und gibt ihm keinen Griff im Bearbeitungsmodus, womit es das einzige Interface-Element war, das Ihr schlicht nicht platzieren konntet. Es erscheint jetzt unter den verschiebbaren Ankern in `/tm sr`, und eine im Kampf vorgenommene Verschiebung wird nach dem Kampfende angewendet, statt abgelehnt zu werden.",
    ["wn_355_escapepropagate"] ="Intern: Die Tastaturweitergabe dieser Fenster wird nun einmalig beim Erstellen des Fensters festgelegt, statt bei jedem Tastendruck neu gesetzt zu werden. Nötig war das nie: Es ist eine dauerhafte Eigenschaft des Rahmens, und das Einzige, was sie je abschaltet, ist das Schließen des Fensters mit Escape — was im Kampf nicht vorkommen kann.",

    -- =====================
    -- 3.5.4 — Was ist neu
    ["wn_354_preyfix"] = "Fehlerbehebung — Die Fortschrittsleiste des Prey Trackers blieb dauerhaft bei 0 % stehen. `GetPreyWidgetInfo` behielt nur den von `pcall` zurückgegebenen Boolean, nicht die eigentlichen Widget-Daten, sodass das Lesen von `.progressPercent` daraus jede Sekunde einen Fehler auslöste und das Update abbrach, bevor es je auf die Ziel-Zählung der Quest zurückfallen konnte. Der Aufruf behält nun beide Rückgabewerte, sodass ein fehlendes Widget-Feld still behandelt wird und der tatsächliche Fortschritt — abgelesen an der Ziel-Zählung der Jagd — korrekt durchkommt.",
    ["wn_354_extranudge"] = "Änderung — Die Verschiebe-Overlays der Extra-Aktionstaste und der Zonenfähigkeit verlieren die vier Klick-Pfeile zum Feinjustieren, die sie in `/tm layout` umgaben. Das Overlay per Maus zu ziehen positioniert es weiterhin exakt wie zuvor — nur die zusätzlichen Knöpfe sind verschwunden.",
    ["wn_354_perflocale"] = "Intern — Das Laden einer nicht-englischen Sprache baute fast 2900 Übersetzungseinträge auf und verwarf sie sofort wieder, fünfmal hintereinander, bei jedem `/reload` — die Datei wurde vollständig kompiliert, bevor das Addon entscheiden konnte, dass sie nicht gebraucht wird. Jede nicht aktive Sprachdatei bricht nun ab, bevor sie ihre Tabelle aufbaut, und die Zusammenführungsprüfung der Basissprache (die durch eine Metatable-Eigenheit stillschweigend wirkungslos war) prüft nun nur noch das, was sie eigentlich prüfen sollte.",
    ["wn_354_perfrangeticker"] = "Änderung — Der Reichweitenprüf-Ticker der Gruppen- und Schlachtzugsfenster, ein Sicherheitsnetz für Fälle, die das eigene Reichweiten-Event des Spiels nicht abdeckt, lief unabhängig von der Gruppengröße zweimal pro Sekunde und Fenster. Er läuft nun alle zwei Sekunden — immer noch schneller als jeder Übergang, den er abfangen muss — und senkt diese Kosten um drei Viertel.",
    ["wn_354_perfaura"] = "Intern — Das Scannen der Verteidigungs-Auras einer Einheit öffnete für jeden geprüften Buff einen neuen geschützten Aufruf, bis zu vierzig Mal pro Aura-Update und verfolgter Einheit. Es gibt nun nur noch einen geschützten Aufruf um den gesamten Scan, mit identischem Rückfallverhalten, falls mittendrin etwas schiefgeht.",
    ["wn_354_perfpartylookup"] = "Intern — Gruppenfenster verzichten nun auf eine lineare Fenstersuche zugunsten einer direkten Nachschlagetabelle und melden sich im Schlachtzug vollständig von Leben-/Ressourcen-/Aura-Events ab — wo diese Fenster ausgeblendet sind und die Schlachtzugsfenster die Updates übernehmen — statt diese Events weiterhin still und ergebnislos zu verarbeiten.",
    ["wn_354_perfcdf"] = "Intern — Das Update-Event von Cooldown Forge konnte bei einem Schwall von Abklingzeit-Änderungen mehrfach im selben Frame auslösen, wobei jedes einzelne für sich alle Leisten und Symbole neu zeichnete. Solche Schwälle werden nun zu einem einzigen Neuzeichnen pro Frame zusammengefasst.",
    ["wn_354_perfmisc"] = "Intern — Ein paar weitere Aufräumarbeiten an heißen Pfaden: Die Boss-Fenster-Abfrage baut nicht mehr bei jedem Tick neue Zeichenketten, der aufgeschobene Layout-Durchlauf des Zieltrackers und dessen rekursiver Inhaltsscan legen nicht mehr bei jedem Knoten Wegwerftabellen an, und die Geschwindigkeitsberechnungen von Skyriding bauen nicht mehr bei jedem Tick eine neue Closure auf.",
    ["wn_354_optionslod"] = "Änderung — Das Optionsfenster — Config, 28 Dateien und rund 17.900 Zeilen — lädt nun bei Bedarf statt beim Einloggen. Es wurde in ein eigenes Addon TomoMod_Options verschoben und lädt erst beim ersten tatsächlichen Öffnen; jeder Knopf und jeder Slash-Befehl, der es zuvor direkt erreichte, lädt es nun beim ersten Gebrauch transparent nach.",
    ["wn_354_optionsfallback"] = "Intern — Die Mythic+-Wertungsfarben, zuvor einmalig beim Einloggen aus einer Theme-Tabelle gelesen, die nun im bedarfsgeladenen Options-Addon liegt (und daher noch nicht existierte), werden nun träge gelesen — sie lösen sich korrekt auf, sobald das Optionsfenster einmal geöffnet wurde, statt für die ganze Sitzung auf einem leeren Rückfallwert eingefroren zu bleiben.",
    ["wn_354_escapefix"] = "Fehlerbehebung — Die Fenster Todes-Rückblick, Lauf-Rückblick, Zauber-Aufschlüsselung und Ziel-Aufschlüsselung des Schadensmessers konnten dazu führen, dass Escape das Spielmenü nach ihrer Nutzung nicht mehr schließen konnte, weil das alte Schließen über eine Funktion lief, deren geschützte Aufrufe nach einer Verunreinigung des Pfades verweigert werden. Alle vier verwenden nun denselben sicheren Escape-Schließmechanismus wie jedes andere TomoMod-Fenster.",

    -- =====================
    -- 3.5.3 — Was ist neu
    ["wn_353_brezvisual"] = "Verbesserung — Der Battle Rez Counter HUD hat eine visuelle Auffrischung erhalten, inspiriert von Tuis Designmustern. Der Frame verfügt nun über einen professionellen mehrschichtigen Hintergrund mit Schatteneeffekten im Inneren, verbesserten Abständen und verfeinerter Typographie für bessere Lesbarkeit im Kampf.",
    ["wn_353_brezglow"] = "Neu — Ein optionaler Gloweffekt wird nun aktiviert, wenn Kampfauferstehungen verfügbar sind, was eine verbesserte visuelle Rückmeldung bietet und den Counter auf einen Blick auffälliger macht.",
    ["wn_353_brezcolors"] = "Änderung — Die Farbpalette des Battle Rez Counters wurde mit Tui-inspirierten Teal-Akzentfarben und besserem Kontrast zwischen aktiven (grün) und Cooldown (rot) Zuständen aktualisiert für eine klarere Statusanzeige.",
    ["wn_353_brezlayers"] = "Intern — Die Frame-Anordnung des Battle Rez Counters wurde mit korrekter Schichtreihenfolge überarbeitet: Hintergrund, innerer Schatten, Symboltextur, Cooldown-Wisch und Textüberlagerungen. Bessere Geometrie und Positionierung aller UI-Elemente.",
    ["wn_353_preytracker"] = "Neu — Prey Tracker: Eine verschiebbare Fortschrittsleiste zur Anzeige des aktiven Prey Hunt-Fortschritts (nur Midnight-Erweiterung). Zeigt den Hunt-Namen, Schwierigkeitsstufe und Echtzeit-Fortschrittsprozentsatz mit sanftem visuellen Design passend zum Battle Rez Counter.",
    ["wn_353_preyconfig"] = "Neu — Der Prey Tracker ist standardmäßig deaktiviert (nur Midnight-Inhalte) und kann unter Konfiguration → QOL → Kampf → Prey Tracker aktiviert werden. Er wird automatisch ausgeblendet, wenn keine Prey Hunt aktiv ist, und zeigt eine Vorschau im Platzierungsmodus.",
    ["wn_353_preylayout"] = "Neu — Der Prey Tracker ist vollständig in TomoMods einheitliches Mover-Layoutsystem integriert. Ziehen Sie ihn zur Positionierung neben anderen HUD-Elementen mit `/tm layout`, mit synchronisiertem Sperr-/Entsperrverhalten und konsistenten Platzierungsmodus-Vorschaubildern.",
    ["wn_353_preyapi"] = "Intern — Der Prey Tracker liest C_QuestLog und C_UIWidgetManager APIs, um aktive Prey Quests zu erkennen und Fortschritte in Echtzeit mit einer Updaterate von 1 Sekunde zu verfolgen, was genaue Statusinformationen während Hunts bietet.",
    ["wn_353_brezcrash"] = "Fehlerbehebung — Der Battle Rez Counter konnte auf manchen Client-Builds komplett fehlschlagen: eine nicht mehr existierende Cooldown-Methode und ein Frame-Level-Aufruf auf einer Textur statt einem Frame ließen beide die Modulinitialisierung abstürzen. Beide sind behoben, ebenso wie ein Glow-Effekt, der abstürzte, sobald er nach einmaligem Ausblenden wieder erscheinen musste.",
    ["wn_353_preyevent"] = "Fehlerbehebung — Der Prey Tracker registrierte ein Event, das auf diesem Client nicht existiert, und löste bei der Initialisierung einen Fehler aus. Behoben, und jede Event-Registrierung ist nun abgesichert, sodass ein fehlendes Event das Modul nicht mehr zum Absturz bringen kann.",
    ["wn_353_preygui"] = "Neu — Der Prey Tracker hat nun einen echten Einstellungsbereich: Konfiguration → QOL → Automatisierungen, mit einer Aktivierungs-Checkbox und Breiten-/Schriftgrößen-Reglern. Zuvor gab es keine Möglichkeit, ihn im Spiel zu aktivieren.",
    ["wn_353_abmover"] = "Fehlerbehebung — Der Eintrag „Action Bars“ in `/tm layout` tat überhaupt nichts. Der portierte Actionbar-Code läuft in einer Sandbox-Umgebung, die sich dem Rest von TomoMod nie offenbarte, wodurch der Platzierungsmodus stillschweigend nicht aktiviert wurde. Er erreicht die Leisten nun korrekt.",
    ["wn_353_abflash"] = "Fehlerbehebung — Das Drücken einer Aktionstaste färbte ihr Symbol komplett weiß, und der erste Behebungsversuch früher in derselben Version funktionierte nicht. Die betroffene Textur ist keine ausgeschnittene Form, die einen anderen Blending-Modus gebraucht hätte, sondern ein massives weißes Quadrat — sie anders zu mischen malte sie weiterhin über das Symbol, und die Änderung ließ drei weitere Texturen, die die ganze Zeit in Ordnung waren, heller erscheinen als vorgesehen. Der Druckeffekt dunkelt das Symbol nun ab, statt es zu überdecken, so wie es von Anfang an gedacht war.",
    ["wn_353_abpressopt"] = "Neu — Sie entscheiden, was eine Taste tut, während Sie sie gedrückt halten. Config → Aktionsleisten → Allgemein bietet die Einstellung „Druckeffekt“ mit drei Möglichkeiten: Blizzards eigener Blitz, jetzt die Voreinstellung, TomoMods Abdunkeln, oder gar nichts. Die Auswahl wirkt sofort, ohne Neuladen.",
    ["wn_353_abposition"] = "Fehlerbehebung — Eine verschobene Aktionsleiste setzte sich bei jedem `/reload` auf ihre Standardposition zurück. Die gespeicherte Position wurde nie tatsächlich geschrieben, und der Wiederherstellungspfad las sie selbst dann nie zurück, wenn sie es war. Beides ist behoben — Leistenpositionen bleiben nun korrekt erhalten.",
    ["wn_353_abcolor"] = "Änderung — Das Move-Mode-Overlay für Aktionsleisten und die zusätzlichen Aktions-/Zonenfähigkeitsknöpfe verwendet nun TomoMods Teal-Markenfarbe statt Tuis ursprünglichem Blau, passend zu jedem anderen `/tm layout`-Overlay.",
    ["wn_353_abextramover"] = "Fehlerbehebung — Die Halterungen für die Extra-Aktionstaste und die Zonenfähigkeit hatten ihr eigenes separates Move-Overlay, das nie mit `/tm layout` verbunden war — immer auf dem Bildschirm sichtbar, aber unmöglich über das einheitliche Layout-Tool zu verschieben. Beide haben nun einen eigenen „Extra-Button“-Eintrag in `/tm layout`.",
    ["wn_353_brezicon"] = "Fehlerbehebung — Das Symbol des Battle Rez Counters wurde als durchgehend schwarzes Quadrat dargestellt: Der dafür verwendete Texturpfad existiert auf diesem Client nicht. Es zeigt nun korrekt das Wiedergeburt-Symbol.",
    ["wn_353_nameplaterole"] = "Fehlerbehebung — Nameplates konnten beim Lesen der Gruppenrolle einer Einheit in eingeschränkten Inhalten Taint-Fehler häufen, da die Rolle als geheimer Wert zurückkommen kann, der nicht direkt verglichen werden kann. Dies ist nun abgesichert und wird als unbekannt behandelt, statt einen Fehler auszulösen.",
    ["wn_353_abmicrodefer"] = "Fehlerbehebung — Die Tasten des Mikromenüs konnten für den Rest der Sitzung verschwinden. Wenn sie zurück an ihren Platz gebracht werden müssen und gerade ein Kampf läuft, wartet das Verschieben auf das Kampfende — aber der Teil, der es danach wecken sollte, war nie vorhanden, also wartete es unbegrenzt, still und ohne einen Eintrag im Fehlerprotokoll. Es läuft jetzt, sobald Sie den Kampf verlassen.",
    ["wn_353_abpaging"] = "Fehlerbehebung — Wenn sich die Leiste unter Ihnen änderte — ein Fahrzeug, eine Kontrollleiste, eine Haltung, eine Himmelsritt-Seite — behielten die Tasten das Aussehen der gerade verlassenen Seite oder zeigten überhaupt nichts mehr an, und nur ein vollständiger Neuaufbau oder ein /reload half. Das Neuzeichnen, das einem Seitenwechsel folgen sollte, hing an einer Blizzard-Funktion, die es auf dem aktuellen Client nicht mehr gibt, und lief deshalb kein einziges Mal. Die Leisten zeichnen sich jetzt selbst neu, wenn sie die Seite wechseln.",
    ["wn_353_aboverride"] = "Fehlerbehebung — Auf die Ersatzleiste wurde überhaupt nie gehört. Das ist die Leiste, auf die ein Fahrzeug, ein Himmelsritt-Reittier oder die Flugform eines Druiden Sie setzt, und da den Leisten niemand mitteilte, dass dies geschehen war, zeigten sie weiterhin die Aktionen der vorherigen Seite. Sie wird jetzt wie jeder andere Seitenwechsel überwacht: die Plätze werden neu gelesen und die Tasten neu gezeichnet.",
    ["wn_353_totembar"] = "Neu — Eine Totemleiste. Sie zeigt die Totems, die ihr gestellt habt, in der Prioritätsreihenfolge eurer eigenen Klasse, wobei jedes Symbol die verbleibende Zeit trägt und ein Ablauf darüber hinwegzieht. Ein Rechtsklick entfernt das Totem, und die Leiste verschwindet von selbst, sobald nichts mehr steht. Blizzards eigener Totemrahmen tritt zurück, solange sie aktiv ist, und wird unversehrt zurückgegeben, sobald ihr sie abschaltet.",
    ["wn_353_totemconfig"] = "Neu — Die Totemleiste wird unter Konfiguration → Aktionsleisten → Allgemein im Abschnitt Totems eingeschaltet und wirkt sofort, ohne Neuladen. Standardmäßig ist sie aus. Symbolgröße, Abstand, Rahmen, Zoom, Wuchsrichtung sowie das Aussehen des Dauertexts und des Ablaufs lassen sich alle einstellen.",
    ["wn_353_totemlayout"] = "Neu — Positioniert sie über `/tm layout` wie jedes andere HUD-Element. Sie bleibt dort sichtbar und beschriftet, auch wenn kein einziges Totem steht — ihr könnt sie also platzieren, bevor ihr überhaupt eines wirkt, statt erst ein Totem stellen, zum Layout-Werkzeug hetzen und hoffen zu müssen, dass es noch steht.",
    ["wn_353_petstancelayout"] = "Neu — Die Begleiter- und die Haltungsleiste lassen sich endlich anordnen. Ausrichtung, Tastenanzahl und Spalten waren ihnen in der Annahme vorenthalten worden, das Spiel bestimme ihre Form — das tut es nicht: Sie laufen durch genau denselben Layout-Code wie die acht Hauptleisten, und zwar seit jeher, sodass die Einstellungen die ganze Zeit wirksam waren, ohne dass es auf dem Bildschirm einen Weg zu ihnen gab. Alle drei Regler sind nun für beide vorhanden, gedeckelt bei zehn statt zwölf Plätzen. Die Haltungsleiste höher zu setzen als eure Klasse Formen hat, ist folgenlos — der Wert wird für euch begrenzt.",
    ["wn_353_loots17"] = "Neu — Die Beutetabellen sind auf dem Stand von Saison 17. Die Dungeon-Rotation hat vollständig gewechselt, also sind alle acht neuen Dungeons dabei — Die Königsruh, Der Tempel von Sethraliss, Rubinlebensbecken, Das blendende Tal, Arena der Leerennarbe, Nalorakks Bau, Mördergasse und Altar der Fänge — dazu die beiden neuen Schlachtzüge, Die Gezeitengebundene Grotte und Der Giftige Abgrund, samt den Klassenbeschränkungen jedes Gegenstands, den sie fallen lassen. Die Tabellen der letzten Saison werden ausgemustert statt danebengelegt: nichts in einer der beiden Rotationen verweist noch auf sie.",
    ["wn_353_mplusteleports"] = "Neu — Der Mythisch+-Tracker kennt die Teleporter der neuen Rotation. Die fünf Rotationsdungeons kommen mit ihren Teleportzaubern, und Die Königsruh sowie Der Tempel von Sethraliss haben endlich ihre eigenen — beide standen leer da, obwohl sie Teil der Rotation sind, sodass der Tracker für keinen von beiden etwas anzubieten hatte.",
    ["wn_353_keysync"] = "Fehlerbehebung — `/tmt keysync` tut endlich etwas. Die Schlüssel-Synchronisationsdiagnose war geschrieben, und die Notiz direkt darüber nannte sogar den Befehl, dem sie antworten sollte, doch nichts im Handler führte dorthin — womit das einzige Werkzeug, um eine still scheiternde Synchronisation von einer zu unterscheiden, die schlicht nichts Passendes fand, aus dem Spiel heraus unerreichbar war. Er steht nun in allen sechs Sprachen in `/tmt help`.",
    ["wn_353_totemport"] = "Intern — Die Totemleiste ist eine Portierung und keine Neuschreibung: aus Tui übernommen, wie sie geschrieben war, mit jeder geänderten Zeile markiert, sodass ein späteres Nachziehen zum Original das Abspielen einer Handvoll Markierungen bedeutet statt einer zweiten Lesung der ganzen Datei. Ihre Abklingzeiten weisen geheime Werte rundheraus zurück, statt sie zu erraten — so behandelt der übrige portierte Code eingeschränkte Inhalte bereits —, und jeder gesicherte Schreibvorgang wartet das Kampfende ab, statt mitten im Gefecht versucht zu werden.",
    ["wn_353_abemptyslot"] = "Fehlerbehebung — Und mit aktiviertem „Leere Plätze ausblenden“ blieb die Leiste nach denselben Wechseln leer statt veraltet: die Tasten waren da, aber unsichtbar, und das Abwählen der Option ließ das Problem verschwinden — was schließlich die Ursache verriet. Das Neuzeichnen lief einen Frame zu früh, während die Tasten noch auf die Plätze der verlassenen Seite zeigten, sodass jede von ihnen als leer eingestuft und ausgeblendet wurde — und danach sah nichts mehr nach. Es läuft jetzt ein zweites Mal im nächsten Frame, sobald die Tasten aufgeholt haben.",

    -- 3.5.2 — Was ist neu
    -- =====================
    ["wn_352_icons"] = "Behoben — Die Symbole der Aktionsleisten kamen schwarz zurück. Die Prüfung, die einen leeren Platz erkennen sollte, erwartete das Symbol als Dateipfad — so hat das Spiel früher geantwortet und tut es seit Jahren nicht mehr, es gibt jetzt eine Nummer zurück. Jedes echte Symbol fiel damit durch einen Test, der eigentlich die fehlenden abfangen sollte, wurde gelöscht und hinterließ ein leeres Quadrat an der Stelle deines Zaubers. Sowohl der normale Weg als auch die Ausweichlösung akzeptieren nun beide Antworten.",
    ["wn_352_tint"] = "Behoben — Außer Reichweite, kein Mana und nicht benutzbar wurden nach einem Neuladen oder einem Leistenwechsel nicht mehr angezeigt, und ein Überfahren mit der Maus holte sie zurück. TomoMod färbte das Symbol genau dort ein, wo auch Blizzard es einfärbt, sodass der von beiden, der zuletzt lief, darüber entschied, was du zu sehen bekamst. Die Färbung ist jetzt eine eigene Schicht von TomoMod über dem Symbol, die es genauso abdunkelt wie zuvor, ohne dass sich die beiden gegenseitig überschreiben — und wenn es nichts zu melden gibt, ist sie schlicht nicht da.",
    ["wn_352_scope"] = "Behoben — Bei abgeschalteten Aktionsleisten hat die Optik trotzdem weiter Schaltflächen umgestaltet. Sie sucht ersatzweise nach Schaltflächen über deren Namen, und diese Namen gehören Blizzards Schaltflächen, ganz gleich ob TomoMod sie übernommen hat oder nicht — die Leisten abzuschalten ließ die Optik also Rahmen neu bemalen, die sie nichts angingen. Sie prüft jetzt, ob die Leisten tatsächlich laufen, bevor sie irgendetwas verändert.",
    ["wn_352_move"] = "Intern — Die Aktionsleisten sind umgezogen. Sie lagen bei den Komfortverbesserungen, weil die Optik dort ihren Anfang nahm, und sie sind in dem Moment keine Verbesserung mehr gewesen, als die letzte Version ein eigenständiges System aus ihnen gemacht hat, mit einem Kern, fünf Schichten und eigenen Schaltflächen. Sie stehen jetzt bei den Einheiten-, Gruppen- und Schlachtzugsfenstern, wo sie hingehören, und werden geladen wie diese. Auf dem Weg dorthin hat sich nichts an ihnen geändert — die drei Korrekturen oben sind mitgekommen.",
    ["wn_352_tui"] = "Intern — Vorarbeit, und noch nichts, was du sehen kannst. Ein Teil dessen, was für die Leisten geplant ist, existiert bereits in einem anderen Addon, und es Zeile für Zeile passend umzuschreiben wäre langsam und würde Fehler hineintragen, die im Original nicht stecken. Es gibt daher jetzt eine dünne Schicht, deren einzige Aufgabe es ist, eine dieser Dateien hier unverändert laufen zu lassen. Wo TomoMod schon eine eigene Fassung von etwas hat — Verankerung, Verschiebemodus — verweist die Schicht darauf, statt eine zweite Kopie mitzuschleppen; deshalb stehen vier Funktionen für sechzehnhundert Zeilen davon. Noch ruft nichts davon irgendetwas auf; es wird bewusst für sich allein eingesetzt, bevor sich etwas darauf stützt.",
    ["wn_352_port"] = "Intern — Und dann das, wofür diese Schicht gebaut wurde. Das Aktionsleisten-Modul aus dem anderen Addon liegt jetzt vollständig hier: vierzehn Dateien, gut achttausend Zeilen, herübergenommen so, wie sie geschrieben wurden, statt passend abgetippt. Jede Stelle, an der eine Zeile geändert werden musste, ist markiert; wenn das Original also weiterzieht, heißt Nachziehen, eine Handvoll Markierungen erneut abzuspielen, statt alles noch einmal zu lesen und zu hoffen, dass einem auffällt, was sich verschoben hat. Es ist geladen, es ist geprüft, und es ist mit Absicht ausgeschaltet: etwas von dieser Größe abzulegen und in derselben Version einzuschalten, führt geradewegs dahin, nicht mehr sagen zu können, welches von beiden deine Leisten zerlegt hat.",
    ["wn_352_portlayers"] = "Intern — Was darin steckt, für den Tag, an dem der Schalter umgelegt wird. Zuerst die Aufklappmenüs: die letzte Version lieferte TomoMods eigene Schaltflächen aus und musste klar sagen, dass ein Magierportal oder eine Jägerfalle auf einer Leiste mit ihnen nicht aufgeht, weil das Spiel den gewöhnlichen Weg auf einer von einem Addon gebauten Schaltfläche verweigert und der Umweg ein paar hundert Zeilen sind, die niemand zweimal schreibt. Diese Zeilen kamen mit der Portierung, samt passender Umgestaltung des spieleigenen Aufklappmenüs für die Schaltflächen, die weiterhin Blizzard gehören. Die zusätzliche Aktionsschaltfläche und die Gebietsfähigkeit bekommen einen eigenen Platz, aus dem das Spiel sie nicht stillschweigend wegschieben kann. Abklingzeiten, das Leuchten und das Ausgrauen dessen, was du nicht wirken kannst, kommen jeweils als eigene Schicht. Nichts davon ist bereits an.",
    ["wn_352_switch"] = "Änderung — Der Schalter ist umgelegt: Die Aktionsleisten laufen jetzt auf dem portierten Modul, und das System, das sie zuvor angetrieben hat, wurde entfernt statt bloß abgeschaltet stehen gelassen — zwei Systeme, die beide überzeugt sind, dieselben Schaltflächen zu besitzen, sind kein Zustand, den man ausliefert, um zu sehen, was passiert. Die letzten drei Teile kamen mit: die Optik, die einer Schaltfläche das spieleigene Bildwerk abnimmt und sie von Grund auf neu zeichnet, bis hin zum Makronamen und der Stapelzahl; das Ausblenden einer Leiste, bis du mit der Maus darübergehst, leistenweise, wobei die Leiste sichtbar bleibt, solange dein Zauberbuch offen ist; und die Überlagerungen, die du siehst, wenn du eine Leiste verschieben willst. Masque wird jetzt ebenfalls unterstützt, wenn du es verwendest, und ist schlicht abwesend, wenn nicht.",
    ["wn_352_bindings"] = "Änderung — Deine Tasten bleiben, und es gibt 106 Dinge weniger zu belegen. Die vorige Version lieferte eine Belegung für jede Schaltfläche jeder Leiste aus, sodass TomoMods eigene Schaltflächen auf einer Leiste bedeuteten, sie im Tastenbelegungsfenster des Spiels ein zweites Mal zu belegen, unter einer TomoMod-Überschrift, neben der Belegung, die du bereits hattest. Die neuen Schaltflächen verlangen das nicht: Sie lesen, was du den spieleigenen Aktionsleisten-Befehlen zugewiesen hast, und übernehmen es für sich. Eine Leiste, die du eingerichtet hattest, funktioniert weiter, ohne dass du etwas tust, und eine Taste, die bereits anderweitig vergeben ist, bleibt genau dort, wo sie ist.",
    ["wn_352_settings"] = "Änderung — Die Optionsseite der Aktionsleisten ist zurück, und eines solltest du vor dem Update wissen. Als die Leisten früher in derselben Version umgestellt wurden, schrumpfte die Seite auf eine einzige Meldung, weil jedes ihrer Bedienelemente in ein System schrieb, das es nicht mehr gab. Sie ist jetzt auf das aufgebaut, was die Leisten tatsächlich lesen: fünf Reiter — die Tasten selbst, die Beschriftungen darauf, die Anzeigen für außer Reichweite, zu wenig Ressource und nicht wirkbar, das Ausblenden einer Leiste, bis du mit der Maus darauf zeigst, und ein Reiter pro Leiste für die Anzahl der Tasten und die Richtung, in die sie wächst. Das Wichtige: Deine alten Leisteneinstellungen werden nicht übernommen. Die alte Art, sie zu speichern, und die neue benennen nichts gleich, und die wenigen Namen, die sich ähneln, bedeuten nicht dasselbe — sie zu übertragen hieße also raten, und ein falscher Tipp hinterlässt dir eine Anordnung, die du nie gewählt hast und zu der du nichts zurückverfolgen kannst. Die alten Einstellungen werden einmalig gelöscht, bei deiner ersten Anmeldung nach dem Update, und die Leisten starten mit sauberen Standardwerten, die du dann nach Belieben einstellst.",
    ["wn_352_chatcopy"] = "Neu — Das Kopieren von Text aus dem Chat wurde neu gebaut. Das Fenster sieht jetzt aus wie der übrige Chat und nicht mehr wie ein schlichter grauer Kasten: Der Text ist beim Öffnen bereits markiert und bis zur letzten Zeile gescrollt, du kannst die Größe ändern, und es fasst 500 Zeilen statt bisher 128. Außerdem gibt es eine Kopierschaltfläche am Chatfenster selbst — immer sichtbar, nur wenn du auf den Chat zeigst, oder gar nicht, ganz wie du magst, unter Skins, Chatfenster. Und das kleine Fenster, das dir die Adresse eines Links zum Kopieren anbietet, passt nun zum Rest, statt der Dialog des Spiels zu sein.",

    -- =====================
    -- 3.5.1 — Was ist neu
    -- =====================
    ["wn_351_engine"] = "Intern — Die Aktionsleisten wurden fünfmal pro Sekunde komplett neu gezeichnet, jede Schaltfläche, ganz gleich ob sich etwas geändert hatte oder nicht. Das ist die Form, die eine Optik annimmt, wenn sie zu einem Funktionsumfang heranwächst, ohne je einen Ort bekommen zu haben, an dem sie sich etwas merken kann. Es gibt jetzt ein einziges Stück, dem die Frage gehört — in welchem Zustand ist diese Schaltfläche — und das Spiel sagt ihm Bescheid, wenn etwas passiert, statt dass es auf einem Zeitgeber nachsieht; weitergegeben wird nur, was sich tatsächlich geändert hat. Die Reichweite ist die Ausnahme, denn dafür hat das Spiel keine Meldung: Diese Prüfung läuft weiter auf einem Zeitgeber, und nur solange du ein Ziel hast. Außerdem nimmt es nie an, dass die Schaltfläche darunter Blizzard gehört — genau das hat alles Übrige in dieser Version erst möglich gemacht.",
    ["wn_351_render"] = "Neu — Symbole und Abklingzeiten lassen sich jetzt einstellen. Die Zahlen der Abklingzeit und ihre Größe, Farbe und Deckkraft des Wischers, Kante und Aufblitzen, der Text für Aufladungen und Stapel samt Größe, der Makroname, das Ausgrauen einer nicht verwendbaren Aktion und der Beschnitt des Symbols — bis hin zu gar keinem Beschnitt. Dazu kommt die Wahl, wer die Abklingzeit zeichnet: Blizzard, das seinen eigenen Wischer behält und ihn lediglich umgestaltet, oder TomoMod, das ihn selbst zeichnet. Blizzard bleibt die Voreinstellung und vorerst die sicherere der beiden; die von TomoMod ist das, was die neuen Schaltflächen weiter unten brauchen, und sie ist da, damit sie sich bewähren kann, bevor irgendetwas auf sie angewiesen ist.",
    ["wn_351_glow"] = "Neu — Zwei Leuchteffekte auf den Leisten, und beide können gleichzeitig an sein. Der eine ist die klassische Hervorhebung eines Procs, der andere folgt dem Rotationsvorschlag, den das Spiel selbst macht. Jeder hat seinen eigenen Stil — Pixel, Autocast, Schaltfläche, Proc oder Blizzard — seine eigene Farbe, und beim Pixel-Stil die Anzahl der Linien, ihre Stärke und die Animationsgeschwindigkeit. Sie bestehen nebeneinander, statt sich abzuwechseln, weil jeder seinen eigenen Griff auf die Schaltfläche behält. Zugeordnet wird über den Zauber, also leuchtet ein Makro, das am Ende etwas wirkt, genau so wie der Zauber allein, und einem Talent, das einen Zauber umbenennt, wird ebenfalls gefolgt. Der Rotationsleuchteffekt ist standardmäßig aus und setzt voraus, dass es die Funktion auf deinem Charakter gibt.",
    ["wn_351_hotkeys"] = "Neu — Der Tastenbelegungstext auf den Schaltflächen gehört jetzt dir: anzeigen oder nicht, Größe, Farbe, in welcher Ecke er sitzt, wie weit er verschoben ist, ob er abgekürzt wird und ob er auf einem leeren Platz überhaupt erscheint. Er wird aus der Belegung selbst ermittelt statt von Blizzards Beschriftung abgeschrieben, und das ist wichtig, weil eine von TomoMod gebaute Schaltfläche gar keine solche Beschriftung hat — Blizzards wird als Rückfallebene behalten, damit eine unerwartete Änderung in einem künftigen Patch etwas schlechteren Text bedeutet und nicht gar keinen. Dazu ein Belegungsmodus: einschalten, eine Schaltfläche überfahren, eine Taste drücken. Rechtsklick oder Escape löscht eine. Im Kampf öffnet er sich nicht.",
    ["wn_351_special"] = "Neu — Dinge, die die Leisten wussten und dir nie gezeigt haben. Auf einer gestalteten Leiste konntest du nicht sehen, in welcher Haltung du warst, welche Waffenverzauberung angelegt war oder welche Begleiterfähigkeit sich selbst wirken sollte: Die Optik entfernt Blizzards Markierungen und wäscht dessen Hervorhebung aus. Es gibt nun einen Ring für die aktive Aktion und für angelegte Gegenstände, jeder mit eigener Farbe und gemeinsamer Stärke, auf einem Ring mit einer Rangfolge, damit sich zwei Zustände nie zu einem Durcheinander stapeln. Das Autocast des Begleiters bekommt sein eigenes Funkeln, das neben den beiden Leuchteffekten oben besteht. Die Begleiterleiste kann sich ausblenden, wenn du keinen Begleiter hast. Für Haltungen gibt es kein Gegenstück — man kann das Spiel gar nicht fragen, ob eine Klasse überhaupt Formen hat, und Blizzards eigene Haltungsschaltflächen verschwinden bereits von selbst, wenn es nichts zu zeigen gibt.",
    ["wn_351_ownbuttons"] = "Neu — TomoMod kann jetzt eigene Aktionsschaltflächen bauen, statt sich Blizzards zu leihen. Es ist überall aus, wird leistenweise eingeschaltet und lässt sich rückgängig machen, indem du das Häkchen entfernst und neu lädst. Alles Vorstehende funktioniert unverändert darauf. Lies bitte die Grenzen, bevor du es einschaltest, denn sie sind echt: Aufklappmenüs öffnen sich auf einer umgestellten Leiste nicht — Magierportale, Jägerfallen, beschworene Fläschchen. Fahrzeug- und Überschreibungsleisten folgen dem Seitenwechsel weiterhin, aber die besondere Ausstiegsschaltfläche und ihre Grafik kommen nicht mit. Die Rotationshervorhebung des Spiels wird darauf nicht gezeichnet; nimm stattdessen den Rotationsleuchteffekt von oben. Begleiter- und Haltungsleisten bleiben vollständig auf Blizzards Schaltflächen. Es ist als experimentell gekennzeichnet, weil es das ist.",
    ["wn_351_bindings"] = "Neu — Die neuen Schaltflächen bringen 106 bereits deklarierte Belegungen mit, sie tauchen also im Tastenbelegungsfenster des Spiels auf, unter einer TomoMod-Überschrift mit einem Abschnitt pro Leiste. Sie werden über einen eigenen Klick gebunden statt über einen einfachen Linksklick, und genau das lässt das Wirken beim Tastendruck richtig funktionieren — eine bekannte Fallgrube, und Bartender4 ist vor Jahren aus demselben Grund denselben Schritt gegangen.",
    ["wn_351_keybound"] = "Neu — TomoMods Leisten schließen sich dem gemeinsamen Belegungsmodus an, den Dominos, Bartender4 und Bagnon verwenden: Ein Durchgang belegt deine Leisten und ihre zusammen, statt dass jedes Addon auf seinem eigenen besteht. Die Bibliothek, die das regelt, liegt jetzt bei, der gemeinsame Modus ist also da, ob du eines dieser Addons benutzt oder nicht. Eine Einzelheit, die für die nächste Aktualisierung festgehalten gehört: Sie muss aus einer verpackten Veröffentlichung stammen, niemals aus ihrem GitHub-Spiegel, der seine eigene Version aus einer Markierung berechnet, die nur innerhalb einer Quell-Arbeitskopie überhaupt gefüllt wird — anderswohin kopiert scheitert er sofort beim Laden.",
    ["wn_351_tabs"] = "Änderung — Die Optionsseite der Aktionsleisten hat jetzt fünf Reiter statt zwei: Optik, Schaltflächen, Leuchten, Tastenbelegung und Leisten. Jede Neuerung landete bisher in einer einzigen langen Spalte auf dem Optik-Reiter, und drei der fünf Schichten dieser Version wären ebenfalls dort gelandet.",

    -- =====================
    -- 3.4.6 — Was ist neu
    -- =====================

    ["wn_346_probe_secret"] = "Behoben — Die Buff-Symbole im Cooldown-Studio, denen 3.4.5 gerade erst beigebracht hatte, ihren Countdown im Kampf zu behalten, erzeugten beim ersten Symbol, das einen Buff überwachte, einen Fehler. Der unsichtbare Marker an jedem Symbol wurde gefragt, ob er auf dem Bildschirm ist — in der Annahme, das sei eine Frage über ein Stück Benutzeroberfläche und nicht über den Buff. Ist es aber nicht. Ob ein Aura-Symbol angezeigt wird, ist genau die Information, ob der Buff aktiv ist, und genau die hält das Spiel zurück: Das zurückgegebene Ja-oder-Nein war selbst zurückgehalten, und der Fehler entstand dadurch, dass es abgefragt wurde. Den Aufruf abzusichern konnte nie helfen: Der Aufruf lief einwandfrei, und der Fehler kam eine Zeile später, beim Ansehen der Antwort.",
    ["wn_346_probe_cooldown"] = "Änderung — Also wird die Frage an etwas anderes gestellt. Jedes Symbol hat bereits seinen eigenen Wischer, den das Spiel direkt antreibt, und dieses Stück gehört TomoMod und nicht dem Spiel: Der Wischer erscheint, solange der Buff aktiv ist, und verschwindet, wenn er endet — und nichts hindert das Addon daran, das zu lesen. Er gibt dieselbe Antwort, von der Seite der Grenze aus, auf der Lesen noch erlaubt ist. Der Marker des Spiels bleibt als Zweitmeinung dahinter erhalten, nun sicher abgefragt, und wenn keiner von beiden antwortet, steuert das Symbol für dieses Bild schlicht nichts bei und treibt den Wischer weiter an — was ohnehin immer der größere Teil seiner Aufgabe war.",

    -- =====================
    -- 3.4.5 — Was ist neu
    -- =====================

    ["wn_345_class_secret"] = "Behoben — Lebensleisten erzeugten bei jeder Aktualisierung einen Fehler für jeden Spieler, dessen Klasse das Spiel nun verbirgt: 399 Mal in einer einzigen Sitzung in dem Bericht, der dazu geführt hat. Patch 12.1 hat erweitert, was ein Addon nicht lesen darf, und ein verborgener Wert fehlt nicht einfach: Er ist da und schlägt fehl, sobald irgendetwas mit ihm geschieht — ihn vergleichen, etwas damit nachschlagen, ihn an einen Text hängen oder auch nur fragen, ob er wahr ist. Die Prüfung muss also vorher kommen; hinterher lässt sich nichts mehr auffangen. Sechzehn Stellen in TomoMod lasen jeweils die Klasse einer Einheit und schlugen die Farbe auf dieselbe Weise nach; sie laufen jetzt alle über einen gemeinsamen Satz von Helfern, der erst fragt, ob ein Wert lesbar ist, bevor er ihn anfasst. Jede Stelle entscheidet selbst, was eine unbekannte Klasse bedeutet, denn die richtige Antwort ist nicht überall dieselbe: Die Klassenerinnerung nimmt an, dass jemand den Segen brauchen könnte, statt ihn zu überspringen, die Zauberer-Tönung auf feindlichen Namensplaketten bleibt aus statt geraten zu werden, und die Schlüsselliste wie auch TomoScore zeichnen einfach ohne Farbe. Die Krone des Gruppenanführers gehört zur selben Familie — auch wer die Gruppe anführt, kann jetzt verborgen sein, und dann bleibt die Krone unsichtbar, denn sie über einem Spieler zu zeigen, der vielleicht gar nicht der Anführer ist, wäre schlimmer als gar keine.",
    ["wn_345_class_passthrough"] = "Neu — Und dann kamen die Klassenfarben zurück. Auf eine Fraktionsfarbe auszuweichen, wenn die Klasse nicht lesbar ist, ist richtig, betrifft in einem Dungeon aber wirklich jeden in der Gruppe: Die Fenster hätten also dauerhaft die falsche Farbe gehabt und nicht nur gelegentlich. Es zeigt sich, dass das Spiel eine Einheit weiterhin für einen einfärbt, auch wenn es die Klasse nicht verraten will: Die Klasse geht in eine der spieleigenen Funktionen hinein und die Farbe kommt direkt aus einer anderen wieder heraus, in die Leiste, ohne dass das Addon jemals eines von beiden liest. Die Lebensleisten von Einheitenfenstern, Namensplaketten, Gruppen- und Schlachtzugsfenstern nehmen zuerst diesen Weg und behalten ihre Klassenfarben. Das funktioniert allerdings nur dort, wo die Farbe unverändert aufgetragen wird — alles, was sie abdunkeln oder mischen muss, braucht die Zahlen, und dort bleibt die Fraktionsfarbe die Antwort.",
    ["wn_345_nameplate_auras"] = "Behoben — Feindliche Namensplaketten verschwanden beim Drehen der Kamera. Nicht ihre Auren: die ganze Plakette. Das Auslesen der Auren einer Einheit gehört zu dem, was Patch 12.1 nun verweigern kann, und die Verweigerung kam mitten aus dem Zeichnen der Plakette: Alles danach — Lebensleiste, Name, Zauberleiste — fand schlicht nicht mehr statt, und die Plakette wirkte gelöscht. Das Drehen der Kamera löste es aus, weil dabei neue Plaketten ins Bild kommen. Jede Aura-Abfrage auf einer Plakette ist jetzt einzeln abgesichert: Eine Verweigerung kostet nur diese eine Aura ihr Symbol oder ihren Countdown, sonst nichts. Zwei der dafür geschriebenen Absicherungen schützten in Wahrheit gar nichts, aus einem Grund, den man als Lua-Schreiber kennen sollte: Eine Absicherung um einen Aufruf herum deckt keinen zweiten Aufruf ab, den man ihr als Argument übergibt, denn das Argument läuft zuerst. Eine der beiden umgab genau den Aufruf, der fehlschlug.",
    ["wn_345_aura_probe"] = "Intern — Elf verschiedene Stellen in TomoMod lesen die Auren einer Einheit: die Auren auf den Fenstern und den Namensplaketten, den Reinigungsrahmen, die Reihe der Heilungszauber, das Gruppensegen-Symbol, die Verteidigungssymbole, die Segensverfolgung von CooldownForge. Jede lief bis zu vierzig Auren-Plätze einzeln durch und sicherte jeden Schritt ab, nur um am Ende festzustellen, dass das Spiel überhaupt nichts beantworten würde. Sie fragen jetzt einmal, und die Antwort gilt für den Rest des Frames: Vierzig Gruppenfenster kosten eine Frage statt sechzehnhundert abgesicherter Schritte. Die Frage wird bewusst über den zulässigsten Weg gestellt, eine Aura zu lesen — ein Nein bedeutet also, dass jeder andere Weg schon verschlossen war und nichts Übersprungen wird, was sich hätte zeichnen lassen. Ein echter Fehler kam dabei heraus: CooldownForge leerte seine eigene Liste verfolgter Segen, sobald ein erneuter Durchlauf verweigert wurde, und verfolgte danach gar nichts mehr, bis das Spiel wieder lesen ließ. Die Grenze offen gesagt: Das macht es günstiger, nicht vollständiger. Ein Symbol, dessen Abfrage nichts lesen kann, geht weiterhin aus, genau wie vorher.",
    ["wn_345_aura_engine"] = "Neu — Auren fehlten während des größten Teils eines Kampfes, und nichts wies darauf hin: kein Fehler, nichts auf der Plakette oder dem Fenster, nur eine Lücke dort, wo das Gesuchte hätte stehen sollen. Alles andere in dieser Version macht eine verweigerte Aura-Abfrage harmlos; nichts davon bringt die Aura zurück, denn das Spiel rückt sie nicht heraus, solange gekämpft wird. Also fragt TomoMod nicht mehr. Es beschreibt jetzt, was es will — diese Auren, so viele, so angeordnet, so gestaltet — und das Spiel sucht und sortiert selbst und reicht die fertigen Symbole zurück. Auf TomoMods Seite liest nichts mehr eine Aura, also bleibt nichts mehr zu verweigern. Jede Aurenreihe im Addon arbeitet jetzt so: Schwächungen und Stärkungen auf Plaketten, Auren und Ziel-Stärkungen auf den Fenstern, Gruppen-Heilüberzeit-Symbole, Schlachtzugs-Schwächungen und -Heilüberzeit. Die Heilüberzeit-Reihen brauchten einen Zwischenschritt: Sie erkannten bestimmte Zauber, und genau der Zauber wird zurückgehalten — also wird die Liste der zu beobachtenden Zauber vorab an das Spiel gegeben, das die Auswahl übernimmt. Der Reinigungshinweis war am schwersten zu lösen und ändert dabei seine Form. Früher war es ein farbiger Rahmen um das Fenster eines Spielers, der aufleuchtete, wenn ein schädlicher Effekt zu dem passte, was ihr entfernen könnt — und da beides nicht mehr einsehbar ist, leuchtete er nur außerhalb des Kampfes auf, also genau dann nicht, wenn ein Heiler ihn braucht. Jetzt ist es ein kleines Symbol in der Ecke des Fensters, und das Spiel wählt selbst den Effekt: Man kann es direkt fragen, ob ihr etwas reinigen könnt, und es antwortet, ohne jemanden hinsehen zu lassen. Zwei Dinge dazu: Blutungen erscheinen nie, weil keine Klassenfähigkeit sie entfernt, und Kontrolleffekte bleiben bewusst draußen, da sie ihre eigene Anzeige haben. Vier Fehler kamen dabei ans Licht: ein Fehler bei jedem Verschwinden einer Plakette, mitten im Kampf erzeugte Symbole ohne Größe, die dauerhaft unsichtbar blieben, Schalter für Schwächungen und Heilüberzeit, die erst nach einem Neuladen wirkten, und ein Größenregler, der still nichts mehr steuerte.",
    ["wn_345_aura_layout"] = "Behoben — Aurenreihen brachen nicht mehr um und wuchsen stets in dieselbe Richtung, ganz gleich was eingestellt war. Die Anzeige dem Spiel zu überlassen hieß, ihm die Größe eines Symbols mitzuteilen, und dazu gehörten weder die Laufrichtung der Reihe noch die Stelle, an der sie umbricht — beides gehört zur Reihe selbst und wurde schlicht nie weitergegeben. Beide Richtungen wirken wieder, waagerecht und senkrecht unabhängig voneinander, ebenso der Abstand zwischen den Symbolen. Dazu passend: Eine auf acht Auren eingestellte Reihe konnte sechzehn zeichnen, wenn sie Stärkungen und Schwächungen zugleich zeigte, denn das sind zwei getrennte Listen und jede bekam das volle Kontingent. Das Kontingent wird nun geteilt. Die Kehrseite: Eine Reihe von acht lässt sich nicht mehr vollständig mit Schwächungen füllen, wenn es keine Stärkungen gibt — die beiden Listen können einander keinen Platz leihen.",
    ["wn_345_cdf_probe"] = "Neu — Die Stärkungssymbole im Cooldown Studio behalten ihren Countdown im Kampf. Das Studio ist die eine Anzeige, die sich nicht als Ganzes an das Spiel übergeben lässt: Es stellt Abklingzeiten und Stärkungen in dieselbe Reihe, wofür das Spiel keinen Begriff hat, und was es wirklich braucht, ist ohnehin enger — läuft diese Stärkung, und wie lange noch — also genau das, was es nicht mehr ansehen darf. Es fragt also, ohne das Spiel zeichnen zu lassen: An jedes Symbol wird eine unsichtbare Markierung gehängt, die nur diese eine Stärkung beobachtet, und das Spiel treibt den Ablauf des Symbols direkt an. Ob die Stärkung läuft, beantwortet die Frage, ob diese Markierung auf dem Bildschirm ist — eine Frage an ein Stück Oberfläche, nicht an die Stärkung. Eine Folge, die man kennen sollte: Immer nur eines darf den Ablauf schreiben, denn zwei im Wechsel waren die Ursache des Flackerns.",
    ["wn_345_dm_dropdowns"] = "Behoben — Auf der Optionsseite des Schadensmessers öffneten sich die Auswahlfelder für Design und Balkentextur mit der richtigen Anzahl Zeilen und ohne jede Beschriftung. Der Messer benennt seine Listen auf die eine Weise, TomoMods Auswahlfeld erwartet die andere, und anders als die übrigen Bedienelemente hat dieses keinen Ersatzwert — also wurde jede Zeile leer gezeichnet. Die Seite Schadensmesser hat außerdem jetzt ein eigenes Symbol im Menü; sie teilte es sich bislang mit der Diagnoseseite, sodass zwei Einträge dasselbe Bild trugen.",

    -- =====================
    -- 3.4.4 — Was ist neu
    -- =====================

    ["wn_344_damagemeter"] = "Neu — TomoMod hat jetzt einen Schadensmesser. DPS und HPS, erlittener Schaden, vermeidbarer Schaden, Schaden an Gegnern, Absorptionen, Unterbrechungen, Bannungen und Tode, aufgeteilt in Schaden, Heilung und Aktionen, die du über die Kopfzeile durchschaltest, mit einer laufenden und einer Gesamtsitzung sowie einer Kampfuhr. Es lohnt sich zu wissen, wie er arbeitet, denn das erklärt, was er kann und was nicht: Er liest Blizzards eigene Kampfdaten, statt das Kampfprotokoll mitzuhören und alles selbst zusammenzurechnen. Das bedeutet keine Flut von Ereignissen zum Filtern und Zahlen, die mit Blizzards eigenem Messer übereinstimmen, weil es dieselben Zahlen sind. Ein Client ohne diese Daten sagt das deutlich, statt dir ein leeres Fenster zu zeigen. Er hört auf /tdm und kann in Sagen, Gruppe, Schlachtzug, Gilde, Instanz, als Flüstern, im passenden Kanal deiner Gruppe oder nur an dich selbst berichten.",
    ["wn_344_dm_windows"] = "Neu — Bis zu fünf Messfenster gleichzeitig, jedes mit eigenem Typ, eigener Sitzung, eigenen Spalten und eigenem Zahlenformat: Schaden und Heilung nebeneinander zu verfolgen ist der Normalfall, und mit einem einzigen Fenster hieß das, den ganzen Kampf über hin und her zu schalten. Zieh ein Fenster an ein anderes und sie docken Kante an Kante an — von da an bewegen sie sich gemeinsam und teilen sich die gemeinsame Kante, sodass das Vergrößern des einen auch das andere vergrößert, und wegziehen löst die Verbindung wieder. Neun Erscheinungsbilder kommen mit: Tomo Dark, Tomo Neon, Minimal, Glossy, Ember, Frost, Terminal, Void und Parchment, dazu die Balkentextur, die Schriftart und ihre Größe, die Balkenhöhe, die Akzentfarbe oder Klassenfarben, die Transparenz im und außerhalb des Kampfes und eine Option, die eigene Leiste stets sichtbar zu halten.",
    ["wn_344_dm_breakdowns"] = "Neu — Eine Zahl auf einer Leiste sagt nicht, was sie erzeugt hat. Linksklick auf eine Leiste öffnet ihre Zauber direkt darunter, Rechtsklick gibt ihnen ein eigenes Fenster: Summen, Treffer, kritische Treffer und kritische Trefferquote je Zauber. Eine Aufschlüsselung nach Ziel beantwortet die andere Hälfte — nicht was du gewirkt hast, sondern worauf — und jeder Pull lässt sich als eigener Abschnitt lesen statt nur als Teil der laufenden Gesamtsumme. Ein Klick auf einen Spieler in der Todesliste öffnet einen Rückblick darauf, was ihn getötet hat; er kann sich auch von selbst öffnen, wenn du stirbst. /tdm resetpos holt dieses Fenster zurück in die Mitte, falls es irgendwo Unpraktischem gelandet ist.",
    ["wn_344_dm_runrecap"] = "Neu — Ein Rückblick am Ende eines Dungeons: Schaden, Heilung, Unterbrechungen, Tode und vermeidbarer erlittener Schaden für die ganze Gruppe, der sich am Ende des Laufs von selbst öffnet oder mit /tdm recap zurückgeholt wird. Er baut sich unterwegs auf, statt am Ende alles auszulesen, und das ist keine Vorliebe: Genau in dem Moment, in dem ein Schlüssel endet, lässt das Spiel ein Addon diese Werte gar nicht mehr lesen, sodass ein auf die naheliegende Weise geschriebener Rückblick nicht einmal die Gruppe sortieren könnte. Stattdessen wird jedes Mal, wenn du den Kampf verlässt, still eine Momentaufnahme gemacht — etwa fünfzehn Mal pro Schlüssel, zu Kosten, die du nicht bemerkst. Was in diesem Moment unlesbar ist, bleibt unangetastet statt überschrieben zu werden, sodass der letzte gültige Wert eines Spielers nie verloren geht.",
    ["wn_344_dm_standalone"] = "Hinweis — Der Messer erscheint auch eigenständig als TomoDamageMeter. Wenn du den installiert hast, tritt die in TomoMod eingebettete Kopie beim Laden zurück und sagt dir das einmal beim Anmelden, statt dass zwei Messer um dieselben Fenster, Einstellungen und Kampfsitzungen streiten. Zurück tritt immer die eingebettete: Das eigenständige Addon zu installieren ist eine bewusste Entscheidung, und die bereits verbreiteten Versionen davon können gar nicht wissen, dass sie selbst zurücktreten sollten.",
    ["wn_344_cds_window"] = "Behoben — Im Cooldown Studio zeichnete sich die Spalte der Leisten-Schaltflächen am linken Rand über die Schaltfläche für den Bearbeitungsmodus am unteren Fensterrand, und die Beschriftungen quollen aus den Schaltflächen heraus, die sie trugen: „Import : Buffs suivis“ war schlicht breiter als das Feld, in dem es saß. Die Spalte war über den für sie reservierten Platz hinausgewachsen, als die Import-Schaltflächen hinzukamen, und nichts in dieser Oberfläche beschneidet ein Element, das überläuft — es zeichnet sich einfach über das, was darunter liegt. Der Platz wird jetzt aus dem berechnet, was er aufnehmen muss, die Schaltflächen sind breit genug für ihren eigenen Text, und das Fenster ist entsprechend größer. Es verlangt auch nicht mehr Platz, als dein Bildschirm hat: Ihm war nur gesagt worden, auf dem Bildschirm zu bleiben, was bei einem Fenster, das größer als die Anzeige ist, nichts bewirkt — auf einem kleineren Bildschirm konnte die gesamte linke Spalte jenseits des Randes liegen. Es passt sich nun dem verfügbaren Raum an, und genau das macht das Vergrößern überhaupt erst gefahrlos. AstralForge baut auf demselben Fenster auf und profitiert ebenso davon. Auf der Übersichtsseite ist die Karte Cooldown Studio außerdem nach oben neben die Karte der Tomo-Suite gerückt, da beide nach außen führen.",
    ["wn_344_changelog_popup"] = "Behoben — Die Seite mit den Neuerungen brachte die angezeigten Hinweise nicht sauber unter: Beim Aufklappen einer Version lagen ihre Absätze übereinander. Der Grund: Ein Textblock muss gemessen werden, bevor das Fenster seine Breite festgelegt hat, sodass ein Absatz, der über sechs Zeilen laufen würde, als eine einzige gemessen wurde und alles darunter in den Platz gesetzt wurde, den diese eine Zeile eingenommen hätte. Statt der Seite das Messen von Text beizubringen, reicht sie die gewählte Version nun an genau dieses Fenster weiter, das schon immer scrollen konnte. Die Seite selbst ist jetzt ein Verzeichnis: jede Version als Schaltfläche mit der Anzahl ihrer Hinweise, vier pro Reihe, die neueste zuerst — neunundfünfzig davon in einer einzigen Spalte bedeuteten viel Scrollen, um überhaupt etwas Älteres zu erreichen. Zwei kleinere Dinge kommen dazu. Das Lesen einer alten Version gilt nicht mehr als Lesen der aktuellen: aus Neugier nachzuschlagen, was sich in 3.2.1 geändert hat, verschluckt nicht mehr den Hinweis auf ein Update, das du noch nicht gesehen hast. Und die Bildlaufleiste dieses Fensters hatte an beiden Enden einer ansonsten grünen Spur Blizzards zwei messingfarbene Pfeile behalten; sie sind weg, und die Leiste nutzt den Platz, den sie belegt hatten.",
    ["wn_344_dm_config"] = "Neu — Die Einstellungen des Messers sind jetzt eine echte Seite Schadensmesser in TomoMods Optionen und nicht mehr eine Schaltfläche, die in ein anderes Fenster führte. Design, Balkentextur, Schriftart und -größe, Balkenhöhe und Akzent in Klassenfarbe; Deckkraft des Hintergrunds, außerhalb des Kampfes und auf den Detailfenstern; Realmnamen ausblenden, die eigene Leiste im Blick behalten, Tooltips auf den Leisten, Kampf-Timer und auf welcher Seite er sitzt, Zurücksetzen beim Betreten einer Instanz, Fenster aneinander andocken; automatische Dungeon- und Todesrückblicke und wie viele Zeilen ein Bericht verschickt. Darunter laufen diese Seite und das eigene Fenster des Messers nun über eine einzige Beschreibung dessen, was bei einer Änderung aufgefrischt werden muss — sonst gäbe es zwei Kopien davon, und sie würden auseinanderlaufen, sobald eine von beiden bearbeitet wird. Schlägt eine Auffrischung fehl, wird die Einstellung trotzdem gespeichert, statt einen Fehler zu zeigen und still zurückzunehmen, was gerade geändert wurde. Spalten, neue Fenster und Kategoriefilter bleiben bewusst im Fenster des Messers, da sie auf ein bestimmtes Fenster wirken und nicht auf alles; die Seite sagt das und bringt einen dorthin. Jenes Fenster öffnete sich außerdem hinter den Optionen statt davor, was behoben ist.",
    ["wn_344_aura_secret"] = "Behoben — Die Auren der Einheitenfenster erzeugten unter Patch 12.1 eine Flut von Fehlern — 189 in einer einzigen Sitzung in dem Bericht, der dazu geführt hat. Früher lieferte das Spiel schlicht nichts zurück, wenn ein Addon die Auren einer Einheit in einem Zustand abfragte, den es nicht guthieß; nun verweigert es die Anfrage rundheraus, und diese Verweigerung wurde nicht abgefangen, sodass sie bei jedem Aura-Ereignis auslöste. Jetzt wird sie abgefangen, und sie hat einen Ausweg: Die Auren werden stattdessen einzeln gelesen, was langsamer ist, aber der einzig verbliebene Weg — und eine Aura, die noch erscheint, ist besser als eine, die einen Fehler erzeugt. Die Buff-Überwachung von CooldownForge hatte dasselbe Problem von der anderen Seite: Die Aura-Aktualisierung des Spiels kann inzwischen vollständig unlesbar ankommen, und allein die Prüfung, ob es sich um eine vollständige Aktualisierung handelte, reichte zum Scheitern — weitere 38 Mal in einer Sitzung. Eine unlesbare Aktualisierung gilt jetzt als vollständige, und es wird einfach alles neu eingelesen; anders lässt sich nicht aktuell bleiben, wenn die Einzelheiten nicht einsehbar sind.",

    -- =====================
    -- 3.4.3 — Was ist neu
    -- =====================
    ["wn_343_changelog"] = "Neu — Eine Seite mit Neuerungen in den Optionen, die jede Version enthält, die TomoMod je veröffentlicht hat. Bisher tauchten die Versionshinweise nur in dem Fenster nach einem Update auf, und dieses zeigt ausschließlich die Version, auf die du gerade gewechselt bist — einmal geschlossen, ist der Text endgültig weg. Die neue Seite listet jede Version auf, die neueste zuerst, und ein Klick auf eine öffnet ihre Hinweise. Sie liest dieselben Hinweise wie das Fenster, es gibt also keine zweite Liste, die veralten könnte.",
    ["wn_343_cdf_resync"] = "Neu — Cooldown Studio: Eine Leiste, die du aus Blizzards Cooldown-Manager erstellt hast, kann jetzt wieder mit ihm abgeglichen werden. Solche Leisten stimmten an dem Tag, an dem du sie erstellt hast, und hatten danach keinen Weg zurück: Nach einer Klassenüberarbeitung musstest du die Listen von Hand vergleichen. Resynchronisieren liest die Kategorie neu ein: Fähigkeiten, die Blizzard seitdem hinzugefügt hat, kommen dazu, entfernte werden entfernt. Alles, was du an der Leiste eingestellt hast, bleibt erhalten — ein weiterhin gelisteter Zauber behält seinen Eintrag genau so, wie du ihn abgestimmt hast, samt Leuchtbedingung, Sichtbarkeit je Spezialisierung und Effekten pro Eintrag — und was du selbst hinzugefügt hast, wird nie angerührt und nie entfernt, ganz gleich was Blizzards Liste tut. Ein Zauber, den du von Hand hinzugefügt hast und den Blizzard später in die Kategorie aufnimmt, bleibt deiner, statt übernommen zu werden, sodass eine spätere Resynchronisierung niemals einen Eintrag löschen kann, den du erstellt hast.",
    ["wn_343_cds_icons"] = "Cooldown Studio: Die Liste dessen, was eine Leiste verfolgt, zeigte Sort 384100 — korrekt und völlig nutzlos. Jeder Eintrag zeigt jetzt sein Symbol und seinen Namen, die ID steht in Klammern dahinter. Solange der Client den Zauber noch nicht zwischengespeichert hat, bekommst du weiterhin nur die Nummer, was die ehrliche Antwort ist statt einer leeren Zeile.",
    ["wn_343_cds_scale"] = "Neu — Cooldown Studio: ein Regler für die Symbolskalierung, in beiden Anordnungen. Eine Leiste zu vergrößern hieß bisher, den Breitenregler zu verschieben und den Höhenregler danach exakt an dieselbe Stelle zu bringen; jetzt ist es ein einziges Bedienelement. Es ist eine Sicht auf die Größe, die du ohnehin schon hattest, und keine neue Einstellung — darunter liegt weiterhin eine einzige Zahl, und nichts muss im Gleichschritt gehalten werden. Eine Schaltfläche stellt quadratische Symbole wieder her und behält dabei die Größe, die du gerade vor dir hattest, statt auf den Standard zurückzuspringen. Sobald du Breite und Höhe bewusst auseinanderziehst, wird der Skalierungsregler ausgegraut — eine Skalierung um 1,2 hat dann keine eindeutige Antwort mehr — und genau diese Schaltfläche holt ihn zurück.",
    ["wn_343_iconsize_range"] = "Behoben — Cooldown Studio: Eine Symbolgröße unter 24 oder über 64 wirkte akzeptiert und war es nicht. Die Leiste wurde in der gewünschten Größe dargestellt und behielt sie, bis eine spätere Aktion — eine Resynchronisierung, ein Import, ein Duplizieren — sie stillschweigend zurücksetzte, ohne dass irgendetwas diese Änderung mit dem verband, was du zuvor getan hattest. Die getrennten Einstellungen für Breite und Höhe akzeptierten derweil die ganze Zeit 8 bis 128, sodass dasselbe kleine Symbol über das eine Bedienelement erreichbar und über das andere abgelehnt war. Es gibt jetzt einen einzigen Bereich, 8 bis 128, für alle drei. Er ist weiter als zuvor und nicht enger: Keine bestehende Leiste ändert ihre Größe.",
    ["wn_343_studio_shortcut"] = "Neu — Eine Cooldown-Studio-Schaltfläche auf der Übersichtsseite, damit das Öffnen des Studios nicht mehr den Umweg über die CooldownForge-Seite verlangt.",

    -- =====================
    -- 3.4.2 — Was ist neu
    -- =====================
    ["wn_342_astralforge"] = "Neu — AstralForge, ein bildschirmfüllender Editor für die Bestandteile eines Einheitenfensters. Bisher saß jeder Teil eines Fensters dort, wo TomoMod es entschieden hatte, und alles, was du bekamst, war ein Regler, der ihn ein paar Pixel weiter schob — den Namen auf die andere Seite zu holen war also keine Einstellung, sondern eine Zahl, die groß genug war, ihn hinüberzuschieben. Jetzt ziehst du jedes Teil dorthin, wo du es haben willst: welche Ecke des Elements andockt und woran sie andockt — Fenster, Lebensbalken, Ressourcenbalken, Infoleiste. Es rastet auf einem feinen Raster ein, richtet sich an anderen Elementen aus, wenn du daran vorbeikommst, und mit gehaltener Umschalttaste setzt du frei ab. Die Regler bleiben für eine Korrektur um zwei Pixel, und beide schreiben dasselbe. Geöffnet wird er aus den Einheitenfenster-Optionen und lädt wie das Cooldown Studio nur auf Anforderung. Was du ziehst, ist eine Vorschaukopie, nie ein echtes Fenster: Die echten sind im Kampf geschützt, und sie direkt zu bearbeiten ist genau das, was die Schnittstellenprobleme verursacht, die TomoMod zwei Versionen lang beseitigt hat.",
    ["wn_342_af_nameplates"] = "Neu — Namensplaketten bekommen denselben Editor, und für sie ist das komplettes Neuland: außer der Schlachtzugsmarkierung hatte auf einer Plakette nichts überhaupt eine Positionseinstellung. Der Name, Lebenswert und -prozentsatz, die Stufe, Klassifizierungssymbol und -text, die Zauberleiste mit Symbol, Name, Zeitanzeige und Schild sowie das Questsymbol lassen sich einzeln platzieren. Deine bestehende Position der Schlachtzugsmarkierung wird unverändert übernommen, alles andere startet genau dort, wo es schon war. Zwei Dinge sind bewusst nicht verschiebbar: Auren, deren Position aus ihrem Platz in der Reihe berechnet und nicht gesetzt wird, und die Teile, die am Füllstand einer Leiste hängen — ein Griff daran würde vorgeben, etwas zu bewegen, das er nicht bewegen kann.",
    ["wn_342_af_props"] = "Neu — Deckkraft, Skalierung und eine übersteuerte Textgröße, je Element. Die Übersteuerung beginnt bei null, also „lass die Größe, die das Modul errechnet hat“ — es ändert sich nichts, bis du es sagst. Angezeigt werden nur die Einstellungen, die das jeweilige Teil auch wirklich umsetzen kann: Deckkraft ergibt bei einem Text Sinn, eine Skalierung nicht, und ein reines Bild nimmt weder das eine noch das andere — du bekommst also, was auf das Ausgewählte zutrifft, statt einer festen Reihe von Reglern, von denen die Hälfte nichts tut.",
    ["wn_342_af_customtext"] = "Neu — Text, den du selbst schreibst. Füge bis zu sechs eigene Texte auf einem Einheitenfenster und vier auf einer Namensplakette hinzu, schreibe etwas wie „[name] - [level]“ und platziere es wie jedes andere Element. Die Platzhalter sind Name, Stufe, Klasse, Volk und Gilde auf einem Fenster sowie Name, Stufe, Klasse, Volk und Klassifizierung auf einer Plakette. Es lohnt sich zu wissen, warum das Addon die Wörter nicht einfach aneinanderhängt: In Midnight liefert das Spiel Name und Stufe einer Einheit in einer Form, die ein Addon nicht lesen darf — schon etwas so Gewöhnliches wie einen Namen mit einem Bindestrich zu verbinden würde also fehlschlagen. Deine Vorlage wird in ein Muster verwandelt, die Werte werden unberührt durchgereicht und das Spiel selbst setzt alles zusammen.",
    ["wn_342_af_presets"] = "Neu — Layout-Vorlagen und Teilen-Zeichenfolgen. Speichere das gesamte Layout dessen, was du gerade bearbeitest, unter einem Namen — jede Position, jede Deckkraft und Skalierung, jeden eigenen Text —, wende es später wieder an oder gib es als Zeichenfolge weiter, die jemand einfügt. Alles, was hereinkommt, wird gleich geprüft, ob es von dir stammt oder von einer fremden Person: Werte, die das Addon nicht kennt, werden verworfen, ein unmöglicher Ankerpunkt wird abgelehnt, bevor er das Spiel erreicht, und ein Layout, das sich im Kreis auf sich selbst bezieht, wird aufgebrochen. Das Schlimmste, was eine eingefügte Zeichenfolge beschreiben kann, ist ein Layout.",
    ["wn_342_af_migration"] = "Deine Fenster verrutschen nicht. Jede Position, die du eingestellt hattest, wird zusammen mit dem Anker, gegen den die Engine sie angewandt hat, in die neue Form überführt — ein umgestelltes und ein brandneues Profil zeichnen also exakt dasselbe Fenster. Eine alte Einstellung wird verworfen statt übernommen: ein Aura-Versatz, den die Engine seit 3.0.5 nicht mehr liest. Er hat seit mehreren Versionen keine Wirkung, und ihn jetzt zu übernehmen würde Auren verschieben, die genau dort sitzen, wo du sie hingestellt hast. Auch die Aura-Behälter hören auf, ihre Position an einer zweiten eigenen Stelle zu führen: sie im Spiel zu ziehen, sie im Editor zu platzieren und sie mit den Reglern zu setzen schreibt jetzt an dieselbe Stelle — widersprechen können sie sich damit nicht mehr.",
    ["wn_342_af_secret"] = "Behoben — AstralForge auf einer tatsächlich vorhandenen Einheit zu öffnen konnte dir ein leeres Fenster hinterlassen. Die erzeugte Vorschau wurde mit echten Daten gefüttert, und im aktuellen Spiel verbirgt jedes Interface-Teil, dessen Inhalt aus geschützten Informationen stammt — etwa ein Lebenswert —, auch seine eigene Position und Größe vor Addons. Genau diese zu messen ist die ganze Aufgabe des Editors: Die allererste Messung schlug fehl und riss die Vorschau mit sich. Die Vorschau läuft jetzt mit erfundenen Daten: ein erfundener Name, ein erfundener Lebenswert, die sich problemlos messen lassen und genau so aussehen wie das, was du gerade einrichtest. Zwei Absicherungen kommen dazu: Was sich trotzdem nicht messen lässt, bleibt einfach ohne Anfasser, statt alles ringsherum anzuhalten, und wenn sich die Vorschau überhaupt nicht bauen lässt, öffnet das Fenster trotzdem mit Elementliste, Inspektor und Vorlagen, statt leer zu bleiben.",
    ["wn_342_keysync_realm"] ="Mythisch+: Die Schlüsselliste der Gruppe war für alle vom eigenen Realm leer. Ihr Schlüssel kam die ganze Zeit an und wurde auch gespeichert — er ließ sich danach nur nicht wiederfinden. Wenn das Addon einer anderen Person dir ihren Schlüssel schickt, benennt das Spiel sie als „Alice-Varimathras“, egal ob das dein Realm ist oder nicht: Jeder Schlüssel wird also unter einem vollständigen Namen abgelegt. Fragt TomoMod das Spiel aber nach der Person, die auf deinem eigenen Realm neben dir steht, bekommt es „Alice“ ohne Realm zurück — und das passt zu nichts. Aufgetaucht ist das mit dem neuen Schlüsselaustausch in 3.4.1, weil die ersetzte Bibliothek diesen Unterschied in ihrem eigenen Code verborgen hatte. Ein Name ohne Realm wird jetzt zusätzlich mit deinem versucht, sodass ein Schlüssel vom eigenen Realm wieder gefunden wird — und zwar an einer einzigen Stelle, dort wo die Schlüssel liegen, statt in jeder Ansicht, die sie ausliest.",
    ["wn_342_escape_keys"] = "Behoben — Solange eines von TomoMods eigenen Fenstern offen war, taten deine Tasten nichts mehr: Du konntest dich nicht bewegen, und deine Fähigkeiten lösten nicht aus. Jedes Fenster, das sich mit Escape schließt, muss das Spiel um die Tastatur bitten, und ein Fenster, das die Tastatur hält, behält jede Taste für sich, sofern es den Rest nicht bewusst weitergibt — was es nur nebenbei tat, nämlich beim Empfang einer Taste, die es gar nicht interessierte, und im Kampf überhaupt nicht, also genau dann, wenn verlorene Tasten am teuersten sind. Jetzt geht jede Taste direkt durch; das Fenster behält allein Escape, und nur außerhalb des Kampfes. Dazu kommt die andere Hälfte des Problems: Ein Fenster hält die Tastatur nur, solange es tatsächlich zu sehen ist. Ein mit Escape geschlossenes Fenster behielt seinen Griff danach, sodass das Problem das verursachende Fenster überdauerte und das nächste geöffnete Fenster es erbte. Das betrifft jedes Fenster des Addons, das sich mit Escape schließt: die Optionen, den Installer, das Beutefenster, den Mythisch+-Hub, TomoScore, den Berufshelfer, das Taschen-Design, das Chat-Kopierfenster und das Cooldown Studio.",
    ["wn_342_keysync_debug"] ="Neu — /tmt keysync. Der Befehl zeigt, über welchen Kanal der Austausch läuft, ob du in einer Gilde bist, alle gerade gespeicherten Schlüssel und dann jedes Gruppenmitglied mit dem Hinweis, ob sein Schlüssel tatsächlich gefunden wird. Genau um diese letzte Zeile geht es: Ein Schlüssel, der gespeichert, aber nicht auffindbar ist, ist ein anderes Problem als einer, der nie angekommen ist — und in der Gruppenliste sehen beide völlig gleich aus. Deshalb hat der Fehler oben länger gedauert zu erkennen als zu beheben. Zum Abschluss fragt der Befehl die Gruppe nach ihren Schlüsseln: Führst du ihn eine Sekunde später erneut aus, siehst du, ob jemand geantwortet hat.",
    ["wn_342_cdf_viewer"] = "Neu — Cooldown Studio: Baue mit einem Klick eine Leiste aus Blizzards eigenem Abklingzeit-Manager. Drei Schaltflächen — Essenziell, Hilfreich und Verfolgte Stärkungszauber — erstellen eine fertige Leiste aus den Fähigkeiten, die Blizzard für deine aktuelle Spezialisierung zusammenstellt, in Blizzards eigener Reihenfolge; die verfolgten Stärkungszauber kommen als Stärkungszauber an und nicht als Abklingzeiten, erscheinen also, solange sie aktiv sind, und zählen ihre Restdauer herunter. Die Liste wird in dem Moment gelesen, in dem du klickst, und nie gespeichert: Blizzard hält diese drei Kategorien über Klassenüberarbeitungen hinweg aktuell, eine importierte Leiste folgt also dem Spiel, statt eine Kopie einzufrieren, die für einen Patch stimmt und ab dem nächsten unbemerkt falsch ist. Wo ein Talent eine Fähigkeit durch eine andere ersetzt, landet die Ersetzung auf der Leiste, damit das Symbol dem in deinem Zauberbuch entspricht. Das ist ein Ausgangspunkt und keine Festlegung: Du bekommst eine ganz normale Leiste, die du umsortieren, kürzen und umgestalten kannst. Und wenn dein Client keinen Abklingzeit-Manager hat oder Blizzard für die Spezialisierung, in der du bist, nichts zusammenstellt, sagt das Studio es dir, statt dir eine leere Leiste zu geben.",

    -- =====================
    -- 3.4.1 — Was ist neu
    -- =====================
    ["wn_341_style"] = "Mythisch+-Tracker: Er war der letzte Bildschirm in TomoMod mit eigenen Farben. Die letzte Version hat die Auswertung nach dem Lauf angeglichen und dabei gesagt, dass der Tracker während des Schlüssels erst passt, wenn er denselben Durchgang bekommt — hier ist er. Er nutzt jetzt dasselbe Grün, denselben Text und dieselben Ränder wie jedes andere Fenster, auf fast schwarzem Grund mit einem Minzstich. Dazu kommt eine Schriftgröße von 0,70 bis 1,60: Sie vergrößert den Text, ohne das Fenster zu vergrößern.",
    ["wn_341_segments"] = "Mythisch+-Tracker: Der Timer besteht jetzt aus drei Segmenten, eines pro Truhe, und jedes zählt die Zeit herunter, bis diese Truhe verloren ist. Bisher zeigte das Fenster die verstrichene Zeit und den Abstand zum vollen Limit, und „wie lange noch bis die +2 weg ist“ war Kopfrechnen zwischen zwei Pulls. Die Segmente werden aus den echten Truhenzeiten des Dungeons berechnet, sie lesen sich von links nach rechts als Minze, Gelb und Rot — das gerade laufende Fenster benennt sich also selbst über die Farbe — und ein verbrauchtes Segment wird blasser statt zu verschwinden, damit die Leiste weiter die Geschichte des Laufs erzählt. Wer die Leiste lieber über die Form als über die Farbe liest, färbt mit einer Einstellung alle drei im selben Grün.",
    ["wn_341_presets"] = "Mythisch+-Tracker: Aus einem festen Fenster wurden drei Erscheinungsbilder. Fenster ist das, was du bereits hattest. HUD lässt Hintergrund und Kopfblock weg und listet die Ziele als schlichten Text, etwas größer, in einer schmalen Schrift. Minimal sind drei Zeilen und sonst nichts — Informationen, Timer, Trash — die Bossliste entfällt und ihr Zählerstand wandert in die Kopfzeile: Du weißt also weiterhin, dass du bei 2 von 4 stehst, ohne dafür vier Zeilen auszugeben. Alles, was eine Vorlage setzt, ist auch ein eigener Schalter: Hintergrund, Kopfblock, Dungeonname, Bossliste, Timer-Aufbau, Segmentfarben, Textgröße. Änderst du einen von Hand, sagt die Vorlage „benutzerdefiniert“, statt so zu tun, als wärst du noch auf ihr.",
    ["wn_341_forces"] = "Mythisch+-Tracker: Die Trash-Leiste konnte lügen, statt zuzugeben, dass sie nichts sieht. Das Spiel verbirgt im Kampf immer mehr Werte, und die Leiste rechnete trotzdem mit ihnen — ein nicht lesbarer Stand kam also als Null heraus, und eine Leiste, die sich mitten im Pull leert, sieht nicht nach fehlenden Daten aus, sondern nach einem Reset. Sie hält jetzt den letzten wirklich gelesenen Wert und weicht stufenweise zurück: genaue Zahlen, dann nur der Prozentsatz, dann eingefroren. Außerdem zeigt sie, was noch zu töten ist, statt 730 / 1000, und nennt die Zeit, zu der der Zähler voll war.",
    ["wn_341_bossnames"] = "Mythisch+-Tracker: Die Bossnamen stammten aus einer handgeschriebenen Tabelle, die jede Saison veraltet. Blizzard fügt Dungeons hinzu und verwendet Journaleinträge zwischen ihnen erneut — eine solche Liste ist am Tag des Patches falsch, und nichts warnt dich davor: Die Namen fallen einfach auf „Boss 1“ zurück. Namen werden jetzt live aus dem Spiel aufgelöst, der Reihe nach auf drei Wegen: über die Karte, auf der du stehst, dann über den Namen des Dungeons im Abgleich mit dem Journal, dann über den rohen Zieltext, falls beides scheitert. Was gefunden wird, wird pro Dungeon gemerkt — es ist gelernt statt vorgeschrieben und kann daher nicht veralten.",
    ["wn_341_splits"] = "Mythisch+-Tracker: Es gab nichts, womit sich ein Lauf vergleichen ließ. Jeder beendete Schlüssel wird jetzt pro Dungeon und pro Stufe aufgezeichnet, und beim nächsten Versuch zeigt jeder Boss, wie weit du vor oder hinter deinem besten Lauf liegst. Der Trash bekommt dieselbe Behandlung: Bei jedem Kill notiert der Tracker, wo dein bester Lauf zu diesem Zeitpunkt beim Trash stand, und zeigt dir den Abstand. Auch ein abgestürzter Lauf wird aufgezeichnet — er ist womöglich deine einzige Referenz für diesen Dungeon, und eine langsame ist besser als gar keine. Nichts ist vorgeladen: Eine mitgelieferte Tabelle „erwarteter Trash bei Boss 2“ wäre die Route eines anderen und wäre falsch, sobald der Dungeon neu abgestimmt wird. Eine Schaltfläche in den Optionen löscht das Aufgezeichnete.",
    ["wn_341_banner"] = "Mythisch+-Tracker: Das Ende eines Schlüssels ging kommentarlos vorbei. Es gibt jetzt ein Banner — in der Zeit oder abgestürzt, die Laufzeit, die Aufwertungen und der Abstand in Klammern. Dieser Abstand ist die Zahl, die am Ende eines Schlüssels alle laut aussprechen, und er war das Einzige, was du dir selbst aus einem längst angehaltenen Timer zusammenrechnen musstest.",
    ["wn_341_options"] = "Mythisch+-Tracker: Er hatte ein eigenes zweites Optionsfenster mit denselben Einstellungen wie die Mythisch+-Seite in TomoMods Konfiguration — zwei Orte für denselben Wert, und sie liefen auseinander. Es ist weg: /tmt öffnet jetzt die Konfiguration auf der Mythisch+-Seite. Alle anderen /tmt-Befehle bleiben unverändert.",
    ["wn_341_legibility"] = "Mythisch+-Tracker: Der Text auf einer gefüllten Leiste war unlesbar. Jede Beschriftung des Trackers hat eine schwarze Kontur, und dieser Text war selbst fast schwarz — er löste sich also in seiner eigenen Kontur auf: Die Truhenmarken auf dem Timer und die Beschriftung der Trash-Leiste waren nur noch Flecken, während die weiße Uhr daneben gestochen scharf blieb. Sie sind jetzt hell. Zwei Kleinigkeiten kamen mit: Eine negative Dauer konnte als große positive erscheinen, aus -3:40 wurde 56:20, und der erste Boss wiederholt seine Kill-Zeit nicht mehr zweimal in derselben Zeile.",
    ["wn_341_cds_taint"] = "Cooldown Studio: Es zu öffnen konnte dich am Ausloggen hindern, auf zwei verschiedenen Wegen. Eine Zeile schrieb in eine Tabelle, die Blizzard gehört — am Wert änderte das nichts, aber allein das Schreiben reicht, damit das Spiel danach jedem Fenster misstraut, das aus dieser Tabelle gebaut wird, die Logout-Bestätigung eingeschlossen. Davon unabhängig behandelte das Fenster „Stil kopieren von“ die Escape-Taste mit einer eigenen Kopie von Code, den es anderswo im Addon längst gibt, und diese Kopie war abgedriftet: Ihr fehlte die Kampfprüfung, und sie gab Tasteneingaben so an das Spiel zurück, dass sich das Spielmenü nicht mehr öffnete. Beides ist behoben, und das Fenster nutzt jetzt die gemeinsame Umsetzung statt einer eigenen. Keiner der beiden Fälle betraf eine Sitzung, in der du das Studio nicht geöffnet hattest — deshalb hat es gedauert, sie zuzuordnen.",
    ["wn_341_keysync"] = "TomoMod meldete sich bei jedem Kampf dutzendfach selbst als Quelle von Oberflächenproblemen, ohne eine zu sein. Ursache war eine mitgelieferte Bibliothek, LibOpenRaid: Sie stellt fest, ob das Spiel einen Wert verbirgt, indem sie ihn zu lesen versucht und den Fehler auffängt — die Antwort stimmt, aber das Spiel schreibt bei jedem Versuch TomoMods Namen in sein Protokoll, und das passiert pausenlos. Die Bibliothek wird nicht mehr ausgeliefert. Sie war nur wegen vier Schlüsselstein-Funktionen da, synchronisierte daneben aber auch Abklingzeiten, Ausrüstung, Talente und Haltbarkeit — und genau der Abklingzeiten-Teil verursachte alles. Das Teilen von Schlüsselsteinen ist jetzt TomoMods eigenes, in einer viel kleineren Datei: Dein Schlüssel kommt direkt aus dem Spiel, der Rest wird mit Gruppe und Gilde ausgetauscht und bis zum wöchentlichen Reset behalten. Eines dürfte zum ersten Mal funktionieren: Die Schlüsselliste der Gruppe aktualisiert sich von selbst, wenn sich ein Schlüssel ändert — der alte Rückruf war so verdrahtet, dass die Bibliothek ihn nie aufrief.",
    ["wn_341_buffskin"] = "Die Gestaltung der Stärkungs- und Schwächungszauber wurde entfernt — die gesamte Funktion samt Reiter und Einstellungen. Auf dem aktuellen Spiel ist sie nicht umsetzbar: Die Schaltflächen, die Blizzard für Auren verwendet, verbergen ihre eigene Größe inzwischen vor Addons, und ein Rand darauf löst einen Fehler innerhalb von Blizzards Code aus — nicht in TomoMods, wo er sich hätte abfangen lassen. Dazu kommt, dass diese Schaltflächen fast bei jedem Patch umgebaut werden: Allein diese Version hat fünf Anläufe darauf verwendet. Das ist Pflege ohne Ende, ausgerechnet an dem Teil der Oberfläche, an dem Blizzards eigene Darstellung bereits genügt. Dein Buff-Fenster kehrt zum Standard zurück, und die Einstellungen werden aus deinen Profilen entfernt, da es keinen Ort gibt, an den sie passen. Wenn dir ein gestaltetes Buff-Fenster wichtig ist, ist ein eigenes Auren-Addon die ehrliche Antwort.",
    ["wn_341_auratracker"] = "Der Aura-Tracker wurde entfernt. CooldownForge erledigt dieselbe Aufgabe besser, und zwei Overlays laufen zu lassen, die sich um dieselbe Bildschirmecke streiten, konnte nicht anders enden. Sein Reiter, seine Vorlagen, sein Mover und seine Einstellungen gehen mit, und eine einmalige Bereinigung entfernt die übrig gebliebenen Einstellungen aus deinen Profilen, statt sie ewig mitzuschleppen. Falls du dort Zauber von Hand hinzugefügt hattest, gehen sie nicht stillschweigend verloren: Automatisch umwandeln lassen sie sich nicht, also listet TomoMod sie bei deiner nächsten Anmeldung einmal mit Namen auf, und du kannst die, die dir noch wichtig sind, im Cooldown Studio neu anlegen.",
    ["wn_341_cds_reload"] = "Cooldown Studio: Es zu schließen kann jetzt die Oberfläche neu laden, und tut es standardmäßig. Das Studio lädt nur auf Anforderung, aber das Spiel kann ein Addon nicht wieder entladen — nur ein Neuladen gibt es frei, und dasselbe Neuladen beseitigt auch alles, was die Sitzung unterwegs aufgesammelt haben könnte. Die Nachfrage wartet auf einen sinnvollen Moment: nie im Kampf, nie während eines Schlüssels, nie in einem Dungeon oder Schlachtzug — und sie kommt zurück, sobald du draußen bist. In den CooldownForge-Optionen lässt sie sich abschalten. Außerdem: Das Studio zu verlassen, während die Leisten entsperrt waren, ließ sie im Bearbeitungsmodus zurück, samt schwebender Fortsetzen-Schaltfläche; beide Wege, das Fenster zu schließen, räumen jetzt auf.",

    -- =====================
    -- 3.3.6 — Was ist neu
    -- =====================
    ["wn_336_cdf_active"] = "CooldownForge: Ein aktiver Buff sah genauso aus wie ein Zauber, der gerade auflädt. Seit ein Symbol einen Buff statt einer Abklingzeit verfolgen kann, erreichten beide Zustände den Bildschirm als dasselbe schlichte Bild, und der einzige Weg, sie zu unterscheiden, war die Zahl darauf zu lesen. Zwei neue Einstellungen trennen sie: Der Abklingzeit-Wischer und der Rand können jeweils Ihre Klassenfarbe oder eine selbst gewählte Farbe annehmen, solange der verfolgte Buff aktiv ist. Beide sind überall standardmäßig aus, es ändert sich also nichts an dem, was Sie bereits gebaut haben, und sie gelten nur für Einträge, die tatsächlich einen Buff verfolgen.",
    ["wn_336_cdf_threshold"] = "CooldownForge: Der Countdown kann die Farbe wechseln, wenn ein Zauber fast zurück ist. Legen Sie eine Schwelle in Sekunden fest, bis zu 60, und wählen Sie die Farbe, die er darunter annimmt — eine Farbe mitten im Kampf zu lesen geht schneller, als eine Zahl zu entziffern. Null schaltet es ab und ist die Vorgabe. Wo das Spiel einem Addon die verbleibende Zeit verweigert, was bei eingeschränkten Inhalten der Fall ist, behält der Timer seine normale Farbe, statt zu raten: Ein Countdown, der falsch rät, wäre schlimmer als einer, der schlicht bleibt.",
    ["wn_336_cdf_font"] = "CooldownForge: Der Text auf Ihren Symbolen war auf eine einzige Schriftart festgelegt. Die Einstellung gab es in jeder Leiste seit dem Erscheinen der Funktion, und nichts hat sie je gelesen — Countdown, Stapel, Zaubername und Spiegel-Timer waren alle fest auf TomoMods eigenes Poppins verdrahtet. Sie können nun jede von Ihren anderen Addons geteilte Schriftart wählen, eine dünne, dicke oder gar keine Kontur nehmen und dem Countdown eine eigene Größe unabhängig von Stapel- und Namenstext geben, sodass ein Schriftwechsel nicht mehr bedeutet, die Größen Ihres Presets aufzugeben. Beide Größenregler laufen jetzt von 8 bis 28 Pixel statt von 9 bis 20. Ohne installiertes Schriftarten-Addon enthält die Liste nur Poppins und sagt das auch.",
    ["wn_336_cdf_glow_charges"] = "CooldownForge: Das Leuchten kann warten, bis alle Aufladungen zurück sind. Ein Zauber mit zwei oder drei Aufladungen war aus Sicht des Leuchtens bereit oder nicht, also leuchtete eine von drei Aufladungen genauso wie drei von drei. Die neue Bedingung wird aus dem Aufladen selbst abgeleitet statt aus einem Zählen — das Spiel verbirgt die aktuelle Zahl im Kampf, und Zählen ist genau das, was dort nicht geht. Ein Zauber ohne Aufladungen fällt auf die einfache Bereitschaft zurück, damit die Bedingung nicht bei den meisten Ihrer Einträge stillschweigend wirkungslos ist.",
    ["wn_336_cdf_glow_stacks"] = "CooldownForge: Das Leuchten kann warten, bis ein verfolgter Buff eine bestimmte Stapelzahl erreicht, einstellbar pro Leiste und pro Symbol überschreibbar. Das Spiel nennt kein Maximum für einen Buff, die Zahl geben also Sie vor — 2 bis 20 auf einer Leiste, bis zu 99 bei einem einzelnen Eintrag. Lässt sich die Stapelzahl nicht lesen, bleibt das Leuchten aus, statt auf einer Vermutung auszulösen, denn ein Leuchten ist etwas, worauf man reagiert.",
    ["wn_336_escape_taint"] = "Fenster: Escape konnte das Spielmenü überhaupt nicht mehr öffnen, sodass sich das Spiel nicht mehr auf normalem Weg beenden ließ. Acht TomoMod-Fenster schlossen sich mit Escape, indem sie sich in eine Liste eintrugen, die Blizzard aus dem Code seines Spielmenüs heraus durchläuft — und dieser Code führt drei Aufrufe aus, die das Spiel verweigert, sobald in der Sitzung irgendetwas gestört wurde. Das Menü öffnete sich also nie und Escape tat nichts. Diese Fenster verarbeiten Escape jetzt selbst und rühren das Spielmenü nicht mehr an. Alle anderen Tasten werden weiterhin durchgereicht. Eine Folge, die man kennen sollte: Im Kampf schließt Escape diese acht Fenster nicht mehr, weil der dafür nötige Aufruf im Kampf selbst eingeschränkt ist. Die Schließen-Schaltfläche funktioniert weiterhin.",
    ["wn_336_statusbar2"] = "Neu — Blizzards Statusleiste 2 ausblenden, unter QOL, Automatisierungen. Die zweite Statusleiste des Bearbeitungsmodus liegt neben der Hauptleiste statt in ihr, weshalb die Option zum Ausblenden von Blizzards Statusleisten sie nie erreichte und es nirgends eine Einstellung dafür gab. Sie wird unsichtbar und klickdurchlässig gemacht statt entfernt, und genau das verhindert Fehler: Die Leiste gehört weiterhin Blizzard, bleibt also im Bearbeitungsmodus vorhanden und dort verschiebbar. Wird die Option abgewählt, ist sie nach einem Neuladen wieder da.",
    ["wn_336_ab_empty_refresh"] = "Aktionsleisten: Bei ausgeblendeten leeren Plätzen blieb der Knopf leer, wenn man einen Zauber darauf zog. Der Zauber war tatsächlich vorhanden und wurde beim Klicken gewirkt, aber es wurde nichts darauf gezeichnet, bis man neu lud — und ein Ablegen auf der Leiste löschte die benachbarten Plätze, die gerade erst für das Ziehen eingeblendet worden waren. Das Ausblenden leerer Plätze wurde in der letzten Version umgestellt, um keine Fehler mehr an Blizzards Knöpfen auszulösen, und bei der neuen Methode bemerkte die Leiste nicht, dass ein Platz belegt worden war. Jetzt bemerkt sie es, auch wenn ein Seitenwechsel oder eine Haltung ändert, worauf ein Knopf zeigt.",
    ["wn_336_uf_aura_growth"] = "Einheitenfenster: Auren wuchsen ausschließlich nach unten. Die Richtungseinstellung deckte links und rechts ab, für die vertikale Hälfte gab es überhaupt keine Einstellung — ein Fenster am unteren Bildschirmrand schickte seine zweite Schwächungsreihe also über die Kante hinaus, ohne dass irgendetwas das hätte aufhalten können. Neben der horizontalen steht jetzt eine vertikale Richtung im Auren-Reiter jeder Einheit, und die Reihen können sich nach oben stapeln. Nach unten bleibt die Voreinstellung, und nichts an dem, was du bereits eingerichtet hast, verschiebt sich; auch das Fenster selbst bewegt sich nicht, nur der Aurenblock wächst in die andere Richtung.",
    ["wn_336_ts_palette"] = "Mythic+: Die Wertungstafel am Ende eines Laufs war der einzige Bildschirm in TomoMod mit eigenen Farben — ein cyanfarbener Akzent, wo der Rest des Addons grün ist, auf einem blaustichigen Hintergrund, wo der Rest neutral ist. Sie stammte aus der Zeit vor der Eingliederung in TomoMod und war nie angeglichen worden, weshalb sie wie das Fenster eines fremden Addons wirkte. Sie übernimmt nun dasselbe Thema wie alles andere. Zwei Farben bleiben bewusst unverändert: Der Balken „in der Zeit“ und sein Text behalten ihr eigenes Grün, denn auf einer ohnehin durchgehend grünen Oberfläche sagt eine Markierung „in der Zeit“ im selben Grün nichts mehr aus. Der Tracker während des Schlüssels ist vorerst unangetastet, beide passen also erst zusammen, wenn er dieselbe Behandlung erhält.",
    ["wn_336_cdf_talent"] = "CooldownForge: Ein Symbol kann an ein Talent gebunden werden — nur sichtbar, wenn es gewählt ist, oder nur, wenn es das nicht ist. Die zweite Hälfte ist so nützlich wie die erste: Ein Build, der ein Talent aufgibt, gewinnt meist etwas an dessen Stelle, und beide Symbole können nun in derselben Leiste liegen, während nur das passende zu sehen ist. Sie geben den Zauber an, den das Talent gewährt, nicht eine Knotennummer: Knoten werden bei jeder Talentüberarbeitung neu nummeriert, Zauber nicht, also übersteht die Bedingung einen Patch. Sie folgt jetzt auch Ihren Loadouts — ein Build-Wechsel meldet sich anders an als das Bearbeiten von Talenten, und nur eines von beiden wurde gehört, sodass eine Bedingung noch mit dem vorherigen Build antworten konnte, bis etwas anderes eine Aktualisierung erzwang.",

    -- =====================
    -- 3.3.5 — Was ist neu
    -- =====================
    ["wn_335_cdf_border"] = "CooldownForge: Am Regler für die Randstärke zu ziehen ließ den Rand verschwinden, statt ihn dicker zu machen. Jede Stileinstellung wurde als ein Block gespeichert, der Editor schreibt aber ein Feld nach dem anderen — die Stärke zu setzen warf also den daneben liegenden Randmodus weg, und ohne Modus wurde das Symbol ganz ohne Rand gezeichnet. Eine Farbe zu wählen bewirkte dasselbe, einen Modus zu wählen setzte die Stärke stillschweigend zurück. Diese Einstellungen behalten nun die Felder, die Sie nicht angefasst haben. Keine Leiste ändert sich von allein; setzen Sie den Wert erneut und Sie bekommen, worum Sie beim ersten Mal gebeten hatten.",
    ["wn_335_cdf_border_paint"] = "CooldownForge: Auch nachdem er nicht mehr verschwand, war der Rand kaum zu sehen, und 1 Pixel sah genauso aus wie 4. Der Umriss wird knapp innerhalb der Symbolkante gezeichnet, und das Bild des Symbols bedeckte ihn vollständig — der Rand wurde also gemalt und dann darunter versteckt, und ihn dicker zu machen begrub nur mehr davon. Das Bild endet jetzt vor dem Rand und lässt ihm Platz. Zwei Dinge sind zu erwarten: Ein Symbol mit Rand zeigt sein Bild ganz leicht kleiner, was ein Rand nun einmal kostet, und eine Stärke, die Sie eingestellt haben, als der Regler nichts zu bewirken schien, wird plötzlich sichtbar — eine auf 4 stehen gebliebene Leiste wirkt also deutlich schwerer, bis Sie den Wert auf das setzen, was Sie eigentlich wollten. Symbole ohne Rand bleiben unverändert.",
    ["wn_335_cdf_preset"] = "CooldownForge: Jede Feineinstellung anzufassen verwandelte Ihre Leiste stillschweigend in eine Tomo-Leiste. Eine Randfarbe auf einer Net- oder Verre-Leiste zu wählen schaltete deren Stil auf „Benutzerdefiniert“, und Benutzerdefiniert war kein echter Stil — das Symbol fiel also auf Tomo zurück, und die von Ihnen gewählte Grundlage war weg. Welches Vorgabeprofil eine Leiste nutzt und ob sie Feineinstellungen hat, sind jetzt zwei getrennte Dinge: Das Profil zu wechseln behält Ihre Feineinstellungen darüber, und eine Feineinstellung zu ändern lässt das Profil in Ruhe. Bereits als Benutzerdefiniert gespeicherte Leisten werden zu Tomo mit erhaltenen Einstellungen — genau so wurden sie ohnehin schon gezeichnet, auf dem Bildschirm ändert sich also nichts.",
    ["wn_335_cdf_thickness"] = "CooldownForge: Der Regler für die Randstärke geht bis 10 statt bis 4. Vier war eine faire Grenze, solange der Rand unsichtbar war; jetzt, wo er tatsächlich gezeichnet wird, ist sie es nicht mehr. Bedenken Sie, dass der Rand seine Breite vom Symbolbild nimmt: Bei 10 bleibt von einem kleinen Symbol kaum etwas übrig.",
    ["wn_335_cdf_target"] = "CooldownForge: Eine Leiste kann jetzt davon abhängen, ob Sie ein Ziel haben — neben den bestehenden Bedingungen für Kampf, Instanz, Gruppe und Schlachtzug und mit denselben drei Möglichkeiten: egal, voraussetzen, das Gegenteil voraussetzen. Für die Leiste, die nur oben sein soll, während Sie tatsächlich auf etwas draufhalten, oder die Hilfsleiste, die verschwinden soll, sobald Sie ein Ziel anwählen.",
    ["wn_335_cdf_dim"] = "CooldownForge: Eine Leiste, deren Sichtbarkeitsbedingung nicht erfüllt ist, kann nun ausblassen, statt zu verschwinden. Wählen Sie „Deckkraft verringern“ statt „Ausblenden“ und legen Sie fest, wie blass sie werden soll, von 5 % bis 95 %. Die abgeblendete Leiste bleibt lebendig — sie verfolgt weiterhin Abklingzeiten, statt einzufrieren. „Im Kampf = Ja“ mit dieser Option lässt Ihnen außerhalb des Kampfes also eine lesbare, halb sichtbare Leiste, statt einer, die bereits veraltet zurückkommt. Ausblenden bleibt die Voreinstellung, und an bereits eingerichteten Leisten ändert sich nichts.",
    ["wn_335_cdf_iconwh"] = "CooldownForge: Symbole müssen nicht mehr quadratisch sein. Breite und Höhe haben jetzt je einen eigenen Regler, 8 bis 128 Pixel, statt einer Größe für beides — breite flache Symbole für eine Reihe am oberen Bildschirmrand, hohe schmale für eine Spalte neben Ihren Fenstern. Bereits gebaute Leisten verrutschen nicht: Die neuen Werte starten unbelegt, und unbelegt heißt „die alte quadratische Größe beibehalten“.",
    ["wn_335_cdf_aura"] = "CooldownForge: Ein Symbol kann einen Buff statt einer Abklingzeit verfolgen. Stellen Sie einen Eintrag auf „verfolgter Buff“, und er bleibt vom Bildschirm fern, solange der Buff fehlt, und erscheint dann mit Restdauer und Stapeln, solange er aktiv ist — ein Proc kann so auf derselben Leiste neben der Fähigkeit sitzen, die ihn auslöst. Sie können auch eine abweichende Buff-ID angeben, für Procs, die von einem Zauber gewährt und als ein anderer angewendet werden. In Mythisch+ verbirgt das Spiel das meiste, was ein Addon über einen Buff lesen kann; das wird weiter unten gesondert behandelt.",
    ["wn_335_cdf_secret"] = "CooldownForge: Ein verfolgter Buff verschwand, sobald ein Kampf begann, und kam zurück, sobald er endete. Jede Abfrage lief über die Zauber-ID des Buffs, und in Midnight verbirgt das Spiel diese Zahl während des Kampfes — gemessen als außerhalb des Kampfes voll lesbar gegenüber 6,5 % im Kampf, wobei jeder verfolgte Buff genau in dem Frame verschwand, in dem der Pull begann. Das Spiel gibt diese ID allerdings einmal heraus, im Moment der Anwendung des Buffs, zusammen mit einem Verweis auf genau diese Anwendung: TomoMod merkt sich nun dieses Paar und fragt fortan nach der Anwendung — was das Spiel weiterhin beantwortet. Auch die Restdauer und die Stapelzahl sind in Mythisch+ zurück, auf demselben Weg ausgelesen — der frühere Hinweis, verfolgte Buffs funktionierten dort, aber ohne Zeitanzeige, trifft nicht mehr zu.",
    ["wn_335_cdf_aura_sources"] = "CooldownForge: Verfolgte Buffs werden nun über zwei Wege gefunden statt über vier. Jeder war hinzugekommen, um einen Fall abzudecken, den der vorherige verfehlte, und nichts verriet, welcher die Arbeit tatsächlich leistete — also wurden sie über je rund 12 700 Abfragen gemessen. Zwei trugen die gesamte Funktion, und sie decken entgegengesetzte Hälften ab: einer wirkt während eines Kampfes, der andere außerhalb. Die beiden, die fast nichts beitrugen, wurden entfernt, und mit ihnen ein Durchlauf durch alle Ihre Buffs, der in jedem Einzelbild und für jede Leiste lief. Eine weitere Lücke schließt sich dabei: Ein Buff, der lediglich eine Anwendung dazugewinnt, meldet das Spiel als Aktualisierung und nicht als neuen Buff — ein so mitten im Kampf erstmals bemerkter Proc wurde daher nie erfasst. Was bleibt, ist eine Grenze des Spiels, die man besser kennt als sucht: Im Kampf benennt es nur einen Teil der Auren. Ein Buff, der beim Kampfbeginn bereits läuft, wird normal verfolgt; einer, der mitten im Kampf aufgebracht wird, ist mitunter nicht identifizierbar, und sein Symbol bleibt verborgen. Dafür gibt es keine Einstellung, und die Option für verfolgte Buffs sagt das jetzt an Ort und Stelle.",
    ["wn_335_cdf_viewer_source"] = "CooldownForge: Ein Proc, der mitten im Kampf auslöst, wird jetzt ebenfalls verfolgt — die unmittelbar darüber beschriebene Grenze fällt größtenteils weg. Das Spiel verrät einem Addon nicht, um welchen Buff es sich handelt, aber es zeichnet ihn die ganze Zeit auf Ihren Bildschirm: Blizzards eigene Anzeige verfolgter Stärkungszauber unterliegt nicht den Beschränkungen, denen ein Addon unterliegt. TomoMod liest nun diese Anzeige — ob das Symbol da ist, die verbleibende Zeit, die Anzahl der Stapel — statt eine Frage zu stellen, die das Spiel im Kampf nicht beantwortet. Nichts ist fest verdrahtet und nichts Geschütztes wird angefasst: Es liest dasselbe Bild, das Sie sehen. Es deckt nur Buffs ab, die Blizzards Anzeige verfolgter Stärkungszauber tatsächlich führt: Für alles andere antworten die beiden bisherigen Methoden genau wie zuvor, es kommen also Fälle hinzu und keiner fällt weg. Gut zu wissen, wenn Sie das neue leistenweise Ausblenden nutzen: Eine ausgeblendete Cooldown-Manager-Leiste kostet Sie das nicht, denn das Ausblenden läuft über Transparenz und die Leiste arbeitet darunter weiter. Ein optisches Detail, mit dem Sie im Kampf rechnen sollten: Wo das Spiel die Zahlen zurückhält, den Countdown aber trotzdem zeichnet, spiegelt TomoMod diese Ziffer auf Ihr Symbol — Sie bekommen die Restzeit als Zahl, ohne den Wischer dahinter, und sie springt in Schritten statt gleichmäßig zu laufen, denn die Leiste aktualisiert sich über Ereignisse und nicht über einen Timer.",
    ["wn_335_cdf_aura_timer"] = "CooldownForge: Ein verfolgter Buff konnte ohne Zeitanzeige und ohne Wischeffekt erscheinen, obwohl das Spiel genau mitgeteilt hatte, wie lange er noch läuft. Es gab zwei Wege, einen Countdown auf das Symbol zu bringen, und der falsche wurde bevorzugt: jener, der ein Dauer-Objekt entgegennimmt, das das Spiel in einer anderen Form zurückgibt als die Abklinganzeige erwartet. Sie nahm es an, zeichnete nichts und meldete keinen Fehler — das Sicherheitsnetz, das genau dieses Scheitern abfangen sollte, löste also nie aus, und der numerische Weg, der funktioniert hätte, wurde nie erreicht. Lesbare Zahlen werden nun zuerst verwendet, das Objekt nur dann, wenn das Spiel die Zahlen verweigert. Falls Ihre verfolgten Buffs als nacktes Symbol erschienen, bekommen sie ihre Zeitanzeige und ihre Anwendungen zurück.",
    ["wn_335_cdf_glow_aura"] = "CooldownForge: Die Leuchtbedingung „solange ein Buff auf Ihnen aktiv ist“ erlosch für die gesamte Dauer jedes Kampfes, und niemand hatte die Verbindung zu den verfolgten Buffs hergestellt. Sie fragte das Spiel auf dieselbe Weise nach Ihrem Buff, wie es verfolgte Buffs ursprünglich taten — die Weise, die mit dem Kampfbeginn keine Antwort mehr gibt — das Leuchten hörte also schlicht auf, was eher nach einem falsch eingerichteten Leuchten aussieht als nach einem Fehler. Sie findet Buffs jetzt genau so wie die Symbole verfolgter Buffs, sodass beide sich nicht mehr darüber uneinig sein können, was Sie tragen.",
    ["wn_335_microbar"] = "Neu — Mikroleiste: Blizzards kleine Reihe von Menütasten wird zu Ihrer eigenen Leiste. Wählen Sie, welche Tasten erscheinen und in welcher Reihenfolge, waagerecht oder senkrecht, wie viele pro Zeile, ihre Größe, ihren Abstand, ihre Skalierung und Deckkraft — und platzieren Sie sie über das Bewegen-Fenster, wo Sie möchten. Sie kann dauerhaft sichtbar bleiben, beim Überfahren erscheinen oder beim Überfahren erscheinen und im Kampf dauerhaft oben bleiben. Symbole können Ihre Klassenfarbe, eine selbst gewählte Farbe oder ihr Originalaussehen annehmen, mit optionaler Entsättigung und einem Zoom unter dem Mauszeiger. Jede Taste reicht Ihren Klick einfach an Blizzards eigene weiter: So funktioniert alles auch im Kampf weiter, und nichts geht kaputt, wenn dem Spiel ein neues Fenster hinzugefügt wird. Die Originaltasten laufen zudem darunter weiter, sodass ihre Hinweise, ihre ausgegrauten Zustände und ihre Tastenbelegungen auf Ihre Tasten gespiegelt werden können — mit vier Hinweis-Leuchteffekten zur Auswahl, Abdunklung für gerade nicht Verfügbares und der Tastenbelegung auf dem Symbol.",
    ["wn_335_cdf_aura_gate"] = "CooldownForge: Ein verfolgter Buff muss kein Zauber mehr sein, den Sie wirken können. Bevor die Leiste irgendein Symbol zeigt, prüft sie, ob der Eintrag überhaupt auf Sie zutrifft — bei einem Zauber sah sie dafür in Ihrem Zauberbuch nach, was für eine Abklingzeit richtig und für einen Buff falsch ist. Proc-Buffs werden Ihnen von einem Talent gewährt oder von einem anderen Zauber aufgebracht, das Zauberbuch sagt also, dass Sie sie nicht haben, und der Eintrag flog hinaus, bevor irgendetwas nachsah, ob der Buff tatsächlich aktiv war. Das Symbol erschien nie — und genau dafür sind verfolgte Buffs überwiegend da. Ein verfolgter Buff wird jetzt am Buff gemessen.",
    ["wn_335_cdf_aura_link"] = "CooldownForge: Einen Proc zu verfolgen heißt nicht mehr, die Zauber-ID des Buffs selbst aufspüren zu müssen. Eine Fähigkeit und der Buff, den sie gewährt, haben fast nie dieselbe ID — die Fähigkeit einzutragen, also das Naheliegende, überwachte damit einen Buff, den niemand je hat, und das Symbol blieb schlicht vom Bildschirm fern. Ein Eintrag probiert jetzt zusätzlich das, was das Spiel mit der eingetragenen ID verknüpft: Blizzards Cooldown-Manager löst dasselbe Problem bereits für seine eigene Anzeige verfolgter Buffs, und TomoMod liest dieselbe Antwort aus. Nichts davon ist fest verdrahtet, es folgt also von allein einem Patch, der einen Proc umhängt, oder einem Talent, das ihn austauscht. Das optionale Buff-ID-Feld funktioniert weiterhin und hat weiterhin Vorrang — für die Fälle, die das Spiel nicht verknüpft.",
    ["wn_335_cds_reorder"] = "Cooldown Studio: Einträge einer Leiste lassen sich nach oben und unten verschieben. Die Reihenfolge der Symbole zu ändern hieß bisher, einen Eintrag zu entfernen, ihn am Ende wieder hinzuzufügen und alles Nachfolgende neu aufzubauen. Ist das Optionsfeld für den verschobenen Eintrag geöffnet, folgt es diesem Eintrag, statt auf dem Platz stehen zu bleiben — zuvor bearbeitete es am Ende denjenigen, der dessen Stelle eingenommen hatte.",
    ["wn_335_mplus_teleport_override"] = "Mythisch+: Ein Dungeon-Teleport, der in Ihrem Zauberbuch steht, konnte trotzdem als nicht erlernt gemeldet werden — die Zeile ausgegraut, der Tooltip meldete ihn als nicht verfügbar, der Klick tat nichts. Wenn ein Dungeon in einer späteren Saison zurückkehrt, gibt Blizzard seinen Teleport als anderen Zauber neu heraus: Skyreachs Teleport wird inzwischen als „Voie des cieux“ gewirkt und nicht als der Warlords-Zauber, den TomoMods Tabelle aufführt. Die Prüfung fragte immer nur nach dem aufgeführten Zauber, also sah der Besitz des aktuellen Zaubers genauso aus wie gar kein Besitz. Sie fragt jetzt zusätzlich beim Spiel nach, welcher Zauber den bekannten ersetzt, und akzeptiert beide — über die Zaubernummer statt über den Namen, sodass es in jeder Client-Sprache funktioniert und auch einer künftigen Saison folgt, die einen Teleport neu zuordnet, ohne dass ein Update nötig wäre.",
    ["wn_335_ab_taint"] = "Aktionsleisten: Die Option „leere Tastenplätze anzeigen“ war die Quelle einer Reihe von Fehlern über blockierte Aktionen an den Tasten der unteren linken Leiste — Fehler, die das Spiel jeweils dem Addon anlastete, das gerade zufällig lief, was zuletzt so aussah, als sei Cooldown Studio schuld. Das Anzeigen der leeren Plätze geschah durch Schreiben in Blizzards eigenen Tastenzustand und durch erzwungenes Einblenden, was das Spiel danach nicht mehr anfassen will. Die Option nutzt jetzt die spieleigene Einstellung „Aktionsleisten immer anzeigen“, und Leisten, die ihre leeren Plätze nicht zeigen sollen, werden stattdessen unsichtbar und klickdurchlässig gemacht. Blizzard behält die Kontrolle über seine Tasten. Zwei Dinge sind zu beachten: Diese Einstellung ist global, sie schaltet sich also ein, sobald auch nur eine Ihrer Leisten leere Plätze möchte, und falls Sie sie selbst in Blizzards Optionen aktiviert hatten, wird sie wieder abgeschaltet, sobald keine TomoMod-Leiste sie mehr braucht. Einen Zauber auf einen leeren Platz zu ziehen funktioniert genau wie zuvor.",
    ["wn_335_cdm_viewers"] = "Cooldowns: Blizzards vier Cooldown-Manager-Leisten lassen sich jetzt einzeln ausblenden, auf der Cooldowns-Seite neben der Schaltfläche für das Cooldown Studio — Essential, Utility und die beiden Anzeigen für verfolgte Stärkungszauber haben je ein eigenes Häkchen. Ein Häkchen nimmt diese Leiste vom Bildschirm und aus TomoMods Platzierungsmodus und lässt die anderen drei unberührt. Es ersetzt ein einzelnes Häkchen, das gar nichts ausgeblendet hat: Es beendete lediglich TomoMods Gestaltung dieser Leisten, die daraufhin in Blizzards eigenem Aussehen auf dem Bildschirm blieben — ein Kästchen namens „Cooldown-Manager-Leisten ausblenden“, das sie auffälliger machte statt unauffälliger. Eine ausgeblendete Leiste wird unsichtbar und klickdurchlässig gemacht, nicht gelöscht: Es bleibt Blizzards Leiste, sie läuft darunter weiter, und ob sie überhaupt existiert, entscheidet nach wie vor Blizzards Bearbeitungsmodus. Das Häkchen wieder zu entfernen stellt sie genau dort wieder her, wo Sie sie platziert hatten. Der Schalter unter CD & Ressourcen bleibt unverändert und beantwortet eine andere Frage — ob TomoMod diese Leisten überhaupt gestaltet, nicht welche davon Sie sehen möchten. Beide greifen jetzt auch zusammen: Das Ausblenden einer Leiste funktioniert weiterhin, wenn das Cooldown-Manager-Modul selbst abgeschaltet ist — die eine Kombination, bei der das Häkchen gespeichert und nie auf irgendetwas angewendet wurde, und genau das, was jemand versucht, der diese Leisten loswerden will.",
    ["wn_335_cdf_entry_spec"] = "CooldownForge: Die Spezialisierung eines Eintrags ließ sich nur in dem Moment wählen, in dem Sie ihn hinzufügten. Danach gab es nirgends eine Möglichkeit, sie zu ändern — ein Symbol, das auf der falschen Spezialisierung angelegt wurde oder bevor Sie sich entschieden, es auf eine zu beschränken, musste gelöscht und neu hinzugefügt werden, wodurch es auch seinen Platz in der Leiste verlor. Das Auswahlmenü sitzt jetzt am Eintrag selbst, sowohl im Cooldown Studio als auch auf der Einstellungsseite „Cooldowns“.",
    ["wn_335_scrollbar_click"] = "Einstellungen: Die Bildlaufleiste im Einstellungsfenster ist jetzt sichtbar und bedienbar. Sie bestand aus fünf Pixeln Dunkelgrau auf einem dunklen Panel — kaum zu treffen und überhaupt schwer zu bemerken, weshalb das Mausrad praktisch der einzige Weg durch eine lange Seite war. Ein Klick auf die Schiene ober- oder unterhalb des Griffs springt nun fast eine Bildschirmhöhe in diese Richtung, und der Griff lässt sich packen, ohne punktgenau zielen zu müssen. Auch das Aussehen ändert sich bewusst: etwas breiter, in hellerem Grau, mit einer dünnen dunklen Linie an der Innenkante, damit sie sich vom Panel dahinter abhebt. Die Textfelder für Import- und Exportzeichenfolgen haben dieselbe Leiste und passen jetzt dazu. Das gilt für jede Seite der Einstellungen, nicht nur für eine.",
    ["wn_335_cds_tabjump"] = "Cooldown Studio: Fast jede Änderung warf Sie auf einen anderen Reiter. Den Stil eines Symbols zu bearbeiten setzte Sie auf „Teilen“ ab, eine Sichtbarkeitsbedingung anzuhaken auf „Anordnung“. Der Editor baut sich nach beinahe jeder Änderung neu auf und öffnete dabei den Reiter, den er sich gemerkt hatte — gemerkt hat er sich einen Reiter aber nur beim allerersten Aufbau, blieb also auf dem hängen, den Sie zuletzt zum ersten Mal geöffnet hatten, und die Rückkehr zu einem bereits besuchten Reiter aktualisierte ihn nie. Er folgt nun dem Reiter, auf dem Sie tatsächlich sind.",

    -- =====================
    -- 3.3.4 — Was ist neu
    -- =====================
    ["wn_334_studio_reasons"] = "Cooldown Studio: Die Schaltfläche „Cooldown Studio öffnen“ konnte schlicht gar nichts tun. Jeder mögliche Grund, an dem das Laden des Editors scheiterte, wurde mit derselben Meldung gemeldet — „nicht installiert“ — einschließlich des mit Abstand häufigsten: Er ist installiert und in der Addon-Liste lediglich nicht angehakt. Jeder Grund nennt jetzt, worum es sich handelt und was dagegen zu tun ist.",
    ["wn_334_studio_enable"] = "Cooldown Studio: Wenn das einzige Problem ein fehlendes Häkchen in der Addon-Liste ist, setzt ein Klick auf die Schaltfläche dieses Häkchen und öffnet den Editor. Besteht das Spiel zuvor auf einem Neuladen, wird das gesagt — statt Sie die Einstellung selbst suchen zu schicken.",
    ["wn_334_studio_preflight"] = "Cooldown Studio: Die Karte im Reiter „Cooldowns“ weist auf ein blockiertes Öffnen hin, bevor Sie klicken, nicht danach. Die Schaltfläche bleibt bewusst anklickbar: Bei einem nicht angehakten Addon ist genau dieser Klick die Lösung.",
    ["wn_334_studio_init"] = "Cooldown Studio: Ein Editor, der zwar lud, aber nicht startete, schluckte Ihren Klick wortlos. Er meldet nun, dass er geladen wurde, sich aber nicht initialisieren konnte — und warum.",
    ["wn_334_studio_toc"] = "Cooldown Studio: Das Unter-Addon zeigt in der Addon-Liste jetzt das TomoMod-Symbol, eine Kategorie und die tatsächliche Versionsnummer des Addons. Es gab weiterhin 1.0.0 ohne Symbol an, was es wie das Addon einer fremden Person aussehen ließ, das zufällig denselben Namen trägt.",
    ["wn_334_package_builder"] = "Paketierung: Der Download wird nun von einem Skript erzeugt, das die Erstellung verweigert, wenn das Cooldown Studio im TomoMod-Ordner statt daneben landet. WoW sieht nur die oberste Ebene des AddOns-Ordners an — ein Studio eine Ebene tiefer ist ein Studio, das niemand in seiner Addon-Liste sieht. Genau diese Lage sollen die Hälfte der Korrekturen oben überhaupt erst erkennbar machen.",
    ["wn_334_diag_export"] = "Diagnose: Das Exportfenster bat Sie, den Bericht zu kopieren, und stellte die Adresse des Trackers in den Titel — eine Adresse, die Sie nur übernehmen konnten, indem Sie den gerade kopierten Bericht wieder wegwarfen. Es wechselt jetzt zwischen Bericht und Link, sagt Ihnen, was davon soeben in der Zwischenablage gelandet ist, und zeigt die Adresse im Klartext auf dem Bildschirm, damit Sie sie einfach ablesen können.",
    ["wn_334_diag_reminder"] = "Diagnose: Das Fenster weist nun darauf hin, dass Ihr Bericht gespeichert ist und sich jederzeit mit /tmdiag tracker wieder öffnen lässt — den Link zuerst zu nehmen kostet Sie also nichts. Beim Schließen wird die Adresse zusätzlich einmal pro Sitzung im Chat ausgegeben, falls Sie zu schnell geschlossen haben.",
    ["wn_334_presets_roles"] = "Presets: Die Presets Tank, Heiler und DPS schrieben je nur drei oder vier Einstellungen und übernahmen alles Übrige aus der gemeinsamen Grundlage — drei Archetypen, die dieselbe Konfiguration unter verschiedenen Namen waren. Jeder schreibt nun eine vollständige Rollenkonfiguration über Gruppen- und Schlachtzugsfenster, Namensplaketten, Zielauren, Ressourcen, Abklingzeiten und Zauberleisten: breite, bedrohungsgefärbte Plaketten mit numerischer Bedrohung für Tanks, deutlich größere Fenster mit HoTs, Entzauberungen und Schilden für Heiler, höhere Ressourcenleisten und nur eigene Schwächungszauber für Schadensausteiler.",
    ["wn_334_presets_reset"] = "Presets: Der Wechsel von einem Preset zum anderen behielt die Einstellungen des vorherigen. Ein Preset schrieb nur seine eigenen Änderungen, alles Unerwähnte blieb so, wie das letzte es hinterlassen hatte — von Tank zu Heiler zu wechseln ließ Sie mit Tank-Modus-Plaketten heilen. Die gemeinsame Grundlage enthält jetzt einen Wert für jede Einstellung, die ein Preset berühren kann, und wird jedes Mal zuerst geschrieben: Ein Preset anzuwenden ergibt dasselbe Ergebnis, ganz gleich, was davor aktiv war.",
    ["wn_334_presets_cards"] = "Übersicht: Die Presets sind jetzt Karten statt vier farbiger Schaltflächen, auf denen nur ein Name stand. Jede zeigt ihr Rollensymbol, ihren Kurztext und drei Punkte dazu, was sie tatsächlich ändert, mit der vollständigen Beschreibung beim Überfahren — und das gerade verwendete Preset ist als „Aktiv“ markiert, was dieses Panel bisher nirgends verriet.",
    ["wn_334_role_badges"] = "Einstellungen: Abschnitte, die für eine bestimmte Rolle wichtig sind, tragen nun ein kleines Tank-, Heiler- oder Schadenssymbol in der Überschrift — HoTs und Entzauberungen, Verteidigungsabklingzeiten, Tank-Modus, Unterbrechungsverfolgung, Bedrohungstext und mehr. Ein Überfahren der Symbole nennt die betroffenen Rollen.",
    ["wn_334_role_filter"] = "Einstellungen: Oben in der Seitenleiste gibt es jetzt eine Rollenfokus-Leiste — Alle, Tank, Heiler, DPS. Eine Auswahl hält die Einstellungen dieser Rolle voll sichtbar und dunkelt die übrigen ab. Es wird bewusst abgedunkelt und nicht ausgeblendet: Eine Option, deren Ort Sie bereits kennen, bleibt genau dort, wo Sie sie gelassen haben — unabhängig vom aktiven Fokus. Ihre Wahl bleibt über Sitzungen hinweg erhalten.",
    ["wn_334_chat_history_settings"] = "Chatverlauf: Das Einzige, was Sie damit tun konnten, war ihn einzuschalten. Er hat jetzt einen eigenen Abschnitt — wie lange Nachrichten aufbewahrt werden (1 Stunde bis 3 Tage oder ohne Grenze), wie viele Zeilen gespeichert werden (10 bis 500) und eine Sitzungsmarkierung nach den wiederhergestellten Zeilen, damit alles darunter eindeutig aus der aktuellen Sitzung stammt. Die Speichergrenze war zudem um eins daneben: Sie nannte 128 Zeilen und behielt 127.",
    ["wn_334_chat_history_delay"] = "Chatverlauf: Die wiederhergestellten Zeilen erschienen genau in dem Moment, in dem Addon-Ladehinweise und Lua-Fehler im Chat eintreffen, und begruben sie unter einer ganzen Seite Wiedergabe. Der Verlauf wartet nun ein paar Sekunden, bevor er erscheint — einstellbar, oder null für das frühere Verhalten.",
    ["wn_334_chat_history_channels"] = "Chatverlauf: Welche Kanäle aufbewahrt werden — Flüstern, Gilde, Offizier, Gruppe, Schlachtzug, Instanz, Kanäle, Sagen, Rufen, Emotes — war seit Einführung der Funktion eine Einstellung und tauchte nirgends in der Oberfläche auf. Jetzt steht sie im Panel. Ein nicht angehakter Kanal wird gar nicht erst aufgezeichnet und nicht bloß aus der Wiedergabe ausgelassen: Ihn wieder anzuhaken holt also nicht zurück, was in der Zwischenzeit vorbeigezogen ist.",
    ["wn_334_chat_history_clear"] = "Chatverlauf: Eine Schaltfläche löscht nun alles Gespeicherte, abgesichert durch eine Rückfrage, und das Ausschalten der Funktion löscht das bereits Gespeicherte mit, statt jede Zeile dauerhaft in Ihren gespeicherten Variablen liegen zu lassen. Das Panel weist darauf hin, bevor Sie das Häkchen entfernen — ebenso darauf, dass der Verlauf accountweit gespeichert und damit von allen Ihren Charakteren geteilt wird.",
    ["wn_334_roles_guides"] = "Rollen: eine neue Kategorie Rollen mit je einer Leitfaden-Seite für Tank, Heiler und Schaden. Jede erklärt, worauf es bei dieser Rolle wirklich ankommt, und jeder Punkt trägt eine Schaltfläche, die das Panel mit der zugehörigen Einstellung öffnet und sie hervorhebt. Die Seite wendet zudem das Preset der Rolle an und schaltet den Rollenfokus der Seitenleiste mit einem Klick um.",
    ["wn_334_search_nested_tabs"] = "Konfigurationssuche: Ein Treffer in einem verschachtelten Reiter — HoTs der Schlachtzugsfenster, Farben der Ressourcenleisten, alles, was ein Panel hinter seine eigene zweite Reiterreihe legt — öffnete die richtige Kategorie und landete dann auf deren erstem Reiter statt auf dem gesuchten. Der Index speicherte nur den innersten Reiternamen, den die äußere Reiterleiste nie zuordnen konnte. Er hält jetzt einen Namen pro Ebene fest, und jede Reiterleiste liest ihren eigenen.",
    ["wn_334_search_index_all_tabs"] = "Konfigurationssuche: Der Großteil der Einstellungen stand überhaupt nicht im Index. Seiten, die Sie nie geöffnet haben, werden einmal unsichtbar aufgebaut, damit die Suche sie finden kann — ein Panel baut jedoch nur seinen ersten Reiter, sodass alles hinter einem zweiten oder dritten Unterreiter, also der Großteil der Oberfläche, per Suche schlicht nicht auffindbar war. Nun wird jeder Reiter durchlaufen. Das ist deutlich mehr Arbeit, deshalb läuft sie im Hintergrund in Häppchen von wenigen Millisekunden, statt das Spiel bei der ersten Suche einzufrieren, und eine bereits angezeigte Trefferliste aktualisiert sich selbst, sobald sie fertig ist.",
    ["wn_334_search_index_duplicates"] = "Konfigurationssuche: Panels, die eine Seite über mehrere Reiter hinweg wiederverwenden — jede Zauberleisten-Einheit, jedes Einheitenfenster — fielen zu einem einzigen Treffer zusammen. Der Index behielt nur den innersten Reiternamen, also schrieben die Zauberleiste des Ziels und die des Fokus denselben Eintrag über dieselbe Sektion, und jede Kopie außer der ersten verschwand. Einträge tragen jetzt den vollständigen Pfad, und die Sektionen jeder Einheit werden einzeln aufgeführt.",
    ["wn_334_roles_deeplink"] = "Rollen: Die Schaltflächen auf den Leitfaden-Seiten öffneten die richtige Kategorie und ließen Sie dann auf dem zuletzt benutzten Reiter stehen. Sie schlugen ihre Einstellung im Suchindex nach, und genau diese Einstellungen — HoTs der Schlachtzugsfenster, Verteidigungszauber der Gruppe, Tank-Modus — fehlten dem Index. Jede Schaltfläche benennt nun ihren eigenen Weg, Reiter für Reiter: Sie landet auf der richtigen Seite und hebt die Sektion hervor, auf einem frisch gestarteten Client ebenso wie bei dem, was Sie gerade angesehen haben.",
    ["wn_334_cr_detection"] = "Klassenerinnerung: Sie las die Haltungsleiste nach Position. Katze war Platz 2, Bär Platz 1, Mondkin Platz 4 — wo eine Gestalt auf dieser Leiste sitzt, hängt aber von den Talenten ab. Verschob sie sich, verglich die Erinnerung Ihre tatsächliche Gestalt mit einem völlig anderen Platz: Sie meldete eine fehlende Gestalt, während Sie darin standen, oder schwieg, während Sie es nicht waren. Gestalten werden jetzt über den Zauber erkannt. Krieger bekommen ihre drei Haltungen, eine pro Spezialisierung, statt eines Eintrags für drei Leistenplätze auf jeder Spezialisierung. Und Paladinauren wurden unter den Gestalten gesucht, wo sie nie zu finden waren — es sind Buffs und werden als Buffs geprüft.",
    ["wn_334_cr_false"] = "Klassenerinnerung: Manche Erinnerungen ließen sich überhaupt nicht abstellen. Der Rufer verfolgte einen einzigen Segen-der-Bronze-Buff, doch dieser Zauber verleiht jeder Klasse einen anderen — zwölf von dreizehn Klassen wurde also gesagt, ihnen fehle ein Buff, den sie trugen, solange das Modul lief. Dasselbe bei den Talentversionen von Mal der Wildnis, Arkane Intelligenz, Mondkingestalt und Schattengestalt: Nur die Grundversion war bekannt, wer die Variante spielte, wurde an einen bereits vorhandenen Buff erinnert.",
    ["wn_334_cr_icons"] = "Klassenerinnerung: Sie war eine pulsierende Textzeile in der Bildschirmmitte, die auflistete, was fehlte. Jetzt ist es eine Symbolreihe, ein Symbol je fehlendem Buff, Gestalt, Haltung oder Aura, und außerhalb des Kampfes wirkt ein Linksklick den Zauber direkt, statt den Namen zu lesen und ihn auf einer Leiste zu suchen. Mittelklick blendet eine Erinnerung bis zum nächsten Ladebildschirm aus — für den Buff, den Sie heute bewusst nicht nehmen. Im Kampf ist bewusst nichts anklickbar: Eine Reihe, die scharf bliebe, würde darüber lügen, was ein Klick auslöst.",
    ["wn_334_cr_options"] = "Klassenerinnerung: Symbolgröße, Abstand, Skalierung der Reihe, Deckkraft, Beschriftung samt Schriftgröße und ein Leuchteffekt mit eigener Farbe. Die beiden Positionsregler sind weg — die Reihe wird wie alles Verschiebbare über den Mover platziert und hat einen eigenen Eintrag im Verschieben-Panel. Wer sie über die Regler verschoben hatte, dessen Position wird einmalig übernommen.",
    ["wn_334_cr_panel"] = "Klassenerinnerung: Die Einstellungsseite beginnt mit einer Live-Vorschau der Reihe, gezeichnet vom Modul selbst — jeder Regler bewegt also genau das, was Sie ansehen. Ein Klick auf ein Symbol führt zu dessen Schalter, auf die Beschriftung zu den Beschriftungsoptionen, auf die Fläche daneben zu den Größenreglern. Und die Liste der unterstützten Klassen — ein Textabsatz je Klasse — ist jetzt ein Raster, eine Zelle je verfolgtem Buff oder Gestalt, klassenfarbig, jede davon ein Schalter, den Sie für alles ausschalten können, woran Sie nicht erinnert werden möchten.",
    ["wn_334_cr_enchants"] = "Klassenerinnerung: Waffenverzauberungen wurden überhaupt nicht verfolgt. Flammenzunge, Windzorn, Erdleben, Wache des Flutenrufers und Donnerschlagschutz haben jetzt je eine eigene Erinnerung, und die beiden Riten des Lichtschmieds teilen sich eine, da sie einander ausschließen und eines von beiden genügt. Imbues sind keine Auren: Das Spiel meldete sie nie wie einen Buff — sie verschwinden nun, sobald Sie eine auftragen, statt auf eine unbeteiligte Aktualisierung zu warten.",
    ["wn_334_cr_poisons"] = "Klassenerinnerung: Schurkengifte, eine Erinnerung je Kategorie statt je Gift — tödlich und nicht tödlich. Entscheidend ist, ob die Plätze belegt sind: Es wird gezählt, wie viele Gifte der Kategorie aktiv sind, gemessen daran, wie viele Sie tatsächlich auftragen können, eins oder zwei mit Drachengehärtete Klingen. Keine Buildliste, die gepflegt werden müsste, und nichts umzustellen, wenn Sie Talente wechseln.",
    ["wn_334_cr_shields"] = "Klassenerinnerung: Schamanenschilde werden verfolgt, und Elementarumlaufbahn wird berücksichtigt statt ignoriert. Mit dem Talent tragen Sie Erdschild auf sich selbst und eines der beiden anderen, also werden beide geprüft; ohne es genügt ein einzelnes Schild. Die Erinnerung nennt die Kategorie, und ihr Symbol zeigt auf das richtige Schild für Ihre Spezialisierung — Wasser für Wiederherstellung, sonst Blitz.",
    ["wn_334_cr_context"] = "Klassenerinnerung: Sie bestimmen jetzt, wo sie erscheint — überall, nur in Dungeons und Schlachtzügen, oder nur in einer Gruppe. In Städten und Gasthäusern ist sie standardmäßig ausgeblendet, denn genau dort tragen Sie ohnehin gleich alles neu auf, und sie schweigt, während Sie tot sind, in einem Fahrzeug sitzen oder auf einem Reittier fliegen: Zustände, in denen sich nichts aus der Reihe drücken lässt.",
    ["wn_334_cr_group"] = "Klassenerinnerung: Sie kann auch die Gruppe im Blick behalten. Schalten Sie „Auch erinnern, wenn einem Gruppenmitglied ein Buff fehlt“ ein, und ein Gruppenbuff, den Sie tragen, löst weiterhin seine Erinnerung aus, solange jemand in Reichweite ihn nicht hat — genau der Fall, den sie immer verpasste, denn ihn selbst zu haben sagt nichts über den Rest der Gruppe. Gezählt werden nur Mitglieder, die den Wert überhaupt wollen, und nur außerhalb des Kampfes: Die Auren anderer Spieler sind im Kampf nicht lesbar, und Raten würde eine Erinnerung den ganzen Pull über stehen lassen. Standardmäßig aus, denn die Auren aller zu beobachten ist nicht umsonst.",
    ["wn_334_cr_perf"] = "Klassenerinnerung: Sie durchsuchte Ihre Auren und die Haltungsleiste einmal pro Sekunde, endlos, ob sich etwas geändert hatte oder nicht. Das Spiel meldet einen gewonnenen, verlorenen oder ausgelaufenen Buff bereits selbst, und die Haltungsleiste hat eigene Ereignisse — dieses Abfragen war schlicht überflüssig. Sie reagiert nun auf Ereignisse und bemerkt zusätzlich Talent- und Zauberbuchänderungen, also genau den Moment, in dem sich die Menge der betroffenen Gestalten tatsächlich verschiebt.",
    ["wn_334_uf_preview_engine"] = "Einheitenfenster: Die Vorschau in den Einstellungen war eine Attrappe. Sie zeichnete eigene Pseudoleisten aus denselben Werten, aber mit eigenem Code, und konnte daher von dem abweichen, was im Spiel herauskam — was sie auch tat. Sie wird nun von denselben Funktionen gebaut wie Ihre echten Fenster: Leistentextur, Schriften, Ränder, Infoleiste, Elementversätze, Aurenraster, Gegnerstärkungen und Bedrohung stammen alle aus der echten Engine, und die Vorschau kann nicht mehr davon abdriften.",
    ["wn_334_uf_preview_live"] = "Einheitenfenster: Die Vorschau zeigt Ihre tatsächlichen Einheiten. Existiert die Einheit — Ihr Ziel, Ihr Fokus, Ihr Begleiter —, werden die Fenster mit echten Daten gespeist und mit ECHT markiert; andernfalls greifen sie auf simulierte Werte zurück, markiert mit SIM. Ein Umschalter Anpassen / 1:1 erlaubt außerdem, die Fenster in ihrer echten Pixelgröße statt im verkleinerten Streifen zu prüfen.",
    ["wn_334_uf_texture_live"] = "Einheitenfenster: Ein Wechsel der Leistentextur bewirkte bis zum Neuladen nichts — sie wurde nur beim Erstellen des Fensters gelesen. Dasselbe galt für die Dauerzahlen auf Auren. Beides wirkt jetzt sofort, auf Ihren echten Fenstern und nicht nur in der Vorschau.",
    ["wn_334_tmkeys"] = "Mythisch+: /tm keys öffnet die Anzeigetafel für Ihre tatsächliche Gruppe — Name, Klasse, M+-Wertung und der Schlüsselstein, den jede Person trägt. Bisher erschien diese Tafel nur von selbst am Ende eines Laufs, und der einzige Befehl, der sie von Hand öffnete, zeigte Beispieldaten statt echter Leute. Ausgerechnet beim Entscheiden, welchen Schlüssel man läuft, konnte man sie nicht ansehen. Sie funktioniert außerhalb eines Dungeons, also genau dort, wo man sie braucht.",
    ["wn_334_score_roleicon"] = "Mythisch+: Jede Zeile der Anzeigetafel zeigt nun ein Rollensymbol neben dem Spezialisierungssymbol, in denselben Farben wie die Rollen-Presets und die Abzeichen in den Einstellungen. Die Spezialisierung sagt, was jemand mitgebracht hat, die Rolle sagt, was er damit tut — und eine Schlüsselsteinliste, die man vor dem Pull liest, will beides.",
    ["wn_334_score_spec"] = "Mythisch+: Ihre eigene Spezialisierung fehlte in Ihrer Zeile der Anzeigetafel — das Spiel liefert sie nicht über denselben Aufruf, den es für alle anderen verwendet. Sie wird jetzt direkt ausgelesen. Spieler mit derselben Rolle erschienen außerdem bei jedem Öffnen außerhalb eines Laufs in anderer Reihenfolge, da der Schadenswert, der sie sonst trennt, dort für alle null ist; Gleichstände fallen nun auf Schlüsselsteinstufe, dann Wertung, dann Name zurück.",
    ["wn_334_mplus_teleports"] = "Mythisch+: Dungeonteleports, die Sie sich verdient hatten, wurden als nicht erlernt angezeigt. Panel und Anzeigetafel grauten den Dungeon aus, der Tooltip meldete den Teleport als nicht verfügbar, und ein Klick auf die Zeile schrieb „nicht erlernt“ und wirkte nichts. Der verwendete Test meldet nur Zauber, die Ihnen Klasse oder Begleiter verleihen, Dungeonteleports stammen jedoch aus Erfolgen — er antwortete also bei jedem einzelnen mit Nein, ganz gleich, was tatsächlich in Ihrem Zauberbuch stand. Für Himmelsangriff gemeldet, betroffen war die gesamte Liste. Die Teleports funktionieren nun aus dem Panel heraus.",
    ["wn_334_delete_confirm"] = "Löschbestätigung: Die Funktion, die das Bestätigungswort für Sie eintippt, griff noch auf einen Teil dieses Fensters zu, den Blizzard in 11.2 entfernt hat, und funktionierte nur noch über einen Notbehelf, der den internen Namen des Fensters errät. Sie fragt das Textfeld nun auf dem unterstützten Weg beim Spiel ab, die alten Wege bleiben dahinter erhalten — sie füllt das Feld also weiter aus, was Blizzard als Nächstes auch mit diesem Fenster anstellt.",
    ["wn_334_friends_removed"] = "Kontakte: Das Skin für das Kontaktfenster wurde entfernt, zusammen mit seinem Reiter in den Einstellungen. Blizzard baut dieses Fenster in 12.1 neu auf, und das Skin arbeitete, indem es mehrere Dutzend seiner Einzelteile namentlich ansprach — Namen, die dieser Umbau nach Belieben verschieben oder umbenennen darf. Das altert nicht sanft: Am Patchtag bleibt ein halb entkleidetes Fenster zurück, bei Ihnen und nicht bei uns. Das Skin war standardmäßig ausgeschaltet; hatten Sie es an, erhält das Fenster einfach wieder Blizzards eigenes Aussehen. Die Kontakte-Schaltfläche in der Chat-Seitenleiste ist nicht betroffen.",

